window.RuqyahQuranSources.indopak={"1:1":"بِسۡمِ اللّٰہِ الرَّحۡمٰنِ الرَّحِیۡمِ ","1:2":"اَلۡحَمۡدُ لِلّٰہِ رَبِّ الۡعٰلَمِیۡنَ ۙ ","1:3":"الرَّحۡمٰنِ الرَّحِیۡمِ ۙ","1:4":"مٰلِکِ یَوۡمِ الدِّیۡنِ ؕ","1:5":"اِیَّاکَ نَعۡبُدُ وَاِیَّاکَ نَسۡتَعِیۡنُ ؕ","1:6":"اِہۡدِنَا الصِّرَاطَ الۡمُسۡتَقِیۡمَ ۙ","1:7":"صِرَاطَ الَّذِیۡنَ اَنۡعَمۡتَ عَلَیۡہِمۡ ۙ۬ غَیۡرِ الۡمَغۡضُوۡبِ عَلَیۡہِمۡ وَلَا الضَّآلِّیۡنَ ٪","2:1":"الٓـمّٓ ۚ","2:2":"ذٰلِکَ الۡکِتٰبُ لَا رَیۡبَ ۚۖۛ فِیۡہِ ۚۛ ہُدًی لِّلۡمُتَّقِیۡنَ ۙ","2:3":"الَّذِیۡنَ یُؤۡمِنُوۡنَ بِالۡغَیۡبِ وَیُقِیۡمُوۡنَ الصَّلٰوۃَ وَمِمَّا رَزَقۡنٰہُمۡ یُنۡفِقُوۡنَ ۙ","2:4":"وَالَّذِیۡنَ یُؤۡمِنُوۡنَ بِمَاۤ اُنۡزِلَ اِلَیۡکَ وَمَاۤ اُنۡزِلَ مِنۡ قَبۡلِکَ ۚ وَبِالۡاٰخِرَۃِ ہُمۡ یُوۡقِنُوۡنَ ؕ","2:5":"اُولٰٓئِکَ عَلٰی ہُدًی مِّنۡ رَّبِّہِمۡ ٭ وَاُولٰٓئِکَ ہُمُ الۡمُفۡلِحُوۡنَ ","2:14":"وَاِذَا لَقُوا الَّذِیۡنَ اٰمَنُوۡا قَالُوۡۤا اٰمَنَّا ۚۖ وَاِذَا خَلَوۡا اِلٰی شَیٰطِیۡنِہِمۡ ۙ قَالُوۡۤا اِنَّا مَعَکُمۡ ۙ اِنَّمَا نَحۡنُ مُسۡتَہۡزِءُوۡنَ ","2:20":"یَکَادُ الۡبَرۡقُ یَخۡطَفُ اَبۡصَارَہُمۡ ؕ کُلَّمَاۤ اَضَآءَ لَہُمۡ مَّشَوۡا فِیۡہِ ٭ۙ وَاِذَاۤ اَظۡلَمَ عَلَیۡہِمۡ قَامُوۡا ؕ وَلَوۡ شَآءَ اللّٰہُ لَذَہَبَ بِسَمۡعِہِمۡ وَاَبۡصَارِہِمۡ ؕ اِنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ٪","2:30":"وَاِذۡ قَالَ رَبُّکَ لِلۡمَلٰٓئِکَۃِ اِنِّیۡ جَاعِلٌ فِی الۡاَرۡضِ خَلِیۡفَۃً ؕ قَالُوۡۤا اَتَجۡعَلُ فِیۡہَا مَنۡ یُّفۡسِدُ فِیۡہَا وَیَسۡفِکُ الدِّمَآءَ ۚ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِکَ وَنُقَدِّسُ لَکَ ؕ قَالَ اِنِّیۡۤ اَعۡلَمُ مَا لَا تَعۡلَمُوۡنَ ","2:34":"وَاِذۡ قُلۡنَا لِلۡمَلٰٓئِکَۃِ اسۡجُدُوۡا لِاٰدَمَ فَسَجَدُوۡۤا اِلَّاۤ اِبۡلِیۡسَ ؕ اَبٰی وَاسۡتَکۡبَرَ ٭۫ وَکَانَ مِنَ الۡکٰفِرِیۡنَ ","2:35":"وَقُلۡنَا یٰۤاٰدَمُ اسۡکُنۡ اَنۡتَ وَزَوۡجُکَ الۡجَنَّۃَ وَکُلَا مِنۡہَا رَغَدًا حَیۡثُ شِئۡتُمَا ۪ وَلَا تَقۡرَبَا ہٰذِہِ الشَّجَرَۃَ فَتَکُوۡنَا مِنَ الظّٰلِمِیۡنَ ","2:36":"فَاَزَلَّہُمَا الشَّیۡطٰنُ عَنۡہَا فَاَخۡرَجَہُمَا مِمَّا کَانَا فِیۡہِ ۪ وَقُلۡنَا اہۡبِطُوۡا بَعۡضُکُمۡ لِبَعۡضٍ عَدُوٌّ ۚ وَلَکُمۡ فِی الۡاَرۡضِ مُسۡتَقَرٌّ وَّمَتَاعٌ اِلٰی حِیۡنٍ ","2:37":"فَتَلَقّٰۤی اٰدَمُ مِنۡ رَّبِّہٖ کَلِمٰتٍ فَتَابَ عَلَیۡہِ ؕ اِنَّہٗ ہُوَ التَّوَّابُ الرَّحِیۡمُ ","2:38":"قُلۡنَا اہۡبِطُوۡا مِنۡہَا جَمِیۡعًا ۚ فَاِمَّا یَاۡتِیَنَّکُمۡ مِّنِّیۡ ہُدًی فَمَنۡ تَبِعَ ہُدَایَ فَلَا خَوۡفٌ عَلَیۡہِمۡ وَلَا ہُمۡ یَحۡزَنُوۡنَ ","2:54":"وَاِذۡ قَالَ مُوۡسٰی لِقَوۡمِہٖ یٰقَوۡمِ اِنَّکُمۡ ظَلَمۡتُمۡ اَنۡفُسَکُمۡ بِاتِّخَاذِکُمُ الۡعِجۡلَ فَتُوۡبُوۡۤا اِلٰی بَارِئِکُمۡ فَاقۡتُلُوۡۤا اَنۡفُسَکُمۡ ؕ ذٰلِکُمۡ خَیۡرٌ لَّکُمۡ عِنۡدَ بَارِئِکُمۡ ؕ فَتَابَ عَلَیۡکُمۡ ؕ اِنَّہٗ ہُوَ التَّوَّابُ الرَّحِیۡمُ ","2:55":"وَاِذۡ قُلۡتُمۡ یٰمُوۡسٰی لَنۡ نُّؤۡمِنَ لَکَ حَتّٰی نَرَی اللّٰہَ جَہۡرَۃً فَاَخَذَتۡکُمُ الصّٰعِقَۃُ وَاَنۡتُمۡ تَنۡظُرُوۡنَ ","2:60":"وَاِذِ اسۡتَسۡقٰی مُوۡسٰی لِقَوۡمِہٖ فَقُلۡنَا اضۡرِبۡ بِّعَصَاکَ الۡحَجَرَ ؕ فَانۡفَجَرَتۡ مِنۡہُ اثۡنَتَا عَشۡرَۃَ عَیۡنًا ؕ قَدۡ عَلِمَ کُلُّ اُنَاسٍ مَّشۡرَبَہُمۡ ؕ کُلُوۡا وَاشۡرَبُوۡا مِنۡ رِّزۡقِ اللّٰہِ وَلَا تَعۡثَوۡا فِی الۡاَرۡضِ مُفۡسِدِیۡنَ ","2:69":"قَالُوا ادۡعُ لَنَا رَبَّکَ یُبَیِّنۡ لَّنَا مَا لَوۡنُہَا ؕ قَالَ اِنَّہٗ یَقُوۡلُ اِنَّہَا بَقَرَۃٌ صَفۡرَآءُ ۙ فَاقِعٌ لَّوۡنُہَا تَسُرُّ النّٰظِرِیۡنَ ","2:72":"وَاِذۡ قَتَلۡتُمۡ نَفۡسًا فَادّٰرَءۡتُمۡ فِیۡہَا ؕ وَاللّٰہُ مُخۡرِجٌ مَّا کُنۡتُمۡ تَکۡتُمُوۡنَ ۚ","2:85":"ثُمَّ اَنۡتُمۡ ہٰۤـؤُلَآءِ تَقۡتُلُوۡنَ اَنۡفُسَکُمۡ وَتُخۡرِجُوۡنَ فَرِیۡقًا مِّنۡکُمۡ مِّنۡ دِیَارِہِمۡ ۫ تَظٰہَرُوۡنَ عَلَیۡہِمۡ بِالۡاِثۡمِ وَالۡعُدۡوَانِ ؕ وَاِنۡ یَّاۡتُوۡکُمۡ اُسٰرٰی تُفٰدُوۡہُمۡ وَہُوَ مُحَرَّمٌ عَلَیۡکُمۡ اِخۡرَاجُہُمۡ ؕ اَفَتُؤۡمِنُوۡنَ بِبَعۡضِ الۡکِتٰبِ وَتَکۡفُرُوۡنَ بِبَعۡضٍ ۚ فَمَا جَزَآءُ مَنۡ یَّفۡعَلُ ذٰلِکَ مِنۡکُمۡ اِلَّا خِزۡیٌ فِی الۡحَیٰوۃِ الدُّنۡیَا ۚ وَیَوۡمَ الۡقِیٰمَۃِ یُرَدُّوۡنَ اِلٰۤی اَشَدِّ الۡعَذَابِ ؕ وَمَا اللّٰہُ بِغَافِلٍ عَمَّا تَعۡمَلُوۡنَ ","2:86":"اُولٰٓئِکَ الَّذِیۡنَ اشۡتَرَوُا الۡحَیٰوۃَ الدُّنۡیَا بِالۡاٰخِرَۃِ ۫ فَلَا یُخَفَّفُ عَنۡہُمُ الۡعَذَابُ وَلَا ہُمۡ یُنۡصَرُوۡنَ ٪ ","2:94":"قُلۡ اِنۡ کَانَتۡ لَکُمُ الدَّارُ الۡاٰخِرَۃُ عِنۡدَ اللّٰہِ خَالِصَۃً مِّنۡ دُوۡنِ النَّاسِ فَتَمَنَّوُا الۡمَوۡتَ اِنۡ کُنۡتُمۡ صٰدِقِیۡنَ ","2:95":"وَلَنۡ یَّتَمَنَّوۡہُ اَبَدًۢا بِمَا قَدَّمَتۡ اَیۡدِیۡہِمۡ ؕ وَاللّٰہُ عَلِیۡمٌۢ بِالظّٰلِمِیۡنَ ","2:102":"وَاتَّبَعُوۡا مَا تَتۡلُوا الشَّیٰطِیۡنُ عَلٰی مُلۡکِ سُلَیۡمٰنَ ۚ وَمَا کَفَرَ سُلَیۡمٰنُ وَلٰکِنَّ الشَّیٰطِیۡنَ کَفَرُوۡا یُعَلِّمُوۡنَ النَّاسَ السِّحۡرَ ٭ وَمَاۤ اُنۡزِلَ عَلَی الۡمَلَکَیۡنِ بِبَابِلَ ہَارُوۡتَ وَمَارُوۡتَ ؕ وَمَا یُعَلِّمٰنِ مِنۡ اَحَدٍ حَتّٰی یَقُوۡلَاۤ اِنَّمَا نَحۡنُ فِتۡنَۃٌ فَلَا تَکۡفُرۡ ؕ فَیَتَعَلَّمُوۡنَ مِنۡہُمَا مَا یُفَرِّقُوۡنَ بِہٖ بَیۡنَ الۡمَرۡءِ وَزَوۡجِہٖ ؕ وَمَا ہُمۡ بِضَآرِّیۡنَ بِہٖ مِنۡ اَحَدٍ اِلَّا بِاِذۡنِ اللّٰہِ ؕ وَیَتَعَلَّمُوۡنَ مَا یَضُرُّہُمۡ وَلَا یَنۡفَعُہُمۡ ؕ وَلَقَدۡ عَلِمُوۡا لَمَنِ اشۡتَرٰىہُ مَا لَہٗ فِی الۡاٰخِرَۃِ مِنۡ خَلَاقٍ ۟ؕ وَلَبِئۡسَ مَا شَرَوۡا بِہٖۤ اَنۡفُسَہُمۡ ؕ لَوۡ کَانُوۡا یَعۡلَمُوۡنَ ","2:109":"وَدَّ کَثِیۡرٌ مِّنۡ اَہۡلِ الۡکِتٰبِ لَوۡ یَرُدُّوۡنَکُمۡ مِّنۡۢ بَعۡدِ اِیۡمَانِکُمۡ کُفَّارًا ۚۖ حَسَدًا مِّنۡ عِنۡدِ اَنۡفُسِہِمۡ مِّنۡۢ بَعۡدِ مَا تَبَیَّنَ لَہُمُ الۡحَقُّ ۚ فَاعۡفُوۡا وَاصۡفَحُوۡا حَتّٰی یَاۡتِیَ اللّٰہُ بِاَمۡرِہٖ ؕ اِنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ","2:149":"وَمِنۡ حَیۡثُ خَرَجۡتَ فَوَلِّ وَجۡہَکَ شَطۡرَ الۡمَسۡجِدِ الۡحَرَامِ ؕ وَاِنَّہٗ لَلۡحَقُّ مِنۡ رَّبِّکَ ؕ وَمَا اللّٰہُ بِغَافِلٍ عَمَّا تَعۡمَلُوۡنَ ","2:150":"وَمِنۡ حَیۡثُ خَرَجۡتَ فَوَلِّ وَجۡہَکَ شَطۡرَ الۡمَسۡجِدِ الۡحَرَامِ ؕ وَحَیۡثُ مَا کُنۡتُمۡ فَوَلُّوۡا وُجُوۡہَکُمۡ شَطۡرَہٗ ۙ لِئَلَّا یَکُوۡنَ لِلنَّاسِ عَلَیۡکُمۡ حُجَّۃٌ ٭ۙ اِلَّا الَّذِیۡنَ ظَلَمُوۡا مِنۡہُمۡ ٭ فَلَا تَخۡشَوۡہُمۡ وَاخۡشَوۡنِیۡ ٭ وَلِاُتِمَّ نِعۡمَتِیۡ عَلَیۡکُمۡ وَلَعَلَّکُمۡ تَہۡتَدُوۡنَ ۙۛ","2:161":"اِنَّ الَّذِیۡنَ کَفَرُوۡا وَمَاتُوۡا وَہُمۡ کُفَّارٌ اُولٰٓئِکَ عَلَیۡہِمۡ لَعۡنَۃُ اللّٰہِ وَالۡمَلٰٓئِکَۃِ وَالنَّاسِ اَجۡمَعِیۡنَ ۙ","2:162":"خٰلِدِیۡنَ فِیۡہَا ۚ لَا یُخَفَّفُ عَنۡہُمُ الۡعَذَابُ وَلَا ہُمۡ یُنۡظَرُوۡنَ ","2:163":"وَاِلٰـہُکُمۡ اِلٰہٌ وَّاحِدٌ ۚ لَاۤ اِلٰہَ اِلَّا ہُوَ الرَّحۡمٰنُ الرَّحِیۡمُ ٪","2:164":"اِنَّ فِیۡ خَلۡقِ السَّمٰوٰتِ وَالۡاَرۡضِ وَاخۡتِلَافِ الَّیۡلِ وَالنَّہَارِ وَالۡفُلۡکِ الَّتِیۡ تَجۡرِیۡ فِی الۡبَحۡرِ بِمَا یَنۡفَعُ النَّاسَ وَمَاۤ اَنۡزَلَ اللّٰہُ مِنَ السَّمَآءِ مِنۡ مَّآءٍ فَاَحۡیَا بِہِ الۡاَرۡضَ بَعۡدَ مَوۡتِہَا وَبَثَّ فِیۡہَا مِنۡ کُلِّ دَآبَّۃٍ ۪ وَّتَصۡرِیۡفِ الرِّیٰحِ وَالسَّحَابِ الۡمُسَخَّرِ بَیۡنَ السَّمَآءِ وَالۡاَرۡضِ لَاٰیٰتٍ لِّقَوۡمٍ یَّعۡقِلُوۡنَ ","2:168":"یٰۤاَیُّہَا النَّاسُ کُلُوۡا مِمَّا فِی الۡاَرۡضِ حَلٰلًا طَیِّبًا ۫ۖ وَّلَا تَتَّبِعُوۡا خُطُوٰتِ الشَّیۡطٰنِ ؕ اِنَّہٗ لَکُمۡ عَدُوٌّ مُّبِیۡنٌ ","2:169":"اِنَّمَا یَاۡمُرُکُمۡ بِالسُّوۡٓءِ وَالۡفَحۡشَآءِ وَاَنۡ تَقُوۡلُوۡا عَلَی اللّٰہِ مَا لَا تَعۡلَمُوۡنَ ","2:178":"یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا کُتِبَ عَلَیۡکُمُ الۡقِصَاصُ فِی الۡقَتۡلٰی ؕ اَلۡحُرُّ بِالۡحُرِّ وَالۡعَبۡدُ بِالۡعَبۡدِ وَالۡاُنۡثٰی بِالۡاُنۡثٰی ؕ فَمَنۡ عُفِیَ لَہٗ مِنۡ اَخِیۡہِ شَیۡءٌ فَاتِّبَاعٌۢ بِالۡمَعۡرُوۡفِ وَاَدَآءٌ اِلَیۡہِ بِاِحۡسَانٍ ؕ ذٰلِکَ تَخۡفِیۡفٌ مِّنۡ رَّبِّکُمۡ وَرَحۡمَۃٌ ؕ فَمَنِ اعۡتَدٰی بَعۡدَ ذٰلِکَ فَلَہٗ عَذَابٌ اَلِیۡمٌ ","2:190":"وَقَاتِلُوۡا فِیۡ سَبِیۡلِ اللّٰہِ الَّذِیۡنَ یُقَاتِلُوۡنَکُمۡ وَلَا تَعۡتَدُوۡا ؕ اِنَّ اللّٰہَ لَا یُحِبُّ الۡمُعۡتَدِیۡنَ ","2:191":"وَاقۡتُلُوۡہُمۡ حَیۡثُ ثَقِفۡتُمُوۡہُمۡ وَاَخۡرِجُوۡہُمۡ مِّنۡ حَیۡثُ اَخۡرَجُوۡکُمۡ وَالۡفِتۡنَۃُ اَشَدُّ مِنَ الۡقَتۡلِ ۚ وَلَا تُقٰتِلُوۡہُمۡ عِنۡدَ الۡمَسۡجِدِ الۡحَرَامِ حَتّٰی یُقٰتِلُوۡکُمۡ فِیۡہِ ۚ فَاِنۡ قٰتَلُوۡکُمۡ فَاقۡتُلُوۡہُمۡ ؕ کَذٰلِکَ جَزَآءُ الۡکٰفِرِیۡنَ ","2:192":"فَاِنِ انۡتَہَوۡا فَاِنَّ اللّٰہَ غَفُوۡرٌ رَّحِیۡمٌ ","2:193":"وَقٰتِلُوۡہُمۡ حَتّٰی لَا تَکُوۡنَ فِتۡنَۃٌ وَّیَکُوۡنَ الدِّیۡنُ لِلّٰہِ ؕ فَاِنِ انۡتَہَوۡا فَلَا عُدۡوَانَ اِلَّا عَلَی الظّٰلِمِیۡنَ ","2:205":"وَاِذَا تَوَلّٰی سَعٰی فِی الۡاَرۡضِ لِیُفۡسِدَ فِیۡہَا وَیُہۡلِکَ الۡحَرۡثَ وَالنَّسۡلَ ؕ وَاللّٰہُ لَا یُحِبُّ الۡفَسَادَ ","2:208":"یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوا ادۡخُلُوۡا فِی السِّلۡمِ کَآفَّۃً ۪ وَلَا تَتَّبِعُوۡا خُطُوٰتِ الشَّیۡطٰنِ ؕ اِنَّہٗ لَکُمۡ عَدُوٌّ مُّبِیۡنٌ ","2:216":"کُتِبَ عَلَیۡکُمُ الۡقِتَالُ وَہُوَ کُرۡہٌ لَّکُمۡ ۚ وَعَسٰۤی اَنۡ تَکۡرَہُوۡا شَیۡئًا وَّہُوَ خَیۡرٌ لَّکُمۡ ۚ وَعَسٰۤی اَنۡ تُحِبُّوۡا شَیۡئًا وَّہُوَ شَرٌّ لَّکُمۡ ؕ وَاللّٰہُ یَعۡلَمُ وَاَنۡتُمۡ لَا تَعۡلَمُوۡنَ ٪","2:217":"یَسۡـَٔلُوۡنَکَ عَنِ الشَّہۡرِ الۡحَرَامِ قِتَالٍ فِیۡہِ ؕ قُلۡ قِتَالٌ فِیۡہِ کَبِیۡرٌ ؕ وَصَدٌّ عَنۡ سَبِیۡلِ اللّٰہِ وَکُفۡرٌۢ بِہٖ وَالۡمَسۡجِدِ الۡحَرَامِ ٭ وَاِخۡرَاجُ اَہۡلِہٖ مِنۡہُ اَکۡبَرُ عِنۡدَ اللّٰہِ ۚ وَالۡفِتۡنَۃُ اَکۡبَرُ مِنَ الۡقَتۡلِ ؕ وَلَا یَزَالُوۡنَ یُقَاتِلُوۡنَکُمۡ حَتّٰی یَرُدُّوۡکُمۡ عَنۡ دِیۡنِکُمۡ اِنِ اسۡتَطَاعُوۡا ؕ وَمَنۡ یَّرۡتَدِدۡ مِنۡکُمۡ عَنۡ دِیۡنِہٖ فَیَمُتۡ وَہُوَ کَافِرٌ فَاُولٰٓئِکَ حَبِطَتۡ اَعۡمَالُہُمۡ فِی الدُّنۡیَا وَالۡاٰخِرَۃِ ۚ وَاُولٰٓئِکَ اَصۡحٰبُ النَّارِ ۚ ہُمۡ فِیۡہَا خٰلِدُوۡنَ ","2:220":"فِی الدُّنۡیَا وَالۡاٰخِرَۃِ ؕ وَیَسۡـَٔلُوۡنَکَ عَنِ الۡیَتٰمٰی ؕ قُلۡ اِصۡلَاحٌ لَّہُمۡ خَیۡرٌ ؕ وَاِنۡ تُخَالِطُوۡہُمۡ فَاِخۡوَانُکُمۡ ؕ وَاللّٰہُ یَعۡلَمُ الۡمُفۡسِدَ مِنَ الۡمُصۡلِحِ ؕ وَلَوۡ شَآءَ اللّٰہُ لَاَعۡنَتَکُمۡ ؕ اِنَّ اللّٰہَ عَزِیۡزٌ حَکِیۡمٌ ","2:221":"وَلَا تَنۡکِحُوا الۡمُشۡرِکٰتِ حَتّٰی یُؤۡمِنَّ ؕ وَلَاَمَۃٌ مُّؤۡمِنَۃٌ خَیۡرٌ مِّنۡ مُّشۡرِکَۃٍ وَّلَوۡ اَعۡجَبَتۡکُمۡ ۚ وَلَا تُنۡکِحُوا الۡمُشۡرِکِیۡنَ حَتّٰی یُؤۡمِنُوۡا ؕ وَلَعَبۡدٌ مُّؤۡمِنٌ خَیۡرٌ مِّنۡ مُّشۡرِکٍ وَّلَوۡ اَعۡجَبَکُمۡ ؕ اُولٰٓئِکَ یَدۡعُوۡنَ اِلَی النَّارِ ۚۖ وَاللّٰہُ یَدۡعُوۡۤا اِلَی الۡجَنَّۃِ وَالۡمَغۡفِرَۃِ بِاِذۡنِہٖ ۚ وَیُبَیِّنُ اٰیٰتِہٖ لِلنَّاسِ لَعَلَّہُمۡ یَتَذَکَّرُوۡنَ ٪","2:222":"وَیَسۡـَٔلُوۡنَکَ عَنِ الۡمَحِیۡضِ ؕ قُلۡ ہُوَ اَذًی ۙ فَاعۡتَزِلُوا النِّسَآءَ فِی الۡمَحِیۡضِ ۙ وَلَا تَقۡرَبُوۡہُنَّ حَتّٰی یَطۡہُرۡنَ ۚ فَاِذَا تَطَہَّرۡنَ فَاۡتُوۡہُنَّ مِنۡ حَیۡثُ اَمَرَکُمُ اللّٰہُ ؕ اِنَّ اللّٰہَ یُحِبُّ التَّوَّابِیۡنَ وَیُحِبُّ الۡمُتَطَہِّرِیۡنَ ","2:243":"اَلَمۡ تَرَ اِلَی الَّذِیۡنَ خَرَجُوۡا مِنۡ دِیَارِہِمۡ وَہُمۡ اُلُوۡفٌ حَذَرَ الۡمَوۡتِ ۪ فَقَالَ لَہُمُ اللّٰہُ مُوۡتُوۡا ۟ ثُمَّ اَحۡیَاہُمۡ ؕ اِنَّ اللّٰہَ لَذُوۡ فَضۡلٍ عَلَی النَّاسِ وَلٰکِنَّ اَکۡثَرَ النَّاسِ لَا یَشۡکُرُوۡنَ ","2:247":"وَقَالَ لَہُمۡ نَبِیُّہُمۡ اِنَّ اللّٰہَ قَدۡ بَعَثَ لَکُمۡ طَالُوۡتَ مَلِکًا ؕ قَالُوۡۤا اَنّٰی یَکُوۡنُ لَہُ الۡمُلۡکُ عَلَیۡنَا وَنَحۡنُ اَحَقُّ بِالۡمُلۡکِ مِنۡہُ وَلَمۡ یُؤۡتَ سَعَۃً مِّنَ الۡمَالِ ؕ قَالَ اِنَّ اللّٰہَ اصۡطَفٰىہُ عَلَیۡکُمۡ وَزَادَہٗ بَسۡطَۃً فِی الۡعِلۡمِ وَالۡجِسۡمِ ؕ وَاللّٰہُ یُؤۡتِیۡ مُلۡکَہٗ مَنۡ یَّشَآءُ ؕ وَاللّٰہُ وَاسِعٌ عَلِیۡمٌ ","2:248":"وَقَالَ لَہُمۡ نَبِیُّہُمۡ اِنَّ اٰیَۃَ مُلۡکِہٖۤ اَنۡ یَّاۡتِیَکُمُ التَّابُوۡتُ فِیۡہِ سَکِیۡنَۃٌ مِّنۡ رَّبِّکُمۡ وَبَقِیَّۃٌ مِّمَّا تَرَکَ اٰلُ مُوۡسٰی وَاٰلُ ہٰرُوۡنَ تَحۡمِلُہُ الۡمَلٰٓئِکَۃُ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً لَّکُمۡ اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ ٪","2:250":"وَلَمَّا بَرَزُوۡا لِجَالُوۡتَ وَجُنُوۡدِہٖ قَالُوۡا رَبَّنَاۤ اَفۡرِغۡ عَلَیۡنَا صَبۡرًا وَّثَبِّتۡ اَقۡدَامَنَا وَانۡصُرۡنَا عَلَی الۡقَوۡمِ الۡکٰفِرِیۡنَ ؕ","2:251":"فَہَزَمُوۡہُمۡ بِاِذۡنِ اللّٰہِ ۟ۙ وَقَتَلَ دَاوٗدُ جَالُوۡتَ وَاٰتٰىہُ اللّٰہُ الۡمُلۡکَ وَالۡحِکۡمَۃَ وَعَلَّمَہٗ مِمَّا یَشَآءُ ؕ وَلَوۡلَا دَفۡعُ اللّٰہِ النَّاسَ بَعۡضَہُمۡ بِبَعۡضٍ ۙ لَّفَسَدَتِ الۡاَرۡضُ وَلٰکِنَّ اللّٰہَ ذُوۡ فَضۡلٍ عَلَی الۡعٰلَمِیۡنَ ","2:255":"اَللّٰہُ لَاۤ اِلٰہَ اِلَّا ہُوَ ۚ اَلۡحَیُّ الۡقَیُّوۡمُ ۬ۚ لَا تَاۡخُذُہٗ سِنَۃٌ وَّلَا نَوۡمٌ ؕ لَہٗ مَا فِی السَّمٰوٰتِ وَمَا فِی الۡاَرۡضِ ؕ مَنۡ ذَا الَّذِیۡ یَشۡفَعُ عِنۡدَہٗۤ اِلَّا بِاِذۡنِہٖ ؕ یَعۡلَمُ مَا بَیۡنَ اَیۡدِیۡہِمۡ وَمَا خَلۡفَہُمۡ ۚ وَلَا یُحِیۡطُوۡنَ بِشَیۡءٍ مِّنۡ عِلۡمِہٖۤ اِلَّا بِمَا شَآءَ ۚ وَسِعَ کُرۡسِیُّہُ السَّمٰوٰتِ وَالۡاَرۡضَ ۚ وَلَا یَـُٔوۡدُہٗ حِفۡظُہُمَا ۚ وَہُوَ الۡعَلِیُّ الۡعَظِیۡمُ ","2:259":"اَوۡ کَالَّذِیۡ مَرَّ عَلٰی قَرۡیَۃٍ وَّہِیَ خَاوِیَۃٌ عَلٰی عُرُوۡشِہَا ۚ قَالَ اَنّٰی یُحۡیٖ ہٰذِہِ اللّٰہُ بَعۡدَ مَوۡتِہَا ۚ فَاَمَاتَہُ اللّٰہُ مِائَۃَ عَامٍ ثُمَّ بَعَثَہٗ ؕ قَالَ کَمۡ لَبِثۡتَ ؕ قَالَ لَبِثۡتُ یَوۡمًا اَوۡ بَعۡضَ یَوۡمٍ ؕ قَالَ بَلۡ لَّبِثۡتَ مِائَۃَ عَامٍ فَانۡظُرۡ اِلٰی طَعَامِکَ وَشَرَابِکَ لَمۡ یَتَسَنَّہۡ ۚ وَانۡظُرۡ اِلٰی حِمَارِکَ وَلِنَجۡعَلَکَ اٰیَۃً لِّلنَّاسِ وَانۡظُرۡ اِلَی الۡعِظَامِ کَیۡفَ نُنۡشِزُہَا ثُمَّ نَکۡسُوۡہَا لَحۡمًا ؕ فَلَمَّا تَبَیَّنَ لَہٗ ۙ قَالَ اَعۡلَمُ اَنَّ اللّٰہَ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرٌ ","2:266":"اَیَوَدُّ اَحَدُکُمۡ اَنۡ تَکُوۡنَ لَہٗ جَنَّۃٌ مِّنۡ نَّخِیۡلٍ وَّاَعۡنَابٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ۙ لَہٗ فِیۡہَا مِنۡ کُلِّ الثَّمَرٰتِ ۙ وَاَصَابَہُ الۡکِبَرُ وَلَہٗ ذُرِّیَّۃٌ ضُعَفَآءُ ۪ۖ فَاَصَابَہَاۤ اِعۡصَارٌ فِیۡہِ نَارٌ فَاحۡتَرَقَتۡ ؕ کَذٰلِکَ یُبَیِّنُ اللّٰہُ لَکُمُ الۡاٰیٰتِ لَعَلَّکُمۡ تَتَفَکَّرُوۡنَ ٪","2:268":"اَلشَّیۡطٰنُ یَعِدُکُمُ الۡفَقۡرَ وَیَاۡمُرُکُمۡ بِالۡفَحۡشَآءِ ۚ وَاللّٰہُ یَعِدُکُمۡ مَّغۡفِرَۃً مِّنۡہُ وَفَضۡلًا ؕ وَاللّٰہُ وَاسِعٌ عَلِیۡمٌ ۖۙ","2:269":"یُّؤۡتِی الۡحِکۡمَۃَ مَنۡ یَّشَآءُ ۚ وَمَنۡ یُّؤۡتَ الۡحِکۡمَۃَ فَقَدۡ اُوۡتِیَ خَیۡرًا کَثِیۡرًا ؕ وَمَا یَذَّکَّرُ اِلَّاۤ اُولُوا الۡاَلۡبَابِ ","2:275":"اَلَّذِیۡنَ یَاۡکُلُوۡنَ الرِّبٰوا لَا یَقُوۡمُوۡنَ اِلَّا کَمَا یَقُوۡمُ الَّذِیۡ یَتَخَبَّطُہُ الشَّیۡطٰنُ مِنَ الۡمَسِّ ؕ ذٰلِکَ بِاَنَّہُمۡ قَالُوۡۤا اِنَّمَا الۡبَیۡعُ مِثۡلُ الرِّبٰوا ۘ وَاَحَلَّ اللّٰہُ الۡبَیۡعَ وَحَرَّمَ الرِّبٰوا ؕ فَمَنۡ جَآءَہٗ مَوۡعِظَۃٌ مِّنۡ رَّبِّہٖ فَانۡتَہٰی فَلَہٗ مَا سَلَفَ ؕ وَاَمۡرُہٗۤ اِلَی اللّٰہِ ؕ وَمَنۡ عَادَ فَاُولٰٓئِکَ اَصۡحٰبُ النَّارِ ۚ ہُمۡ فِیۡہَا خٰلِدُوۡنَ ","2:285":"اٰمَنَ الرَّسُوۡلُ بِمَاۤ اُنۡزِلَ اِلَیۡہِ مِنۡ رَّبِّہٖ وَالۡمُؤۡمِنُوۡنَ ؕ کُلٌّ اٰمَنَ بِاللّٰہِ وَمَلٰٓئِکَتِہٖ وَکُتُبِہٖ وَرُسُلِہٖ ۟ لَا نُفَرِّقُ بَیۡنَ اَحَدٍ مِّنۡ رُّسُلِہٖ ۟ وَقَالُوۡا سَمِعۡنَا وَاَطَعۡنَا ٭۫ غُفۡرَانَکَ رَبَّنَا وَاِلَیۡکَ الۡمَصِیۡرُ ","2:286":"لَا یُکَلِّفُ اللّٰہُ نَفۡسًا اِلَّا وُسۡعَہَا ؕ لَہَا مَا کَسَبَتۡ وَعَلَیۡہَا مَا اکۡتَسَبَتۡ ؕ رَبَّنَا لَا تُؤَاخِذۡنَاۤ اِنۡ نَّسِیۡنَاۤ اَوۡ اَخۡطَاۡنَا ۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَیۡنَاۤ اِصۡرًا کَمَا حَمَلۡتَہٗ عَلَی الَّذِیۡنَ مِنۡ قَبۡلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَۃَ لَنَا بِہٖ ۚ وَاعۡفُ عَنَّا ٝ وَاغۡفِرۡ لَنَا ٝ وَارۡحَمۡنَا ٝ اَنۡتَ مَوۡلٰىنَا فَانۡصُرۡنَا عَلَی الۡقَوۡمِ الۡکٰفِرِیۡنَ ٪","3:2":"اللّٰہُ لَاۤ اِلٰہَ اِلَّا ہُوَ ۙ الۡحَیُّ الۡقَیُّوۡمُ ؕ ","3:12":"قُلۡ لِّلَّذِیۡنَ کَفَرُوۡا سَتُغۡلَبُوۡنَ وَتُحۡشَرُوۡنَ اِلٰی جَہَنَّمَ ؕ وَبِئۡسَ الۡمِہَادُ ","3:13":"قَدۡ کَانَ لَکُمۡ اٰیَۃٌ فِیۡ فِئَتَیۡنِ الۡتَقَتَا ؕ فِئَۃٌ تُقَاتِلُ فِیۡ سَبِیۡلِ اللّٰہِ وَاُخۡرٰی کَافِرَۃٌ یَّرَوۡنَہُمۡ مِّثۡلَیۡہِمۡ رَاۡیَ الۡعَیۡنِ ؕ وَاللّٰہُ یُؤَیِّدُ بِنَصۡرِہٖ مَنۡ یَّشَآءُ ؕ اِنَّ فِیۡ ذٰلِکَ لَعِبۡرَۃً لِّاُولِی الۡاَبۡصَارِ ","3:14":"زُیِّنَ لِلنَّاسِ حُبُّ الشَّہَوٰتِ مِنَ النِّسَآءِ وَالۡبَنِیۡنَ وَالۡقَنَاطِیۡرِ الۡمُقَنۡطَرَۃِ مِنَ الذَّہَبِ وَالۡفِضَّۃِ وَالۡخَیۡلِ الۡمُسَوَّمَۃِ وَالۡاَنۡعَامِ وَالۡحَرۡثِ ؕ ذٰلِکَ مَتَاعُ الۡحَیٰوۃِ الدُّنۡیَا ۚ وَاللّٰہُ عِنۡدَہٗ حُسۡنُ الۡمَاٰبِ ","3:18":"شَہِدَ اللّٰہُ اَنَّہٗ لَاۤ اِلٰہَ اِلَّا ہُوَ ۙ وَالۡمَلٰٓئِکَۃُ وَاُولُوا الۡعِلۡمِ قَآئِمًۢا بِالۡقِسۡطِ ؕ لَاۤ اِلٰہَ اِلَّا ہُوَ الۡعَزِیۡزُ الۡحَکِیۡمُ ؕ ","3:19":"اِنَّ الدِّیۡنَ عِنۡدَ اللّٰہِ الۡاِسۡلَامُ ۟ وَمَا اخۡتَلَفَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ اِلَّا مِنۡۢ بَعۡدِ مَا جَآءَہُمُ الۡعِلۡمُ بَغۡیًۢا بَیۡنَہُمۡ ؕ وَمَنۡ یَّکۡفُرۡ بِاٰیٰتِ اللّٰہِ فَاِنَّ اللّٰہَ سَرِیۡعُ الۡحِسَابِ ","3:27":"تُوۡلِجُ الَّیۡلَ فِی النَّہَارِ وَتُوۡلِجُ النَّہَارَ فِی الَّیۡلِ ۫ وَتُخۡرِجُ الۡحَیَّ مِنَ الۡمَیِّتِ وَتُخۡرِجُ الۡمَیِّتَ مِنَ الۡحَیِّ ۫ وَتَرۡزُقُ مَنۡ تَشَآءُ بِغَیۡرِ حِسَابٍ ","3:36":"فَلَمَّا وَضَعَتۡہَا قَالَتۡ رَبِّ اِنِّیۡ وَضَعۡتُہَاۤ اُنۡثٰی ؕ وَاللّٰہُ اَعۡلَمُ بِمَا وَضَعَتۡ ؕ وَلَیۡسَ الذَّکَرُ کَالۡاُنۡثٰی ۚ وَاِنِّیۡ سَمَّیۡتُہَا مَرۡیَمَ وَاِنِّیۡۤ اُعِیۡذُہَا بِکَ وَذُرِّیَّتَہَا مِنَ الشَّیۡطٰنِ الرَّجِیۡمِ ","3:111":"لَنۡ یَّضُرُّوۡکُمۡ اِلَّاۤ اَذًی ؕ وَاِنۡ یُّقَاتِلُوۡکُمۡ یُوَلُّوۡکُمُ الۡاَدۡبَارَ ۟ ثُمَّ لَا یُنۡصَرُوۡنَ ","3:112":"ضُرِبَتۡ عَلَیۡہِمُ الذِّلَّۃُ اَیۡنَ مَا ثُقِفُوۡۤا اِلَّا بِحَبۡلٍ مِّنَ اللّٰہِ وَحَبۡلٍ مِّنَ النَّاسِ وَبَآءُوۡ بِغَضَبٍ مِّنَ اللّٰہِ وَضُرِبَتۡ عَلَیۡہِمُ الۡمَسۡکَنَۃُ ؕ ذٰلِکَ بِاَنَّہُمۡ کَانُوۡا یَکۡفُرُوۡنَ بِاٰیٰتِ اللّٰہِ وَیَقۡتُلُوۡنَ الۡاَنۡۢبِیَآءَ بِغَیۡرِ حَقٍّ ؕ ذٰلِکَ بِمَا عَصَوۡا وَّکَانُوۡا یَعۡتَدُوۡنَ ٭ ","3:119":"ہٰۤاَنۡتُمۡ اُولَآءِ تُحِبُّوۡنَہُمۡ وَلَا یُحِبُّوۡنَکُمۡ وَتُؤۡمِنُوۡنَ بِالۡکِتٰبِ کُلِّہٖ ۚ وَاِذَا لَقُوۡکُمۡ قَالُوۡۤا اٰمَنَّا ۚ٭ۖ وَاِذَا خَلَوۡا عَضُّوۡا عَلَیۡکُمُ الۡاَنَامِلَ مِنَ الۡغَیۡظِ ؕ قُلۡ مُوۡتُوۡا بِغَیۡظِکُمۡ ؕ اِنَّ اللّٰہَ عَلِیۡمٌۢ بِذَاتِ الصُّدُوۡرِ ","3:120":"اِنۡ تَمۡسَسۡکُمۡ حَسَنَۃٌ تَسُؤۡہُمۡ ۫ وَاِنۡ تُصِبۡکُمۡ سَیِّئَۃٌ یَّفۡرَحُوۡا بِہَا ؕ وَاِنۡ تَصۡبِرُوۡا وَتَتَّقُوۡا لَا یَضُرُّکُمۡ کَیۡدُہُمۡ شَیۡـًٔا ؕ اِنَّ اللّٰہَ بِمَا یَعۡمَلُوۡنَ مُحِیۡطٌ ٪ ","3:121":"وَاِذۡ غَدَوۡتَ مِنۡ اَہۡلِکَ تُبَوِّئُ الۡمُؤۡمِنِیۡنَ مَقَاعِدَ لِلۡقِتَالِ ؕ وَاللّٰہُ سَمِیۡعٌ عَلِیۡمٌ ۙ ","3:122":"اِذۡ ہَمَّتۡ طَّآئِفَتٰنِ مِنۡکُمۡ اَنۡ تَفۡشَلَا ۙ وَاللّٰہُ وَلِیُّہُمَا ؕ وَعَلَی اللّٰہِ فَلۡیَتَوَکَّلِ الۡمُؤۡمِنُوۡنَ ","3:123":"وَلَقَدۡ نَصَرَکُمُ اللّٰہُ بِبَدۡرٍ وَّاَنۡتُمۡ اَذِلَّۃٌ ۚ فَاتَّقُوا اللّٰہَ لَعَلَّکُمۡ تَشۡکُرُوۡنَ ","3:124":"اِذۡ تَقُوۡلُ لِلۡمُؤۡمِنِیۡنَ اَلَنۡ یَّکۡفِیَکُمۡ اَنۡ یُّمِدَّکُمۡ رَبُّکُمۡ بِثَلٰثَۃِ اٰلٰفٍ مِّنَ الۡمَلٰٓئِکَۃِ مُنۡزَلِیۡنَ ؕ ","3:125":"بَلٰۤی ۙ اِنۡ تَصۡبِرُوۡا وَتَتَّقُوۡا وَیَاۡتُوۡکُمۡ مِّنۡ فَوۡرِہِمۡ ہٰذَا یُمۡدِدۡکُمۡ رَبُّکُمۡ بِخَمۡسَۃِ اٰلٰفٍ مِّنَ الۡمَلٰٓئِکَۃِ مُسَوِّمِیۡنَ ","3:126":"وَمَا جَعَلَہُ اللّٰہُ اِلَّا بُشۡرٰی لَکُمۡ وَلِتَطۡمَئِنَّ قُلُوۡبُکُمۡ بِہٖ ؕ وَمَا النَّصۡرُ اِلَّا مِنۡ عِنۡدِ اللّٰہِ الۡعَزِیۡزِ الۡحَکِیۡمِ ۙ ","3:127":"لِیَقۡطَعَ طَرَفًا مِّنَ الَّذِیۡنَ کَفَرُوۡۤا اَوۡ یَکۡبِتَہُمۡ فَیَنۡقَلِبُوۡا خَآئِبِیۡنَ ","3:135":"وَالَّذِیۡنَ اِذَا فَعَلُوۡا فَاحِشَۃً اَوۡ ظَلَمُوۡۤا اَنۡفُسَہُمۡ ذَکَرُوا اللّٰہَ فَاسۡتَغۡفَرُوۡا لِذُنُوۡبِہِمۡ ۪ وَمَنۡ یَّغۡفِرُ الذُّنُوۡبَ اِلَّا اللّٰہُ ۪۟ وَلَمۡ یُصِرُّوۡا عَلٰی مَا فَعَلُوۡا وَہُمۡ یَعۡلَمُوۡنَ ","3:143":"وَلَقَدۡ کُنۡتُمۡ تَمَنَّوۡنَ الۡمَوۡتَ مِنۡ قَبۡلِ اَنۡ تَلۡقَوۡہُ ۪ فَقَدۡ رَاَیۡتُمُوۡہُ وَاَنۡتُمۡ تَنۡظُرُوۡنَ ٪","3:154":"ثُمَّ اَنۡزَلَ عَلَیۡکُمۡ مِّنۡۢ بَعۡدِ الۡغَمِّ اَمَنَۃً نُّعَاسًا یَّغۡشٰی طَآئِفَۃً مِّنۡکُمۡ ۙ وَطَآئِفَۃٌ قَدۡ اَہَمَّتۡہُمۡ اَنۡفُسُہُمۡ یَظُنُّوۡنَ بِاللّٰہِ غَیۡرَ الۡحَقِّ ظَنَّ الۡجَاہِلِیَّۃِ ؕ یَقُوۡلُوۡنَ ہَلۡ لَّنَا مِنَ الۡاَمۡرِ مِنۡ شَیۡءٍ ؕ قُلۡ اِنَّ الۡاَمۡرَ کُلَّہٗ لِلّٰہِ ؕ یُخۡفُوۡنَ فِیۡۤ اَنۡفُسِہِمۡ مَّا لَا یُبۡدُوۡنَ لَکَ ؕ یَقُوۡلُوۡنَ لَوۡ کَانَ لَنَا مِنَ الۡاَمۡرِ شَیۡءٌ مَّا قُتِلۡنَا ہٰہُنَا ؕ قُلۡ لَّوۡ کُنۡتُمۡ فِیۡ بُیُوۡتِکُمۡ لَبَرَزَ الَّذِیۡنَ کُتِبَ عَلَیۡہِمُ الۡقَتۡلُ اِلٰی مَضَاجِعِہِمۡ ۚ وَلِیَبۡتَلِیَ اللّٰہُ مَا فِیۡ صُدُوۡرِکُمۡ وَلِیُمَحِّصَ مَا فِیۡ قُلُوۡبِکُمۡ ؕ وَاللّٰہُ عَلِیۡمٌۢ بِذَاتِ الصُّدُوۡرِ ","3:175":"اِنَّمَا ذٰلِکُمُ الشَّیۡطٰنُ یُخَوِّفُ اَوۡلِیَآءَہٗ ۪ فَلَا تَخَافُوۡہُمۡ وَخَافُوۡنِ اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ ","3:181":"لَقَدۡ سَمِعَ اللّٰہُ قَوۡلَ الَّذِیۡنَ قَالُوۡۤا اِنَّ اللّٰہَ فَقِیۡرٌ وَّنَحۡنُ اَغۡنِیَآءُ ۘ سَنَکۡتُبُ مَا قَالُوۡا وَقَتۡلَہُمُ الۡاَنۡۢبِیَآءَ بِغَیۡرِ حَقٍّ ۙ وَّنَقُوۡلُ ذُوۡقُوۡا عَذَابَ الۡحَرِیۡقِ ","3:197":"مَتَاعٌ قَلِیۡلٌ ۟ ثُمَّ مَاۡوٰىہُمۡ جَہَنَّمُ ؕ وَبِئۡسَ الۡمِہَادُ ","4:15":"وَالّٰتِیۡ یَاۡتِیۡنَ الۡفَاحِشَۃَ مِنۡ نِّسَآئِکُمۡ فَاسۡتَشۡہِدُوۡا عَلَیۡہِنَّ اَرۡبَعَۃً مِّنۡکُمۡ ۚ فَاِنۡ شَہِدُوۡا فَاَمۡسِکُوۡہُنَّ فِی الۡبُیُوۡتِ حَتّٰی یَتَوَفّٰہُنَّ الۡمَوۡتُ اَوۡ یَجۡعَلَ اللّٰہُ لَہُنَّ سَبِیۡلًا ","4:16":"وَالَّذٰنِ یَاۡتِیٰنِہَا مِنۡکُمۡ فَاٰذُوۡہُمَا ۚ فَاِنۡ تَابَا وَاَصۡلَحَا فَاَعۡرِضُوۡا عَنۡہُمَا ؕ اِنَّ اللّٰہَ کَانَ تَوَّابًا رَّحِیۡمًا ","4:22":"وَلَا تَنۡکِحُوۡا مَا نَکَحَ اٰبَآؤُکُمۡ مِّنَ النِّسَآءِ اِلَّا مَا قَدۡ سَلَفَ ؕ اِنَّہٗ کَانَ فَاحِشَۃً وَّمَقۡتًا ؕ وَسَآءَ سَبِیۡلًا ٪ ","4:25":"وَمَنۡ لَّمۡ یَسۡتَطِعۡ مِنۡکُمۡ طَوۡلًا اَنۡ یَّنۡکِحَ الۡمُحۡصَنٰتِ الۡمُؤۡمِنٰتِ فَمِنۡ مَّا مَلَکَتۡ اَیۡمَانُکُمۡ مِّنۡ فَتَیٰتِکُمُ الۡمُؤۡمِنٰتِ ؕ وَاللّٰہُ اَعۡلَمُ بِاِیۡمَانِکُمۡ ؕ بَعۡضُکُمۡ مِّنۡۢ بَعۡضٍ ۚ فَانۡکِحُوۡہُنَّ بِاِذۡنِ اَہۡلِہِنَّ وَاٰتُوۡہُنَّ اُجُوۡرَہُنَّ بِالۡمَعۡرُوۡفِ مُحۡصَنٰتٍ غَیۡرَ مُسٰفِحٰتٍ وَّلَا مُتَّخِذٰتِ اَخۡدَانٍ ۚ فَاِذَاۤ اُحۡصِنَّ فَاِنۡ اَتَیۡنَ بِفَاحِشَۃٍ فَعَلَیۡہِنَّ نِصۡفُ مَا عَلَی الۡمُحۡصَنٰتِ مِنَ الۡعَذَابِ ؕ ذٰلِکَ لِمَنۡ خَشِیَ الۡعَنَتَ مِنۡکُمۡ ؕ وَاَنۡ تَصۡبِرُوۡا خَیۡرٌ لَّکُمۡ ؕ وَاللّٰہُ غَفُوۡرٌ رَّحِیۡمٌ ٪ ","4:28":"یُرِیۡدُ اللّٰہُ اَنۡ یُّخَفِّفَ عَنۡکُمۡ ۚ وَخُلِقَ الۡاِنۡسَانُ ضَعِیۡفًا ","4:38":"وَالَّذِیۡنَ یُنۡفِقُوۡنَ اَمۡوَالَہُمۡ رِئَآءَ النَّاسِ وَلَا یُؤۡمِنُوۡنَ بِاللّٰہِ وَلَا بِالۡیَوۡمِ الۡاٰخِرِ ؕ وَمَنۡ یَّکُنِ الشَّیۡطٰنُ لَہٗ قَرِیۡنًا فَسَآءَ قَرِیۡنًا ","4:54":"اَمۡ یَحۡسُدُوۡنَ النَّاسَ عَلٰی مَاۤ اٰتٰہُمُ اللّٰہُ مِنۡ فَضۡلِہٖ ۚ فَقَدۡ اٰتَیۡنَاۤ اٰلَ اِبۡرٰہِیۡمَ الۡکِتٰبَ وَالۡحِکۡمَۃَ وَاٰتَیۡنٰہُمۡ مُّلۡکًا عَظِیۡمًا ","4:56":"اِنَّ الَّذِیۡنَ کَفَرُوۡا بِاٰیٰتِنَا سَوۡفَ نُصۡلِیۡہِمۡ نَارًا ؕ کُلَّمَا نَضِجَتۡ جُلُوۡدُہُمۡ بَدَّلۡنٰہُمۡ جُلُوۡدًا غَیۡرَہَا لِیَذُوۡقُوا الۡعَذَابَ ؕ اِنَّ اللّٰہَ کَانَ عَزِیۡزًا حَکِیۡمًا ","4:60":"اَلَمۡ تَرَ اِلَی الَّذِیۡنَ یَزۡعُمُوۡنَ اَنَّہُمۡ اٰمَنُوۡا بِمَاۤ اُنۡزِلَ اِلَیۡکَ وَمَاۤ اُنۡزِلَ مِنۡ قَبۡلِکَ یُرِیۡدُوۡنَ اَنۡ یَّتَحَاکَمُوۡۤا اِلَی الطَّاغُوۡتِ وَقَدۡ اُمِرُوۡۤا اَنۡ یَّکۡفُرُوۡا بِہٖ ؕ وَیُرِیۡدُ الشَّیۡطٰنُ اَنۡ یُّضِلَّہُمۡ ضَلٰلًۢا بَعِیۡدًا ","4:66":"وَلَوۡ اَنَّا کَتَبۡنَا عَلَیۡہِمۡ اَنِ اقۡتُلُوۡۤا اَنۡفُسَکُمۡ اَوِ اخۡرُجُوۡا مِنۡ دِیَارِکُمۡ مَّا فَعَلُوۡہُ اِلَّا قَلِیۡلٌ مِّنۡہُمۡ ؕ وَلَوۡ اَنَّہُمۡ فَعَلُوۡا مَا یُوۡعَظُوۡنَ بِہٖ لَکَانَ خَیۡرًا لَّہُمۡ وَاَشَدَّ تَثۡبِیۡتًا ۙ ","4:75":"وَمَا لَکُمۡ لَا تُقَاتِلُوۡنَ فِیۡ سَبِیۡلِ اللّٰہِ وَالۡمُسۡتَضۡعَفِیۡنَ مِنَ الرِّجَالِ وَالنِّسَآءِ وَالۡوِلۡدَانِ الَّذِیۡنَ یَقُوۡلُوۡنَ رَبَّنَاۤ اَخۡرِجۡنَا مِنۡ ہٰذِہِ الۡقَرۡیَۃِ الظَّالِمِ اَہۡلُہَا ۚ وَاجۡعَلۡ لَّنَا مِنۡ لَّدُنۡکَ وَلِیًّا ۚۙ وَّاجۡعَلۡ لَّنَا مِنۡ لَّدُنۡکَ نَصِیۡرًا ؕ ","4:76":"اَلَّذِیۡنَ اٰمَنُوۡا یُقَاتِلُوۡنَ فِیۡ سَبِیۡلِ اللّٰہِ ۚ وَالَّذِیۡنَ کَفَرُوۡا یُقَاتِلُوۡنَ فِیۡ سَبِیۡلِ الطَّاغُوۡتِ فَقَاتِلُوۡۤا اَوۡلِیَآءَ الشَّیۡطٰنِ ۚ اِنَّ کَیۡدَ الشَّیۡطٰنِ کَانَ ضَعِیۡفًا ٪ ","4:77":"اَلَمۡ تَرَ اِلَی الَّذِیۡنَ قِیۡلَ لَہُمۡ کُفُّوۡۤا اَیۡدِیَکُمۡ وَاَقِیۡمُوا الصَّلٰوۃَ وَاٰتُوا الزَّکٰوۃَ ۚ فَلَمَّا کُتِبَ عَلَیۡہِمُ الۡقِتَالُ اِذَا فَرِیۡقٌ مِّنۡہُمۡ یَخۡشَوۡنَ النَّاسَ کَخَشۡیَۃِ اللّٰہِ اَوۡ اَشَدَّ خَشۡیَۃً ۚ وَقَالُوۡا رَبَّنَا لِمَ کَتَبۡتَ عَلَیۡنَا الۡقِتَالَ ۚ لَوۡلَاۤ اَخَّرۡتَنَاۤ اِلٰۤی اَجَلٍ قَرِیۡبٍ ؕ قُلۡ مَتَاعُ الدُّنۡیَا قَلِیۡلٌ ۚ وَالۡاٰخِرَۃُ خَیۡرٌ لِّمَنِ اتَّقٰی ۟ وَلَا تُظۡلَمُوۡنَ فَتِیۡلًا ","4:78":"اَیۡنَمَا تَکُوۡنُوۡا یُدۡرِکۡکُّمُ الۡمَوۡتُ وَلَوۡ کُنۡتُمۡ فِیۡ بُرُوۡجٍ مُّشَیَّدَۃٍ ؕ وَاِنۡ تُصِبۡہُمۡ حَسَنَۃٌ یَّقُوۡلُوۡا ہٰذِہٖ مِنۡ عِنۡدِ اللّٰہِ ۚ وَاِنۡ تُصِبۡہُمۡ سَیِّئَۃٌ یَّقُوۡلُوۡا ہٰذِہٖ مِنۡ عِنۡدِکَ ؕ قُلۡ کُلٌّ مِّنۡ عِنۡدِ اللّٰہِ ؕ فَمَالِ ہٰۤؤُلَآءِ الۡقَوۡمِ لَا یَکَادُوۡنَ یَفۡقَہُوۡنَ حَدِیۡثًا ","4:84":"فَقَاتِلۡ فِیۡ سَبِیۡلِ اللّٰہِ ۚ لَا تُکَلَّفُ اِلَّا نَفۡسَکَ وَحَرِّضِ الۡمُؤۡمِنِیۡنَ ۚ عَسَی اللّٰہُ اَنۡ یَّکُفَّ بَاۡسَ الَّذِیۡنَ کَفَرُوۡا ؕ وَاللّٰہُ اَشَدُّ بَاۡسًا وَّاَشَدُّ تَنۡکِیۡلًا ","4:85":"مَنۡ یَّشۡفَعۡ شَفَاعَۃً حَسَنَۃً یَّکُنۡ لَّہٗ نَصِیۡبٌ مِّنۡہَا ۚ وَمَنۡ یَّشۡفَعۡ شَفَاعَۃً سَیِّئَۃً یَّکُنۡ لَّہٗ کِفۡلٌ مِّنۡہَا ؕ وَکَانَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ مُّقِیۡتًا ","4:89":"وَدُّوۡا لَوۡ تَکۡفُرُوۡنَ کَمَا کَفَرُوۡا فَتَکُوۡنُوۡنَ سَوَآءً فَلَا تَتَّخِذُوۡا مِنۡہُمۡ اَوۡلِیَآءَ حَتّٰی یُہَاجِرُوۡا فِیۡ سَبِیۡلِ اللّٰہِ ؕ فَاِنۡ تَوَلَّوۡا فَخُذُوۡہُمۡ وَاقۡتُلُوۡہُمۡ حَیۡثُ وَجَدۡتُّمُوۡہُمۡ ۪ وَلَا تَتَّخِذُوۡا مِنۡہُمۡ وَلِیًّا وَّلَا نَصِیۡرًا ۙ ","4:91":"سَتَجِدُوۡنَ اٰخَرِیۡنَ یُرِیۡدُوۡنَ اَنۡ یَّاۡمَنُوۡکُمۡ وَیَاۡمَنُوۡا قَوۡمَہُمۡ ؕ کُلَّ مَا رُدُّوۡۤا اِلَی الۡفِتۡنَۃِ اُرۡکِسُوۡا فِیۡہَا ۚ فَاِنۡ لَّمۡ یَعۡتَزِلُوۡکُمۡ وَیُلۡقُوۡۤا اِلَیۡکُمُ السَّلَمَ وَیَکُفُّوۡۤا اَیۡدِیَہُمۡ فَخُذُوۡہُمۡ وَاقۡتُلُوۡہُمۡ حَیۡثُ ثَقِفۡتُمُوۡہُمۡ ؕ وَاُولٰٓئِکُمۡ جَعَلۡنَا لَکُمۡ عَلَیۡہِمۡ سُلۡطٰنًا مُّبِیۡنًا ٪ ","4:93":"وَمَنۡ یَّقۡتُلۡ مُؤۡمِنًا مُّتَعَمِّدًا فَجَزَآؤُہٗ جَہَنَّمُ خٰلِدًا فِیۡہَا وَغَضِبَ اللّٰہُ عَلَیۡہِ وَلَعَنَہٗ وَاَعَدَّ لَہٗ عَذَابًا عَظِیۡمًا ","4:97":"اِنَّ الَّذِیۡنَ تَوَفّٰہُمُ الۡمَلٰٓئِکَۃُ ظَالِمِیۡۤ اَنۡفُسِہِمۡ قَالُوۡا فِیۡمَ کُنۡتُمۡ ؕ قَالُوۡا کُنَّا مُسۡتَضۡعَفِیۡنَ فِی الۡاَرۡضِ ؕ قَالُوۡۤا اَلَمۡ تَکُنۡ اَرۡضُ اللّٰہِ وَاسِعَۃً فَتُہَاجِرُوۡا فِیۡہَا ؕ فَاُولٰٓئِکَ مَاۡوٰىہُمۡ جَہَنَّمُ ؕ وَسَآءَتۡ مَصِیۡرًا ۙ ","4:98":"اِلَّا الۡمُسۡتَضۡعَفِیۡنَ مِنَ الرِّجَالِ وَالنِّسَآءِ وَالۡوِلۡدَانِ لَا یَسۡتَطِیۡعُوۡنَ حِیۡلَۃً وَّلَا یَہۡتَدُوۡنَ سَبِیۡلًا ۙ ","4:102":"وَاِذَا کُنۡتَ فِیۡہِمۡ فَاَقَمۡتَ لَہُمُ الصَّلٰوۃَ فَلۡتَقُمۡ طَآئِفَۃٌ مِّنۡہُمۡ مَّعَکَ وَلۡیَاۡخُذُوۡۤا اَسۡلِحَتَہُمۡ ۟ فَاِذَا سَجَدُوۡا فَلۡیَکُوۡنُوۡا مِنۡ وَّرَآئِکُمۡ ۪ وَلۡتَاۡتِ طَآئِفَۃٌ اُخۡرٰی لَمۡ یُصَلُّوۡا فَلۡیُصَلُّوۡا مَعَکَ وَلۡیَاۡخُذُوۡا حِذۡرَہُمۡ وَاَسۡلِحَتَہُمۡ ۚ وَدَّ الَّذِیۡنَ کَفَرُوۡا لَوۡ تَغۡفُلُوۡنَ عَنۡ اَسۡلِحَتِکُمۡ وَاَمۡتِعَتِکُمۡ فَیَمِیۡلُوۡنَ عَلَیۡکُمۡ مَّیۡلَۃً وَّاحِدَۃً ؕ وَلَا جُنَاحَ عَلَیۡکُمۡ اِنۡ کَانَ بِکُمۡ اَذًی مِّنۡ مَّطَرٍ اَوۡ کُنۡتُمۡ مَّرۡضٰۤی اَنۡ تَضَعُوۡۤا اَسۡلِحَتَکُمۡ ۚ وَخُذُوۡا حِذۡرَکُمۡ ؕ اِنَّ اللّٰہَ اَعَدَّ لِلۡکٰفِرِیۡنَ عَذَابًا مُّہِیۡنًا ","4:104":"وَلَا تَہِنُوۡا فِی ابۡتِغَآءِ الۡقَوۡمِ ؕ اِنۡ تَکُوۡنُوۡا تَاۡلَمُوۡنَ فَاِنَّہُمۡ یَاۡلَمُوۡنَ کَمَا تَاۡلَمُوۡنَ ۚ وَتَرۡجُوۡنَ مِنَ اللّٰہِ مَا لَا یَرۡجُوۡنَ ؕ وَکَانَ اللّٰہُ عَلِیۡمًا حَکِیۡمًا ٪ ","4:116":"اِنَّ اللّٰہَ لَا یَغۡفِرُ اَنۡ یُّشۡرَکَ بِہٖ وَیَغۡفِرُ مَا دُوۡنَ ذٰلِکَ لِمَنۡ یَّشَآءُ ؕ وَمَنۡ یُّشۡرِکۡ بِاللّٰہِ فَقَدۡ ضَلَّ ضَلٰلًۢا بَعِیۡدًا ","4:117":"اِنۡ یَّدۡعُوۡنَ مِنۡ دُوۡنِہٖۤ اِلَّاۤ اِنٰثًا ۚ وَاِنۡ یَّدۡعُوۡنَ اِلَّا شَیۡطٰنًا مَّرِیۡدًا ۙ ","4:118":"لَّعَنَہُ اللّٰہُ ۘ وَقَالَ لَاَتَّخِذَنَّ مِنۡ عِبَادِکَ نَصِیۡبًا مَّفۡرُوۡضًا ۙ","4:119":"وَّلَاُضِلَّنَّہُمۡ وَلَاُمَنِّیَنَّہُمۡ وَلَاٰمُرَنَّہُمۡ فَلَیُبَتِّکُنَّ اٰذَانَ الۡاَنۡعَامِ وَلَاٰمُرَنَّہُمۡ فَلَیُغَیِّرُنَّ خَلۡقَ اللّٰہِ ؕ وَمَنۡ یَّتَّخِذِ الشَّیۡطٰنَ وَلِیًّا مِّنۡ دُوۡنِ اللّٰہِ فَقَدۡ خَسِرَ خُسۡرَانًا مُّبِیۡنًا ؕ","4:120":"یَعِدُہُمۡ وَیُمَنِّیۡہِمۡ ؕ وَمَا یَعِدُہُمُ الشَّیۡطٰنُ اِلَّا غُرُوۡرًا ","4:121":"اُولٰٓئِکَ مَاۡوٰىہُمۡ جَہَنَّمُ ۫ وَلَا یَجِدُوۡنَ عَنۡہَا مَحِیۡصًا ","5:22":"قَالُوۡا یٰمُوۡسٰۤی اِنَّ فِیۡہَا قَوۡمًا جَبَّارِیۡنَ ٭ۖ وَاِنَّا لَنۡ نَّدۡخُلَہَا حَتّٰی یَخۡرُجُوۡا مِنۡہَا ۚ فَاِنۡ یَّخۡرُجُوۡا مِنۡہَا فَاِنَّا دٰخِلُوۡنَ ","5:23":"قَالَ رَجُلٰنِ مِنَ الَّذِیۡنَ یَخَافُوۡنَ اَنۡعَمَ اللّٰہُ عَلَیۡہِمَا ادۡخُلُوۡا عَلَیۡہِمُ الۡبَابَ ۚ فَاِذَا دَخَلۡتُمُوۡہُ فَاِنَّکُمۡ غٰلِبُوۡنَ ۬ۚ وَعَلَی اللّٰہِ فَتَوَکَّلُوۡۤا اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ ","5:24":"قَالُوۡا یٰمُوۡسٰۤی اِنَّا لَنۡ نَّدۡخُلَہَاۤ اَبَدًا مَّا دَامُوۡا فِیۡہَا فَاذۡہَبۡ اَنۡتَ وَرَبُّکَ فَقَاتِلَاۤ اِنَّا ہٰہُنَا قٰعِدُوۡنَ ","5:25":"قَالَ رَبِّ اِنِّیۡ لَاۤ اَمۡلِکُ اِلَّا نَفۡسِیۡ وَاَخِیۡ فَافۡرُقۡ بَیۡنَنَا وَبَیۡنَ الۡقَوۡمِ الۡفٰسِقِیۡنَ ","5:32":"مِنۡ اَجۡلِ ذٰلِکَ ۚۛؔ کَتَبۡنَا عَلٰی بَنِیۡۤ اِسۡرَآءِیۡلَ اَنَّہٗ مَنۡ قَتَلَ نَفۡسًۢا بِغَیۡرِ نَفۡسٍ اَوۡ فَسَادٍ فِی الۡاَرۡضِ فَکَاَنَّمَا قَتَلَ النَّاسَ جَمِیۡعًا ؕ وَمَنۡ اَحۡیَاہَا فَکَاَنَّمَاۤ اَحۡیَا النَّاسَ جَمِیۡعًا ؕ وَلَقَدۡ جَآءَتۡہُمۡ رُسُلُنَا بِالۡبَیِّنٰتِ ۫ ثُمَّ اِنَّ کَثِیۡرًا مِّنۡہُمۡ بَعۡدَ ذٰلِکَ فِی الۡاَرۡضِ لَمُسۡرِفُوۡنَ ","5:33":"اِنَّمَا جَزٰٓؤُا الَّذِیۡنَ یُحَارِبُوۡنَ اللّٰہَ وَرَسُوۡلَہٗ وَیَسۡعَوۡنَ فِی الۡاَرۡضِ فَسَادًا اَنۡ یُّقَتَّلُوۡۤا اَوۡ یُصَلَّبُوۡۤا اَوۡ تُقَطَّعَ اَیۡدِیۡہِمۡ وَاَرۡجُلُہُمۡ مِّنۡ خِلَافٍ اَوۡ یُنۡفَوۡا مِنَ الۡاَرۡضِ ؕ ذٰلِکَ لَہُمۡ خِزۡیٌ فِی الدُّنۡیَا وَلَہُمۡ فِی الۡاٰخِرَۃِ عَذَابٌ عَظِیۡمٌ ۙ","5:37":"یُرِیۡدُوۡنَ اَنۡ یَّخۡرُجُوۡا مِنَ النَّارِ وَمَا ہُمۡ بِخٰرِجِیۡنَ مِنۡہَا ۫ وَلَہُمۡ عَذَابٌ مُّقِیۡمٌ ","5:41":"یٰۤاَیُّہَا الرَّسُوۡلُ لَا یَحۡزُنۡکَ الَّذِیۡنَ یُسَارِعُوۡنَ فِی الۡکُفۡرِ مِنَ الَّذِیۡنَ قَالُوۡۤا اٰمَنَّا بِاَفۡوَاہِہِمۡ وَلَمۡ تُؤۡمِنۡ قُلُوۡبُہُمۡ ۚۛ وَمِنَ الَّذِیۡنَ ہَادُوۡا ۚۛ سَمّٰعُوۡنَ لِلۡکَذِبِ سَمّٰعُوۡنَ لِقَوۡمٍ اٰخَرِیۡنَ ۙ لَمۡ یَاۡتُوۡکَ ؕ یُحَرِّفُوۡنَ الۡکَلِمَ مِنۡۢ بَعۡدِ مَوَاضِعِہٖ ۚ یَقُوۡلُوۡنَ اِنۡ اُوۡتِیۡتُمۡ ہٰذَا فَخُذُوۡہُ وَاِنۡ لَّمۡ تُؤۡتَوۡہُ فَاحۡذَرُوۡا ؕ وَمَنۡ یُّرِدِ اللّٰہُ فِتۡنَتَہٗ فَلَنۡ تَمۡلِکَ لَہٗ مِنَ اللّٰہِ شَیۡئًا ؕ اُولٰٓئِکَ الَّذِیۡنَ لَمۡ یُرِدِ اللّٰہُ اَنۡ یُّطَہِّرَ قُلُوۡبَہُمۡ ؕ لَہُمۡ فِی الدُّنۡیَا خِزۡیٌ ۚۖ وَّلَہُمۡ فِی الۡاٰخِرَۃِ عَذَابٌ عَظِیۡمٌ ","5:45":"وَکَتَبۡنَا عَلَیۡہِمۡ فِیۡہَاۤ اَنَّ النَّفۡسَ بِالنَّفۡسِ ۙ وَالۡعَیۡنَ بِالۡعَیۡنِ وَالۡاَنۡفَ بِالۡاَنۡفِ وَالۡاُذُنَ بِالۡاُذُنِ وَالسِّنَّ بِالسِّنِّ ۙ وَالۡجُرُوۡحَ قِصَاصٌ ؕ فَمَنۡ تَصَدَّقَ بِہٖ فَہُوَ کَفَّارَۃٌ لَّہٗ ؕ وَمَنۡ لَّمۡ یَحۡکُمۡ بِمَاۤ اَنۡزَلَ اللّٰہُ فَاُولٰٓئِکَ ہُمُ الظّٰلِمُوۡنَ ","5:83":"وَاِذَا سَمِعُوۡا مَاۤ اُنۡزِلَ اِلَی الرَّسُوۡلِ تَرٰۤی اَعۡیُنَہُمۡ تَفِیۡضُ مِنَ الدَّمۡعِ مِمَّا عَرَفُوۡا مِنَ الۡحَقِّ ۚ یَقُوۡلُوۡنَ رَبَّنَاۤ اٰمَنَّا فَاکۡتُبۡنَا مَعَ الشّٰہِدِیۡنَ ","5:90":"یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِنَّمَا الۡخَمۡرُ وَالۡمَیۡسِرُ وَالۡاَنۡصَابُ وَالۡاَزۡلَامُ رِجۡسٌ مِّنۡ عَمَلِ الشَّیۡطٰنِ فَاجۡتَنِبُوۡہُ لَعَلَّکُمۡ تُفۡلِحُوۡنَ ","5:91":"اِنَّمَا یُرِیۡدُ الشَّیۡطٰنُ اَنۡ یُّوۡقِعَ بَیۡنَکُمُ الۡعَدَاوَۃَ وَالۡبَغۡضَآءَ فِی الۡخَمۡرِ وَالۡمَیۡسِرِ وَیَصُدَّکُمۡ عَنۡ ذِکۡرِ اللّٰہِ وَعَنِ الصَّلٰوۃِ ۚ فَہَلۡ اَنۡتُمۡ مُّنۡتَہُوۡنَ ","5:95":"یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَقۡتُلُوا الصَّیۡدَ وَاَنۡتُمۡ حُرُمٌ ؕ وَمَنۡ قَتَلَہٗ مِنۡکُمۡ مُّتَعَمِّدًا فَجَزَآءٌ مِّثۡلُ مَا قَتَلَ مِنَ النَّعَمِ یَحۡکُمُ بِہٖ ذَوَا عَدۡلٍ مِّنۡکُمۡ ہَدۡیًۢا بٰلِغَ الۡکَعۡبَۃِ اَوۡ کَفَّارَۃٌ طَعَامُ مَسٰکِیۡنَ اَوۡ عَدۡلُ ذٰلِکَ صِیَامًا لِّیَذُوۡقَ وَبَالَ اَمۡرِہٖ ؕ عَفَا اللّٰہُ عَمَّا سَلَفَ ؕ وَمَنۡ عَادَ فَیَنۡتَقِمُ اللّٰہُ مِنۡہُ ؕ وَاللّٰہُ عَزِیۡزٌ ذُو انۡتِقَامٍ ","6:13":"وَلَہٗ مَا سَکَنَ فِی الَّیۡلِ وَالنَّہَارِ ؕ وَہُوَ السَّمِیۡعُ الۡعَلِیۡمُ ","6:43":"فَلَوۡلَاۤ اِذۡ جَآءَہُمۡ بَاۡسُنَا تَضَرَّعُوۡا وَلٰکِنۡ قَسَتۡ قُلُوۡبُہُمۡ وَزَیَّنَ لَہُمُ الشَّیۡطٰنُ مَا کَانُوۡا یَعۡمَلُوۡنَ ","6:61":"وَہُوَ الۡقَاہِرُ فَوۡقَ عِبَادِہٖ وَیُرۡسِلُ عَلَیۡکُمۡ حَفَظَۃً ؕ حَتّٰۤی اِذَا جَآءَ اَحَدَکُمُ الۡمَوۡتُ تَوَفَّتۡہُ رُسُلُنَا وَہُمۡ لَا یُفَرِّطُوۡنَ ","6:62":"ثُمَّ رُدُّوۡۤا اِلَی اللّٰہِ مَوۡلٰىہُمُ الۡحَقِّ ؕ اَلَا لَہُ الۡحُکۡمُ ۟ وَہُوَ اَسۡرَعُ الۡحٰسِبِیۡنَ ","6:68":"وَاِذَا رَاَیۡتَ الَّذِیۡنَ یَخُوۡضُوۡنَ فِیۡۤ اٰیٰتِنَا فَاَعۡرِضۡ عَنۡہُمۡ حَتّٰی یَخُوۡضُوۡا فِیۡ حَدِیۡثٍ غَیۡرِہٖ ؕ وَاِمَّا یُنۡسِیَنَّکَ الشَّیۡطٰنُ فَلَا تَقۡعُدۡ بَعۡدَ الذِّکۡرٰی مَعَ الۡقَوۡمِ الظّٰلِمِیۡنَ ","6:71":"قُلۡ اَنَدۡعُوۡا مِنۡ دُوۡنِ اللّٰہِ مَا لَا یَنۡفَعُنَا وَلَا یَضُرُّنَا وَنُرَدُّ عَلٰۤی اَعۡقَابِنَا بَعۡدَ اِذۡ ہَدٰىنَا اللّٰہُ کَالَّذِی اسۡتَہۡوَتۡہُ الشَّیٰطِیۡنُ فِی الۡاَرۡضِ حَیۡرَانَ ۪ لَہٗۤ اَصۡحٰبٌ یَّدۡعُوۡنَہٗۤ اِلَی الۡہُدَی ائۡتِنَا ؕ قُلۡ اِنَّ ہُدَی اللّٰہِ ہُوَ الۡہُدٰی ؕ وَاُمِرۡنَا لِنُسۡلِمَ لِرَبِّ الۡعٰلَمِیۡنَ ۙ ","6:93":"وَمَنۡ اَظۡلَمُ مِمَّنِ افۡتَرٰی عَلَی اللّٰہِ کَذِبًا اَوۡ قَالَ اُوۡحِیَ اِلَیَّ وَلَمۡ یُوۡحَ اِلَیۡہِ شَیۡءٌ وَّمَنۡ قَالَ سَاُنۡزِلُ مِثۡلَ مَاۤ اَنۡزَلَ اللّٰہُ ؕ وَلَوۡ تَرٰۤی اِذِ الظّٰلِمُوۡنَ فِیۡ غَمَرٰتِ الۡمَوۡتِ وَالۡمَلٰٓئِکَۃُ بَاسِطُوۡۤا اَیۡدِیۡہِمۡ ۚ اَخۡرِجُوۡۤا اَنۡفُسَکُمۡ ؕ اَلۡیَوۡمَ تُجۡزَوۡنَ عَذَابَ الۡہُوۡنِ بِمَا کُنۡتُمۡ تَقُوۡلُوۡنَ عَلَی اللّٰہِ غَیۡرَ الۡحَقِّ وَکُنۡتُمۡ عَنۡ اٰیٰتِہٖ تَسۡتَکۡبِرُوۡنَ ","6:95":"اِنَّ اللّٰہَ فَالِقُ الۡحَبِّ وَالنَّوٰی ؕ یُخۡرِجُ الۡحَیَّ مِنَ الۡمَیِّتِ وَمُخۡرِجُ الۡمَیِّتِ مِنَ الۡحَیِّ ؕ ذٰلِکُمُ اللّٰہُ فَاَنّٰی تُؤۡفَکُوۡنَ ","6:103":"لَا تُدۡرِکُہُ الۡاَبۡصَارُ ۫ وَہُوَ یُدۡرِکُ الۡاَبۡصَارَ ۚ وَہُوَ اللَّطِیۡفُ الۡخَبِیۡرُ ","6:112":"وَکَذٰلِکَ جَعَلۡنَا لِکُلِّ نَبِیٍّ عَدُوًّا شَیٰطِیۡنَ الۡاِنۡسِ وَالۡجِنِّ یُوۡحِیۡ بَعۡضُہُمۡ اِلٰی بَعۡضٍ زُخۡرُفَ الۡقَوۡلِ غُرُوۡرًا ؕ وَلَوۡ شَآءَ رَبُّکَ مَا فَعَلُوۡہُ فَذَرۡہُمۡ وَمَا یَفۡتَرُوۡنَ ","6:121":"وَلَا تَاۡکُلُوۡا مِمَّا لَمۡ یُذۡکَرِ اسۡمُ اللّٰہِ عَلَیۡہِ وَاِنَّہٗ لَفِسۡقٌ ؕ وَاِنَّ الشَّیٰطِیۡنَ لَیُوۡحُوۡنَ اِلٰۤی اَوۡلِیٰٓئِہِمۡ لِیُجَادِلُوۡکُمۡ ۚ وَاِنۡ اَطَعۡتُمُوۡہُمۡ اِنَّکُمۡ لَمُشۡرِکُوۡنَ ٪ ","6:128":"وَیَوۡمَ یَحۡشُرُہُمۡ جَمِیۡعًا ۚ یٰمَعۡشَرَ الۡجِنِّ قَدِ اسۡتَکۡثَرۡتُمۡ مِّنَ الۡاِنۡسِ ۚ وَقَالَ اَوۡلِیٰٓؤُہُمۡ مِّنَ الۡاِنۡسِ رَبَّنَا اسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضٍ وَّبَلَغۡنَاۤ اَجَلَنَا الَّذِیۡۤ اَجَّلۡتَ لَنَا ؕ قَالَ النَّارُ مَثۡوٰىکُمۡ خٰلِدِیۡنَ فِیۡہَاۤ اِلَّا مَا شَآءَ اللّٰہُ ؕ اِنَّ رَبَّکَ حَکِیۡمٌ عَلِیۡمٌ ","6:129":"وَکَذٰلِکَ نُوَلِّیۡ بَعۡضَ الظّٰلِمِیۡنَ بَعۡضًۢا بِمَا کَانُوۡا یَکۡسِبُوۡنَ ٪ ","6:130":"یٰمَعۡشَرَ الۡجِنِّ وَالۡاِنۡسِ اَلَمۡ یَاۡتِکُمۡ رُسُلٌ مِّنۡکُمۡ یَقُصُّوۡنَ عَلَیۡکُمۡ اٰیٰتِیۡ وَیُنۡذِرُوۡنَکُمۡ لِقَآءَ یَوۡمِکُمۡ ہٰذَا ؕ قَالُوۡا شَہِدۡنَا عَلٰۤی اَنۡفُسِنَا وَغَرَّتۡہُمُ الۡحَیٰوۃُ الدُّنۡیَا وَشَہِدُوۡا عَلٰۤی اَنۡفُسِہِمۡ اَنَّہُمۡ کَانُوۡا کٰفِرِیۡنَ ","6:142":"وَمِنَ الۡاَنۡعَامِ حَمُوۡلَۃً وَّفَرۡشًا ؕ کُلُوۡا مِمَّا رَزَقَکُمُ اللّٰہُ وَلَا تَتَّبِعُوۡا خُطُوٰتِ الشَّیۡطٰنِ ؕ اِنَّہٗ لَکُمۡ عَدُوٌّ مُّبِیۡنٌ ۙ ","6:151":"قُلۡ تَعَالَوۡا اَتۡلُ مَا حَرَّمَ رَبُّکُمۡ عَلَیۡکُمۡ اَلَّا تُشۡرِکُوۡا بِہٖ شَیۡئًا وَّبِالۡوَالِدَیۡنِ اِحۡسَانًا ۚ وَلَا تَقۡتُلُوۡۤا اَوۡلَادَکُمۡ مِّنۡ اِمۡلَاقٍ ؕ نَحۡنُ نَرۡزُقُکُمۡ وَاِیَّاہُمۡ ۚ وَلَا تَقۡرَبُوا الۡفَوَاحِشَ مَا ظَہَرَ مِنۡہَا وَمَا بَطَنَ ۚ وَلَا تَقۡتُلُوا النَّفۡسَ الَّتِیۡ حَرَّمَ اللّٰہُ اِلَّا بِالۡحَقِّ ؕ ذٰلِکُمۡ وَصّٰکُمۡ بِہٖ لَعَلَّکُمۡ تَعۡقِلُوۡنَ ","7:13":"قَالَ فَاہۡبِطۡ مِنۡہَا فَمَا یَکُوۡنُ لَکَ اَنۡ تَتَکَبَّرَ فِیۡہَا فَاخۡرُجۡ اِنَّکَ مِنَ الصّٰغِرِیۡنَ ","7:18":"قَالَ اخۡرُجۡ مِنۡہَا مَذۡءُوۡمًا مَّدۡحُوۡرًا ؕ لَمَنۡ تَبِعَکَ مِنۡہُمۡ لَاَمۡلَـَٔنَّ جَہَنَّمَ مِنۡکُمۡ اَجۡمَعِیۡنَ ","7:25":"قَالَ فِیۡہَا تَحۡیَوۡنَ وَفِیۡہَا تَمُوۡتُوۡنَ وَمِنۡہَا تُخۡرَجُوۡنَ ٪ ","7:27":"یٰبَنِیۡۤ اٰدَمَ لَا یَفۡتِنَنَّکُمُ الشَّیۡطٰنُ کَمَاۤ اَخۡرَجَ اَبَوَیۡکُمۡ مِّنَ الۡجَنَّۃِ یَنۡزِعُ عَنۡہُمَا لِبَاسَہُمَا لِیُرِیَہُمَا سَوۡاٰتِہِمَا ؕ اِنَّہٗ یَرٰىکُمۡ ہُوَ وَقَبِیۡلُہٗ مِنۡ حَیۡثُ لَا تَرَوۡنَہُمۡ ؕ اِنَّا جَعَلۡنَا الشَّیٰطِیۡنَ اَوۡلِیَآءَ لِلَّذِیۡنَ لَا یُؤۡمِنُوۡنَ ","7:28":"وَاِذَا فَعَلُوۡا فَاحِشَۃً قَالُوۡا وَجَدۡنَا عَلَیۡہَاۤ اٰبَآءَنَا وَاللّٰہُ اَمَرَنَا بِہَا ؕ قُلۡ اِنَّ اللّٰہَ لَا یَاۡمُرُ بِالۡفَحۡشَآءِ ؕ اَتَقُوۡلُوۡنَ عَلَی اللّٰہِ مَا لَا تَعۡلَمُوۡنَ ","7:30":"فَرِیۡقًا ہَدٰی وَفَرِیۡقًا حَقَّ عَلَیۡہِمُ الضَّلٰلَۃُ ؕ اِنَّہُمُ اتَّخَذُوا الشَّیٰطِیۡنَ اَوۡلِیَآءَ مِنۡ دُوۡنِ اللّٰہِ وَیَحۡسَبُوۡنَ اَنَّہُمۡ مُّہۡتَدُوۡنَ ","7:33":"قُلۡ اِنَّمَا حَرَّمَ رَبِّیَ الۡفَوَاحِشَ مَا ظَہَرَ مِنۡہَا وَمَا بَطَنَ وَالۡاِثۡمَ وَالۡبَغۡیَ بِغَیۡرِ الۡحَقِّ وَاَنۡ تُشۡرِکُوۡا بِاللّٰہِ مَا لَمۡ یُنَزِّلۡ بِہٖ سُلۡطٰنًا وَّاَنۡ تَقُوۡلُوۡا عَلَی اللّٰہِ مَا لَا تَعۡلَمُوۡنَ ","7:38":"قَالَ ادۡخُلُوۡا فِیۡۤ اُمَمٍ قَدۡ خَلَتۡ مِنۡ قَبۡلِکُمۡ مِّنَ الۡجِنِّ وَالۡاِنۡسِ فِی النَّارِ ؕ کُلَّمَا دَخَلَتۡ اُمَّۃٌ لَّعَنَتۡ اُخۡتَہَا ؕ حَتّٰۤی اِذَا ادَّارَکُوۡا فِیۡہَا جَمِیۡعًا ۙ قَالَتۡ اُخۡرٰىہُمۡ لِاُوۡلٰىہُمۡ رَبَّنَا ہٰۤؤُلَآءِ اَضَلُّوۡنَا فَاٰتِہِمۡ عَذَابًا ضِعۡفًا مِّنَ النَّارِ ۬ؕ قَالَ لِکُلٍّ ضِعۡفٌ وَّلٰکِنۡ لَّا تَعۡلَمُوۡنَ ","7:46":"وَبَیۡنَہُمَا حِجَابٌ ۚ وَعَلَی الۡاَعۡرَافِ رِجَالٌ یَّعۡرِفُوۡنَ کُلًّۢا بِسِیۡمٰہُمۡ ۚ وَنَادَوۡا اَصۡحٰبَ الۡجَنَّۃِ اَنۡ سَلٰمٌ عَلَیۡکُمۡ ۟ لَمۡ یَدۡخُلُوۡہَا وَہُمۡ یَطۡمَعُوۡنَ ","7:54":"اِنَّ رَبَّکُمُ اللّٰہُ الَّذِیۡ خَلَقَ السَّمٰوٰتِ وَالۡاَرۡضَ فِیۡ سِتَّۃِ اَیَّامٍ ثُمَّ اسۡتَوٰی عَلَی الۡعَرۡشِ ۟ یُغۡشِی الَّیۡلَ النَّہَارَ یَطۡلُبُہٗ حَثِیۡثًا ۙ وَّالشَّمۡسَ وَالۡقَمَرَ وَالنُّجُوۡمَ مُسَخَّرٰتٍۭ بِاَمۡرِہٖ ؕ اَلَا لَہُ الۡخَلۡقُ وَالۡاَمۡرُ ؕ تَبٰرَکَ اللّٰہُ رَبُّ الۡعٰلَمِیۡنَ ","7:56":"وَلَا تُفۡسِدُوۡا فِی الۡاَرۡضِ بَعۡدَ اِصۡلَاحِہَا وَادۡعُوۡہُ خَوۡفًا وَّطَمَعًا ؕ اِنَّ رَحۡمَتَ اللّٰہِ قَرِیۡبٌ مِّنَ الۡمُحۡسِنِیۡنَ ","7:58":"وَالۡبَلَدُ الطَّیِّبُ یَخۡرُجُ نَبَاتُہٗ بِاِذۡنِ رَبِّہٖ ۚ وَالَّذِیۡ خَبُثَ لَا یَخۡرُجُ اِلَّا نَکِدًا ؕ کَذٰلِکَ نُصَرِّفُ الۡاٰیٰتِ لِقَوۡمٍ یَّشۡکُرُوۡنَ ٪ ","7:82":"وَمَا کَانَ جَوَابَ قَوۡمِہٖۤ اِلَّاۤ اَنۡ قَالُوۡۤا اَخۡرِجُوۡہُمۡ مِّنۡ قَرۡیَتِکُمۡ ۚ اِنَّہُمۡ اُنَاسٌ یَّتَطَہَّرُوۡنَ ","7:102":"وَمَا وَجَدۡنَا لِاَکۡثَرِہِمۡ مِّنۡ عَہۡدٍ ۚ وَاِنۡ وَّجَدۡنَاۤ اَکۡثَرَہُمۡ لَفٰسِقِیۡنَ ","7:117":"وَاَوۡحَیۡنَاۤ اِلٰی مُوۡسٰۤی اَنۡ اَلۡقِ عَصَاکَ ۚ فَاِذَا ہِیَ تَلۡقَفُ مَا یَاۡفِکُوۡنَ ۚ ","7:118":"فَوَقَعَ الۡحَقُّ وَبَطَلَ مَا کَانُوۡا یَعۡمَلُوۡنَ ۚ ","7:119":"فَغُلِبُوۡا ہُنَالِکَ وَانۡقَلَبُوۡا صٰغِرِیۡنَ ۚ ","7:120":"وَاُلۡقِیَ السَّحَرَۃُ سٰجِدِیۡنَ ۚۖ ","7:121":"قَالُوۡۤا اٰمَنَّا بِرَبِّ الۡعٰلَمِیۡنَ ۙ ","7:122":"رَبِّ مُوۡسٰی وَہٰرُوۡنَ ","7:127":"وَقَالَ الۡمَلَاُ مِنۡ قَوۡمِ فِرۡعَوۡنَ اَتَذَرُ مُوۡسٰی وَقَوۡمَہٗ لِیُفۡسِدُوۡا فِی الۡاَرۡضِ وَیَذَرَکَ وَاٰلِہَتَکَ ؕ قَالَ سَنُقَتِّلُ اَبۡنَآءَہُمۡ وَنَسۡتَحۡیٖ نِسَآءَہُمۡ ۚ وَاِنَّا فَوۡقَہُمۡ قٰہِرُوۡنَ ","7:150":"وَلَمَّا رَجَعَ مُوۡسٰۤی اِلٰی قَوۡمِہٖ غَضۡبَانَ اَسِفًا ۙ قَالَ بِئۡسَمَا خَلَفۡتُمُوۡنِیۡ مِنۡۢ بَعۡدِیۡ ۚ اَعَجِلۡتُمۡ اَمۡرَ رَبِّکُمۡ ۚ وَاَلۡقَی الۡاَلۡوَاحَ وَاَخَذَ بِرَاۡسِ اَخِیۡہِ یَجُرُّہٗۤ اِلَیۡہِ ؕ قَالَ ابۡنَ اُمَّ اِنَّ الۡقَوۡمَ اسۡتَضۡعَفُوۡنِیۡ وَکَادُوۡا یَقۡتُلُوۡنَنِیۡ ۫ۖ فَلَا تُشۡمِتۡ بِیَ الۡاَعۡدَآءَ وَلَا تَجۡعَلۡنِیۡ مَعَ الۡقَوۡمِ الظّٰلِمِیۡنَ ","7:151":"قَالَ رَبِّ اغۡفِرۡ لِیۡ وَلِاَخِیۡ وَاَدۡخِلۡنَا فِیۡ رَحۡمَتِکَ ۫ۖ وَاَنۡتَ اَرۡحَمُ الرّٰحِمِیۡنَ ٪","7:175":"وَاتۡلُ عَلَیۡہِمۡ نَبَاَ الَّذِیۡۤ اٰتَیۡنٰہُ اٰیٰتِنَا فَانۡسَلَخَ مِنۡہَا فَاَتۡبَعَہُ الشَّیۡطٰنُ فَکَانَ مِنَ الۡغٰوِیۡنَ ","7:179":"وَلَقَدۡ ذَرَاۡنَا لِجَہَنَّمَ کَثِیۡرًا مِّنَ الۡجِنِّ وَالۡاِنۡسِ ۫ۖ لَہُمۡ قُلُوۡبٌ لَّا یَفۡقَہُوۡنَ بِہَا ۫ وَلَہُمۡ اَعۡیُنٌ لَّا یُبۡصِرُوۡنَ بِہَا ۫ وَلَہُمۡ اٰذَانٌ لَّا یَسۡمَعُوۡنَ بِہَا ؕ اُولٰٓئِکَ کَالۡاَنۡعَامِ بَلۡ ہُمۡ اَضَلُّ ؕ اُولٰٓئِکَ ہُمُ الۡغٰفِلُوۡنَ ","7:200":"وَاِمَّا یَنۡزَغَنَّکَ مِنَ الشَّیۡطٰنِ نَزۡغٌ فَاسۡتَعِذۡ بِاللّٰہِ ؕ اِنَّہٗ سَمِیۡعٌ عَلِیۡمٌ ","7:201":"اِنَّ الَّذِیۡنَ اتَّقَوۡا اِذَا مَسَّہُمۡ طٰٓئِفٌ مِّنَ الشَّیۡطٰنِ تَذَکَّرُوۡا فَاِذَا ہُمۡ مُّبۡصِرُوۡنَ ۚ ","8:1":"یَسۡـَٔلُوۡنَکَ عَنِ الۡاَنۡفَالِ ؕ قُلِ الۡاَنۡفَالُ لِلّٰہِ وَالرَّسُوۡلِ ۚ فَاتَّقُوا اللّٰہَ وَاَصۡلِحُوۡا ذَاتَ بَیۡنِکُمۡ ۪ وَاَطِیۡعُوا اللّٰہَ وَرَسُوۡلَہٗۤ اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ ","8:2":"اِنَّمَا الۡمُؤۡمِنُوۡنَ الَّذِیۡنَ اِذَا ذُکِرَ اللّٰہُ وَجِلَتۡ قُلُوۡبُہُمۡ وَاِذَا تُلِیَتۡ عَلَیۡہِمۡ اٰیٰتُہٗ زَادَتۡہُمۡ اِیۡمَانًا وَّعَلٰی رَبِّہِمۡ یَتَوَکَّلُوۡنَ ۚۖ ","8:3":"الَّذِیۡنَ یُقِیۡمُوۡنَ الصَّلٰوۃَ وَمِمَّا رَزَقۡنٰہُمۡ یُنۡفِقُوۡنَ ؕ ","8:4":"اُولٰٓئِکَ ہُمُ الۡمُؤۡمِنُوۡنَ حَقًّا ؕ لَہُمۡ دَرَجٰتٌ عِنۡدَ رَبِّہِمۡ وَمَغۡفِرَۃٌ وَّرِزۡقٌ کَرِیۡمٌ ۚ ","8:5":"کَمَاۤ اَخۡرَجَکَ رَبُّکَ مِنۡۢ بَیۡتِکَ بِالۡحَقِّ ۪ وَاِنَّ فَرِیۡقًا مِّنَ الۡمُؤۡمِنِیۡنَ لَکٰرِہُوۡنَ ۙ ","8:6":"یُجَادِلُوۡنَکَ فِی الۡحَقِّ بَعۡدَمَا تَبَیَّنَ کَاَنَّمَا یُسَاقُوۡنَ اِلَی الۡمَوۡتِ وَہُمۡ یَنۡظُرُوۡنَ ؕ ","8:7":"وَاِذۡ یَعِدُکُمُ اللّٰہُ اِحۡدَی الطَّآئِفَتَیۡنِ اَنَّہَا لَکُمۡ وَتَوَدُّوۡنَ اَنَّ غَیۡرَ ذَاتِ الشَّوۡکَۃِ تَکُوۡنُ لَکُمۡ وَیُرِیۡدُ اللّٰہُ اَنۡ یُّحِقَّ الۡحَقَّ بِکَلِمٰتِہٖ وَیَقۡطَعَ دَابِرَ الۡکٰفِرِیۡنَ ۙ ","8:8":"لِیُحِقَّ الۡحَقَّ وَیُبۡطِلَ الۡبَاطِلَ وَلَوۡ کَرِہَ الۡمُجۡرِمُوۡنَ ۚ ","8:9":"اِذۡ تَسۡتَغِیۡثُوۡنَ رَبَّکُمۡ فَاسۡتَجَابَ لَکُمۡ اَنِّیۡ مُمِدُّکُمۡ بِاَلۡفٍ مِّنَ الۡمَلٰٓئِکَۃِ مُرۡدِفِیۡنَ ","8:10":"وَمَا جَعَلَہُ اللّٰہُ اِلَّا بُشۡرٰی وَلِتَطۡمَئِنَّ بِہٖ قُلُوۡبُکُمۡ ۚ وَمَا النَّصۡرُ اِلَّا مِنۡ عِنۡدِ اللّٰہِ ؕ اِنَّ اللّٰہَ عَزِیۡزٌ حَکِیۡمٌ ٪ ","8:11":"اِذۡ یُغَشِّیۡکُمُ النُّعَاسَ اَمَنَۃً مِّنۡہُ وَیُنَزِّلُ عَلَیۡکُمۡ مِّنَ السَّمَآءِ مَآءً لِّیُطَہِّرَکُمۡ بِہٖ وَیُذۡہِبَ عَنۡکُمۡ رِجۡزَ الشَّیۡطٰنِ وَلِیَرۡبِطَ عَلٰی قُلُوۡبِکُمۡ وَیُثَبِّتَ بِہِ الۡاَقۡدَامَ ؕ ","8:12":"اِذۡ یُوۡحِیۡ رَبُّکَ اِلَی الۡمَلٰٓئِکَۃِ اَنِّیۡ مَعَکُمۡ فَثَبِّتُوا الَّذِیۡنَ اٰمَنُوۡا ؕ سَاُلۡقِیۡ فِیۡ قُلُوۡبِ الَّذِیۡنَ کَفَرُوا الرُّعۡبَ فَاضۡرِبُوۡا فَوۡقَ الۡاَعۡنَاقِ وَاضۡرِبُوۡا مِنۡہُمۡ کُلَّ بَنَانٍ ؕ ","8:13":"ذٰلِکَ بِاَنَّہُمۡ شَآقُّوا اللّٰہَ وَرَسُوۡلَہٗ ۚ وَمَنۡ یُّشَاقِقِ اللّٰہَ وَرَسُوۡلَہٗ فَاِنَّ اللّٰہَ شَدِیۡدُ الۡعِقَابِ ","8:14":"ذٰلِکُمۡ فَذُوۡقُوۡہُ وَاَنَّ لِلۡکٰفِرِیۡنَ عَذَابَ النَّارِ ","8:15":"یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡۤا اِذَا لَقِیۡتُمُ الَّذِیۡنَ کَفَرُوۡا زَحۡفًا فَلَا تُوَلُّوۡہُمُ الۡاَدۡبَارَ ۚ ","8:16":"وَمَنۡ یُّوَلِّہِمۡ یَوۡمَئِذٍ دُبُرَہٗۤ اِلَّا مُتَحَرِّفًا لِّقِتَالٍ اَوۡ مُتَحَیِّزًا اِلٰی فِئَۃٍ فَقَدۡ بَآءَ بِغَضَبٍ مِّنَ اللّٰہِ وَمَاۡوٰىہُ جَہَنَّمُ ؕ وَبِئۡسَ الۡمَصِیۡرُ ","8:17":"فَلَمۡ تَقۡتُلُوۡہُمۡ وَلٰکِنَّ اللّٰہَ قَتَلَہُمۡ ۪ وَمَا رَمَیۡتَ اِذۡ رَمَیۡتَ وَلٰکِنَّ اللّٰہَ رَمٰی ۚ وَلِیُبۡلِیَ الۡمُؤۡمِنِیۡنَ مِنۡہُ بَلَآءً حَسَنًا ؕ اِنَّ اللّٰہَ سَمِیۡعٌ عَلِیۡمٌ ","8:18":"ذٰلِکُمۡ وَاَنَّ اللّٰہَ مُوۡہِنُ کَیۡدِ الۡکٰفِرِیۡنَ ","8:19":"اِنۡ تَسۡتَفۡتِحُوۡا فَقَدۡ جَآءَکُمُ الۡفَتۡحُ ۚ وَاِنۡ تَنۡتَہُوۡا فَہُوَ خَیۡرٌ لَّکُمۡ ۚ وَاِنۡ تَعُوۡدُوۡا نَعُدۡ ۚ وَلَنۡ تُغۡنِیَ عَنۡکُمۡ فِئَتُکُمۡ شَیۡئًا وَّلَوۡ کَثُرَتۡ ۙ وَاَنَّ اللّٰہَ مَعَ الۡمُؤۡمِنِیۡنَ ٪ ","8:30":"وَاِذۡ یَمۡکُرُ بِکَ الَّذِیۡنَ کَفَرُوۡا لِیُثۡبِتُوۡکَ اَوۡ یَقۡتُلُوۡکَ اَوۡ یُخۡرِجُوۡکَ ؕ وَیَمۡکُرُوۡنَ وَیَمۡکُرُ اللّٰہُ ؕ وَاللّٰہُ خَیۡرُ الۡمٰکِرِیۡنَ ","8:38":"قُلۡ لِّلَّذِیۡنَ کَفَرُوۡۤا اِنۡ یَّنۡتَہُوۡا یُغۡفَرۡ لَہُمۡ مَّا قَدۡ سَلَفَ ۚ وَاِنۡ یَّعُوۡدُوۡا فَقَدۡ مَضَتۡ سُنَّتُ الۡاَوَّلِیۡنَ ","8:39":"وَقَاتِلُوۡہُمۡ حَتّٰی لَا تَکُوۡنَ فِتۡنَۃٌ وَّیَکُوۡنَ الدِّیۡنُ کُلُّہٗ لِلّٰہِ ۚ فَاِنِ انۡتَہَوۡا فَاِنَّ اللّٰہَ بِمَا یَعۡمَلُوۡنَ بَصِیۡرٌ ","8:40":"وَاِنۡ تَوَلَّوۡا فَاعۡلَمُوۡۤا اَنَّ اللّٰہَ مَوۡلٰىکُمۡ ؕ نِعۡمَ الۡمَوۡلٰی وَنِعۡمَ النَّصِیۡرُ ","8:48":"وَاِذۡ زَیَّنَ لَہُمُ الشَّیۡطٰنُ اَعۡمَالَہُمۡ وَقَالَ لَا غَالِبَ لَکُمُ الۡیَوۡمَ مِنَ النَّاسِ وَاِنِّیۡ جَارٌ لَّکُمۡ ۚ فَلَمَّا تَرَآءَتِ الۡفِئَتٰنِ نَکَصَ عَلٰی عَقِبَیۡہِ وَقَالَ اِنِّیۡ بَرِیۡٓءٌ مِّنۡکُمۡ اِنِّیۡۤ اَرٰی مَا لَا تَرَوۡنَ اِنِّیۡۤ اَخَافُ اللّٰہَ ؕ وَاللّٰہُ شَدِیۡدُ الۡعِقَابِ ٪ ","8:50":"وَلَوۡ تَرٰۤی اِذۡ یَتَوَفَّی الَّذِیۡنَ کَفَرُوا ۙ الۡمَلٰٓئِکَۃُ یَضۡرِبُوۡنَ وُجُوۡہَہُمۡ وَاَدۡبَارَہُمۡ ۚ وَذُوۡقُوۡا عَذَابَ الۡحَرِیۡقِ ","8:57":"فَاِمَّا تَثۡقَفَنَّہُمۡ فِی الۡحَرۡبِ فَشَرِّدۡ بِہِمۡ مَّنۡ خَلۡفَہُمۡ لَعَلَّہُمۡ یَذَّکَّرُوۡنَ ","8:58":"وَاِمَّا تَخَافَنَّ مِنۡ قَوۡمٍ خِیَانَۃً فَانۡۢبِذۡ اِلَیۡہِمۡ عَلٰی سَوَآءٍ ؕ اِنَّ اللّٰہَ لَا یُحِبُّ الۡخَآئِنِیۡنَ ٪ ","8:60":"وَاَعِدُّوۡا لَہُمۡ مَّا اسۡتَطَعۡتُمۡ مِّنۡ قُوَّۃٍ وَّمِنۡ رِّبَاطِ الۡخَیۡلِ تُرۡہِبُوۡنَ بِہٖ عَدُوَّ اللّٰہِ وَعَدُوَّکُمۡ وَاٰخَرِیۡنَ مِنۡ دُوۡنِہِمۡ ۚ لَا تَعۡلَمُوۡنَہُمۡ ۚ اَللّٰہُ یَعۡلَمُہُمۡ ؕ وَمَا تُنۡفِقُوۡا مِنۡ شَیۡءٍ فِیۡ سَبِیۡلِ اللّٰہِ یُوَفَّ اِلَیۡکُمۡ وَاَنۡتُمۡ لَا تُظۡلَمُوۡنَ ","8:64":"یٰۤاَیُّہَا النَّبِیُّ حَسۡبُکَ اللّٰہُ وَمَنِ اتَّبَعَکَ مِنَ الۡمُؤۡمِنِیۡنَ ٪ ","8:65":"یٰۤاَیُّہَا النَّبِیُّ حَرِّضِ الۡمُؤۡمِنِیۡنَ عَلَی الۡقِتَالِ ؕ اِنۡ یَّکُنۡ مِّنۡکُمۡ عِشۡرُوۡنَ صٰبِرُوۡنَ یَغۡلِبُوۡا مِائَتَیۡنِ ۚ وَاِنۡ یَّکُنۡ مِّنۡکُمۡ مِّائَۃٌ یَّغۡلِبُوۡۤا اَلۡفًا مِّنَ الَّذِیۡنَ کَفَرُوۡا بِاَنَّہُمۡ قَوۡمٌ لَّا یَفۡقَہُوۡنَ ","8:66":"اَلۡـٰٔنَ خَفَّفَ اللّٰہُ عَنۡکُمۡ وَعَلِمَ اَنَّ فِیۡکُمۡ ضَعۡفًا ؕ فَاِنۡ یَّکُنۡ مِّنۡکُمۡ مِّائَۃٌ صَابِرَۃٌ یَّغۡلِبُوۡا مِائَتَیۡنِ ۚ وَاِنۡ یَّکُنۡ مِّنۡکُمۡ اَلۡفٌ یَّغۡلِبُوۡۤا اَلۡفَیۡنِ بِاِذۡنِ اللّٰہِ ؕ وَاللّٰہُ مَعَ الصّٰبِرِیۡنَ ","8:70":"یٰۤاَیُّہَا النَّبِیُّ قُلۡ لِّمَنۡ فِیۡۤ اَیۡدِیۡکُمۡ مِّنَ الۡاَسۡرٰۤی ۙ اِنۡ یَّعۡلَمِ اللّٰہُ فِیۡ قُلُوۡبِکُمۡ خَیۡرًا یُّؤۡتِکُمۡ خَیۡرًا مِّمَّاۤ اُخِذَ مِنۡکُمۡ وَیَغۡفِرۡ لَکُمۡ ؕ وَاللّٰہُ غَفُوۡرٌ رَّحِیۡمٌ ","8:71":"وَاِنۡ یُّرِیۡدُوۡا خِیَانَتَکَ فَقَدۡ خَانُوا اللّٰہَ مِنۡ قَبۡلُ فَاَمۡکَنَ مِنۡہُمۡ ؕ وَاللّٰہُ عَلِیۡمٌ حَکِیۡمٌ ","9:5":"فَاِذَا انۡسَلَخَ الۡاَشۡہُرُ الۡحُرُمُ فَاقۡتُلُوا الۡمُشۡرِکِیۡنَ حَیۡثُ وَجَدۡتُّمُوۡہُمۡ وَخُذُوۡہُمۡ وَاحۡصُرُوۡہُمۡ وَاقۡعُدُوۡا لَہُمۡ کُلَّ مَرۡصَدٍ ۚ فَاِنۡ تَابُوۡا وَاَقَامُوا الصَّلٰوۃَ وَاٰتَوُا الزَّکٰوۃَ فَخَلُّوۡا سَبِیۡلَہُمۡ ؕ اِنَّ اللّٰہَ غَفُوۡرٌ رَّحِیۡمٌ ","9:12":"وَاِنۡ نَّکَثُوۡۤا اَیۡمَانَہُمۡ مِّنۡۢ بَعۡدِ عَہۡدِہِمۡ وَطَعَنُوۡا فِیۡ دِیۡنِکُمۡ فَقَاتِلُوۡۤا اَئِمَّۃَ الۡکُفۡرِ ۙ اِنَّہُمۡ لَاۤ اَیۡمَانَ لَہُمۡ لَعَلَّہُمۡ یَنۡتَہُوۡنَ ","9:13":"اَلَا تُقَاتِلُوۡنَ قَوۡمًا نَّکَثُوۡۤا اَیۡمَانَہُمۡ وَہَمُّوۡا بِاِخۡرَاجِ الرَّسُوۡلِ وَہُمۡ بَدَءُوۡکُمۡ اَوَّلَ مَرَّۃٍ ؕ اَتَخۡشَوۡنَہُمۡ ۚ فَاللّٰہُ اَحَقُّ اَنۡ تَخۡشَوۡہُ اِنۡ کُنۡتُمۡ مُّؤۡمِنِیۡنَ ","9:14":"قَاتِلُوۡہُمۡ یُعَذِّبۡہُمُ اللّٰہُ بِاَیۡدِیۡکُمۡ وَیُخۡزِہِمۡ وَیَنۡصُرۡکُمۡ عَلَیۡہِمۡ وَیَشۡفِ صُدُوۡرَ قَوۡمٍ مُّؤۡمِنِیۡنَ ۙ ","9:15":"وَیُذۡہِبۡ غَیۡظَ قُلُوۡبِہِمۡ ؕ وَیَتُوۡبُ اللّٰہُ عَلٰی مَنۡ یَّشَآءُ ؕ وَاللّٰہُ عَلِیۡمٌ حَکِیۡمٌ ","9:26":"ثُمَّ اَنۡزَلَ اللّٰہُ سَکِیۡنَتَہٗ عَلٰی رَسُوۡلِہٖ وَعَلَی الۡمُؤۡمِنِیۡنَ وَاَنۡزَلَ جُنُوۡدًا لَّمۡ تَرَوۡہَا وَعَذَّبَ الَّذِیۡنَ کَفَرُوۡا ؕ وَذٰلِکَ جَزَآءُ الۡکٰفِرِیۡنَ ","9:29":"قَاتِلُوا الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِاللّٰہِ وَلَا بِالۡیَوۡمِ الۡاٰخِرِ وَلَا یُحَرِّمُوۡنَ مَا حَرَّمَ اللّٰہُ وَرَسُوۡلُہٗ وَلَا یَدِیۡنُوۡنَ دِیۡنَ الۡحَقِّ مِنَ الَّذِیۡنَ اُوۡتُوا الۡکِتٰبَ حَتّٰی یُعۡطُوا الۡجِزۡیَۃَ عَنۡ یَّدٍ وَّہُمۡ صٰغِرُوۡنَ ٪","9:36":"اِنَّ عِدَّۃَ الشُّہُوۡرِ عِنۡدَ اللّٰہِ اثۡنَا عَشَرَ شَہۡرًا فِیۡ کِتٰبِ اللّٰہِ یَوۡمَ خَلَقَ السَّمٰوٰتِ وَالۡاَرۡضَ مِنۡہَاۤ اَرۡبَعَۃٌ حُرُمٌ ؕ ذٰلِکَ الدِّیۡنُ الۡقَیِّمُ ۬ۙ فَلَا تَظۡلِمُوۡا فِیۡہِنَّ اَنۡفُسَکُمۡ وَقَاتِلُوا الۡمُشۡرِکِیۡنَ کَآفَّۃً کَمَا یُقَاتِلُوۡنَکُمۡ کَآفَّۃً ؕ وَاعۡلَمُوۡۤا اَنَّ اللّٰہَ مَعَ الۡمُتَّقِیۡنَ ","9:40":"اِلَّا تَنۡصُرُوۡہُ فَقَدۡ نَصَرَہُ اللّٰہُ اِذۡ اَخۡرَجَہُ الَّذِیۡنَ کَفَرُوۡا ثَانِیَ اثۡنَیۡنِ اِذۡ ہُمَا فِی الۡغَارِ اِذۡ یَقُوۡلُ لِصَاحِبِہٖ لَا تَحۡزَنۡ اِنَّ اللّٰہَ مَعَنَا ۚ فَاَنۡزَلَ اللّٰہُ سَکِیۡنَتَہٗ عَلَیۡہِ وَاَیَّدَہٗ بِجُنُوۡدٍ لَّمۡ تَرَوۡہَا وَجَعَلَ کَلِمَۃَ الَّذِیۡنَ کَفَرُوا السُّفۡلٰی ؕ وَکَلِمَۃُ اللّٰہِ ہِیَ الۡعُلۡیَا ؕ وَاللّٰہُ عَزِیۡزٌ حَکِیۡمٌ ","9:57":"لَوۡ یَجِدُوۡنَ مَلۡجَاً اَوۡ مَغٰرٰتٍ اَوۡ مُدَّخَلًا لَّوَلَّوۡا اِلَیۡہِ وَہُمۡ یَجۡمَحُوۡنَ ","9:64":"یَحۡذَرُ الۡمُنٰفِقُوۡنَ اَنۡ تُنَزَّلَ عَلَیۡہِمۡ سُوۡرَۃٌ تُنَبِّئُہُمۡ بِمَا فِیۡ قُلُوۡبِہِمۡ ؕ قُلِ اسۡتَہۡزِءُوۡا ۚ اِنَّ اللّٰہَ مُخۡرِجٌ مَّا تَحۡذَرُوۡنَ ","9:84":"وَلَا تُصَلِّ عَلٰۤی اَحَدٍ مِّنۡہُمۡ مَّاتَ اَبَدًا وَّلَا تَقُمۡ عَلٰی قَبۡرِہٖ ؕ اِنَّہُمۡ کَفَرُوۡا بِاللّٰہِ وَرَسُوۡلِہٖ وَمَاتُوۡا وَہُمۡ فٰسِقُوۡنَ ","9:85":"وَلَا تُعۡجِبۡکَ اَمۡوَالُہُمۡ وَاَوۡلَادُہُمۡ ؕ اِنَّمَا یُرِیۡدُ اللّٰہُ اَنۡ یُّعَذِّبَہُمۡ بِہَا فِی الدُّنۡیَا وَتَزۡہَقَ اَنۡفُسُہُمۡ وَہُمۡ کٰفِرُوۡنَ ","9:118":"وَّعَلَی الثَّلٰثَۃِ الَّذِیۡنَ خُلِّفُوۡا ؕ حَتّٰۤی اِذَا ضَاقَتۡ عَلَیۡہِمُ الۡاَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَیۡہِمۡ اَنۡفُسُہُمۡ وَظَنُّوۡۤا اَنۡ لَّا مَلۡجَاَ مِنَ اللّٰہِ اِلَّاۤ اِلَیۡہِ ؕ ثُمَّ تَابَ عَلَیۡہِمۡ لِیَتُوۡبُوۡا ؕ اِنَّ اللّٰہَ ہُوَ التَّوَّابُ الرَّحِیۡمُ ٪ ","9:123":"یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا قَاتِلُوا الَّذِیۡنَ یَلُوۡنَکُمۡ مِّنَ الۡکُفَّارِ وَلۡیَجِدُوۡا فِیۡکُمۡ غِلۡظَۃً ؕ وَاعۡلَمُوۡۤا اَنَّ اللّٰہَ مَعَ الۡمُتَّقِیۡنَ ","9:124":"وَاِذَا مَاۤ اُنۡزِلَتۡ سُوۡرَۃٌ فَمِنۡہُمۡ مَّنۡ یَّقُوۡلُ اَیُّکُمۡ زَادَتۡہُ ہٰذِہٖۤ اِیۡمَانًا ۚ فَاَمَّا الَّذِیۡنَ اٰمَنُوۡا فَزَادَتۡہُمۡ اِیۡمَانًا وَّہُمۡ یَسۡتَبۡشِرُوۡنَ ","9:125":"وَاَمَّا الَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ فَزَادَتۡہُمۡ رِجۡسًا اِلٰی رِجۡسِہِمۡ وَمَاتُوۡا وَہُمۡ کٰفِرُوۡنَ ","9:127":"وَاِذَا مَاۤ اُنۡزِلَتۡ سُوۡرَۃٌ نَّظَرَ بَعۡضُہُمۡ اِلٰی بَعۡضٍ ؕ ہَلۡ یَرٰىکُمۡ مِّنۡ اَحَدٍ ثُمَّ انۡصَرَفُوۡا ؕ صَرَفَ اللّٰہُ قُلُوۡبَہُمۡ بِاَنَّہُمۡ قَوۡمٌ لَّا یَفۡقَہُوۡنَ ","9:129":"فَاِنۡ تَوَلَّوۡا فَقُلۡ حَسۡبِیَ اللّٰہُ ۫٭ۖ لَاۤ اِلٰہَ اِلَّا ہُوَ ؕ عَلَیۡہِ تَوَکَّلۡتُ وَہُوَ رَبُّ الۡعَرۡشِ الۡعَظِیۡمِ ٪ ","10:31":"قُلۡ مَنۡ یَّرۡزُقُکُمۡ مِّنَ السَّمَآءِ وَالۡاَرۡضِ اَمَّنۡ یَّمۡلِکُ السَّمۡعَ وَالۡاَبۡصَارَ وَمَنۡ یُّخۡرِجُ الۡحَیَّ مِنَ الۡمَیِّتِ وَیُخۡرِجُ الۡمَیِّتَ مِنَ الۡحَیِّ وَمَنۡ یُّدَبِّرُ الۡاَمۡرَ ؕ فَسَیَقُوۡلُوۡنَ اللّٰہُ ۚ فَقُلۡ اَفَلَا تَتَّقُوۡنَ ","10:57":"یٰۤاَیُّہَا النَّاسُ قَدۡ جَآءَتۡکُمۡ مَّوۡعِظَۃٌ مِّنۡ رَّبِّکُمۡ وَشِفَآءٌ لِّمَا فِی الصُّدُوۡرِ ۬ۙ وَہُدًی وَّرَحۡمَۃٌ لِّلۡمُؤۡمِنِیۡنَ ","10:70":"مَتَاعٌ فِی الدُّنۡیَا ثُمَّ اِلَیۡنَا مَرۡجِعُہُمۡ ثُمَّ نُذِیۡقُہُمُ الۡعَذَابَ الشَّدِیۡدَ بِمَا کَانُوۡا یَکۡفُرُوۡنَ ٪ ","10:81":"فَلَمَّاۤ اَلۡقَوۡا قَالَ مُوۡسٰی مَا جِئۡتُمۡ بِہِ ۙ السِّحۡرُ ؕ اِنَّ اللّٰہَ سَیُبۡطِلُہٗ ؕ اِنَّ اللّٰہَ لَا یُصۡلِحُ عَمَلَ الۡمُفۡسِدِیۡنَ ","10:82":"وَیُحِقُّ اللّٰہُ الۡحَقَّ بِکَلِمٰتِہٖ وَلَوۡ کَرِہَ الۡمُجۡرِمُوۡنَ ٪ ","11:43":"قَالَ سَاٰوِیۡۤ اِلٰی جَبَلٍ یَّعۡصِمُنِیۡ مِنَ الۡمَآءِ ؕ قَالَ لَا عَاصِمَ الۡیَوۡمَ مِنۡ اَمۡرِ اللّٰہِ اِلَّا مَنۡ رَّحِمَ ۚ وَحَالَ بَیۡنَہُمَا الۡمَوۡجُ فَکَانَ مِنَ الۡمُغۡرَقِیۡنَ ","11:56":"اِنِّیۡ تَوَکَّلۡتُ عَلَی اللّٰہِ رَبِّیۡ وَرَبِّکُمۡ ؕ مَا مِنۡ دَآبَّۃٍ اِلَّا ہُوَ اٰخِذٌۢ بِنَاصِیَتِہَا ؕ اِنَّ رَبِّیۡ عَلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ","11:64":"وَیٰقَوۡمِ ہٰذِہٖ نَاقَۃُ اللّٰہِ لَکُمۡ اٰیَۃً فَذَرُوۡہَا تَاۡکُلۡ فِیۡۤ اَرۡضِ اللّٰہِ وَلَا تَمَسُّوۡہَا بِسُوۡٓءٍ فَیَاۡخُذَکُمۡ عَذَابٌ قَرِیۡبٌ ","11:78":"وَجَآءَہٗ قَوۡمُہٗ یُہۡرَعُوۡنَ اِلَیۡہِ ؕ وَمِنۡ قَبۡلُ کَانُوۡا یَعۡمَلُوۡنَ السَّیِّاٰتِ ؕ قَالَ یٰقَوۡمِ ہٰۤؤُلَآءِ بَنَاتِیۡ ہُنَّ اَطۡہَرُ لَکُمۡ فَاتَّقُوا اللّٰہَ وَلَا تُخۡزُوۡنِ فِیۡ ضَیۡفِیۡ ؕ اَلَـیۡسَ مِنۡکُمۡ رَجُلٌ رَّشِیۡدٌ ","11:118":"وَلَوۡ شَآءَ رَبُّکَ لَجَعَلَ النَّاسَ اُمَّۃً وَّاحِدَۃً وَّلَا یَزَالُوۡنَ مُخۡتَلِفِیۡنَ ۙ ","11:119":"اِلَّا مَنۡ رَّحِمَ رَبُّکَ ؕ وَلِذٰلِکَ خَلَقَہُمۡ ؕ وَتَمَّتۡ کَلِمَۃُ رَبِّکَ لَاَمۡلَـَٔنَّ جَہَنَّمَ مِنَ الۡجِنَّۃِ وَالنَّاسِ اَجۡمَعِیۡنَ ","12:5":"قَالَ یٰبُنَیَّ لَا تَقۡصُصۡ رُءۡیَاکَ عَلٰۤی اِخۡوَتِکَ فَیَکِیۡدُوۡا لَکَ کَیۡدًا ؕ اِنَّ الشَّیۡطٰنَ لِلۡاِنۡسَانِ عَدُوٌّ مُّبِیۡنٌ ","12:23":"وَرَاوَدَتۡہُ الَّتِیۡ ہُوَ فِیۡ بَیۡتِہَا عَنۡ نَّفۡسِہٖ وَغَلَّقَتِ الۡاَبۡوَابَ وَقَالَتۡ ہَیۡتَ لَکَ ؕ قَالَ مَعَاذَ اللّٰہِ اِنَّہٗ رَبِّیۡۤ اَحۡسَنَ مَثۡوَایَ ؕ اِنَّہٗ لَا یُفۡلِحُ الظّٰلِمُوۡنَ ","12:24":"وَلَقَدۡ ہَمَّتۡ بِہٖ ۚ وَہَمَّ بِہَا لَوۡلَاۤ اَنۡ رَّاٰ بُرۡہَانَ رَبِّہٖ ؕ کَذٰلِکَ لِنَصۡرِفَ عَنۡہُ السُّوۡٓءَ وَالۡفَحۡشَآءَ ؕ اِنَّہٗ مِنۡ عِبَادِنَا الۡمُخۡلَصِیۡنَ ","12:25":"وَاسۡتَبَقَا الۡبَابَ وَقَدَّتۡ قَمِیۡصَہٗ مِنۡ دُبُرٍ وَّاَلۡفَیَا سَیِّدَہَا لَدَا الۡبَابِ ؕ قَالَتۡ مَا جَزَآءُ مَنۡ اَرَادَ بِاَہۡلِکَ سُوۡٓءًا اِلَّاۤ اَنۡ یُّسۡجَنَ اَوۡ عَذَابٌ اَلِیۡمٌ ","12:26":"قَالَ ہِیَ رَاوَدَتۡنِیۡ عَنۡ نَّفۡسِیۡ وَشَہِدَ شَاہِدٌ مِّنۡ اَہۡلِہَا ۚ اِنۡ کَانَ قَمِیۡصُہٗ قُدَّ مِنۡ قُبُلٍ فَصَدَقَتۡ وَہُوَ مِنَ الۡکٰذِبِیۡنَ ","12:30":"وَقَالَ نِسۡوَۃٌ فِی الۡمَدِیۡنَۃِ امۡرَاَتُ الۡعَزِیۡزِ تُرَاوِدُ فَتٰىہَا عَنۡ نَّفۡسِہٖ ۚ قَدۡ شَغَفَہَا حُبًّا ؕ اِنَّا لَنَرٰىہَا فِیۡ ضَلٰلٍ مُّبِیۡنٍ ","12:31":"فَلَمَّا سَمِعَتۡ بِمَکۡرِہِنَّ اَرۡسَلَتۡ اِلَیۡہِنَّ وَاَعۡتَدَتۡ لَہُنَّ مُتَّکَاً وَّاٰتَتۡ کُلَّ وَاحِدَۃٍ مِّنۡہُنَّ سِکِّیۡنًا وَّقَالَتِ اخۡرُجۡ عَلَیۡہِنَّ ۚ فَلَمَّا رَاَیۡنَہٗۤ اَکۡبَرۡنَہٗ وَقَطَّعۡنَ اَیۡدِیَہُنَّ وَقُلۡنَ حَاشَ لِلّٰہِ مَا ہٰذَا بَشَرًا ؕ اِنۡ ہٰذَاۤ اِلَّا مَلَکٌ کَرِیۡمٌ ","12:32":"قَالَتۡ فَذٰلِکُنَّ الَّذِیۡ لُمۡتُنَّنِیۡ فِیۡہِ ؕ وَلَقَدۡ رَاوَدۡتُّہٗ عَنۡ نَّفۡسِہٖ فَاسۡتَعۡصَمَ ؕ وَلَئِنۡ لَّمۡ یَفۡعَلۡ مَاۤ اٰمُرُہٗ لَیُسۡجَنَنَّ وَلَیَکُوۡنًا مِّنَ الصّٰغِرِیۡنَ ","12:33":"قَالَ رَبِّ السِّجۡنُ اَحَبُّ اِلَیَّ مِمَّا یَدۡعُوۡنَنِیۡۤ اِلَیۡہِ ۚ وَاِلَّا تَصۡرِفۡ عَنِّیۡ کَیۡدَہُنَّ اَصۡبُ اِلَیۡہِنَّ وَاَکُنۡ مِّنَ الۡجٰہِلِیۡنَ ","12:34":"فَاسۡتَجَابَ لَہٗ رَبُّہٗ فَصَرَفَ عَنۡہُ کَیۡدَہُنَّ ؕ اِنَّہٗ ہُوَ السَّمِیۡعُ الۡعَلِیۡمُ ","12:50":"وَقَالَ الۡمَلِکُ ائۡتُوۡنِیۡ بِہٖ ۚ فَلَمَّا جَآءَہُ الرَّسُوۡلُ قَالَ ارۡجِعۡ اِلٰی رَبِّکَ فَسۡـَٔلۡہُ مَا بَالُ النِّسۡوَۃِ الّٰتِیۡ قَطَّعۡنَ اَیۡدِیَہُنَّ ؕ اِنَّ رَبِّیۡ بِکَیۡدِہِنَّ عَلِیۡمٌ ","12:51":"قَالَ مَا خَطۡبُکُنَّ اِذۡ رَاوَدۡتُّنَّ یُوۡسُفَ عَنۡ نَّفۡسِہٖ ؕ قُلۡنَ حَاشَ لِلّٰہِ مَا عَلِمۡنَا عَلَیۡہِ مِنۡ سُوۡٓءٍ ؕ قَالَتِ امۡرَاَتُ الۡعَزِیۡزِ الۡـٰٔنَ حَصۡحَصَ الۡحَقُّ ۫ اَنَا رَاوَدۡتُّہٗ عَنۡ نَّفۡسِہٖ وَاِنَّہٗ لَمِنَ الصّٰدِقِیۡنَ ","12:53":"وَمَاۤ اُبَرِّئُ نَفۡسِیۡ ۚ اِنَّ النَّفۡسَ لَاَمَّارَۃٌۢ بِالسُّوۡٓءِ اِلَّا مَا رَحِمَ رَبِّیۡ ؕ اِنَّ رَبِّیۡ غَفُوۡرٌ رَّحِیۡمٌ ","12:67":"وَقَالَ یٰبَنِیَّ لَا تَدۡخُلُوۡا مِنۡۢ بَابٍ وَّاحِدٍ وَّادۡخُلُوۡا مِنۡ اَبۡوَابٍ مُّتَفَرِّقَۃٍ ؕ وَمَاۤ اُغۡنِیۡ عَنۡکُمۡ مِّنَ اللّٰہِ مِنۡ شَیۡءٍ ؕ اِنِ الۡحُکۡمُ اِلَّا لِلّٰہِ ؕ عَلَیۡہِ تَوَکَّلۡتُ ۚ وَعَلَیۡہِ فَلۡیَتَوَکَّلِ الۡمُتَوَکِّلُوۡنَ ","12:84":"وَتَوَلّٰی عَنۡہُمۡ وَقَالَ یٰۤاَسَفٰی عَلٰی یُوۡسُفَ وَابۡیَضَّتۡ عَیۡنٰہُ مِنَ الۡحُزۡنِ فَہُوَ کَظِیۡمٌ ","12:100":"وَرَفَعَ اَبَوَیۡہِ عَلَی الۡعَرۡشِ وَخَرُّوۡا لَہٗ سُجَّدًا ۚ وَقَالَ یٰۤاَبَتِ ہٰذَا تَاۡوِیۡلُ رُءۡیَایَ مِنۡ قَبۡلُ ۫ قَدۡ جَعَلَہَا رَبِّیۡ حَقًّا ؕ وَقَدۡ اَحۡسَنَ بِیۡۤ اِذۡ اَخۡرَجَنِیۡ مِنَ السِّجۡنِ وَجَآءَ بِکُمۡ مِّنَ الۡبَدۡوِ مِنۡۢ بَعۡدِ اَنۡ نَّزَغَ الشَّیۡطٰنُ بَیۡنِیۡ وَبَیۡنَ اِخۡوَتِیۡ ؕ اِنَّ رَبِّیۡ لَطِیۡفٌ لِّمَا یَشَآءُ ؕ اِنَّہٗ ہُوَ الۡعَلِیۡمُ الۡحَکِیۡمُ ","13:31":"وَلَوۡ اَنَّ قُرۡاٰنًا سُیِّرَتۡ بِہِ الۡجِبَالُ اَوۡ قُطِّعَتۡ بِہِ الۡاَرۡضُ اَوۡ کُلِّمَ بِہِ الۡمَوۡتٰی ؕ بَلۡ لِّلّٰہِ الۡاَمۡرُ جَمِیۡعًا ؕ اَفَلَمۡ یَایۡـَٔسِ الَّذِیۡنَ اٰمَنُوۡۤا اَنۡ لَّوۡ یَشَآءُ اللّٰہُ لَہَدَی النَّاسَ جَمِیۡعًا ؕ وَلَا یَزَالُ الَّذِیۡنَ کَفَرُوۡا تُصِیۡبُہُمۡ بِمَا صَنَعُوۡا قَارِعَۃٌ اَوۡ تَحُلُّ قَرِیۡبًا مِّنۡ دَارِہِمۡ حَتّٰی یَاۡتِیَ وَعۡدُ اللّٰہِ ؕ اِنَّ اللّٰہَ لَا یُخۡلِفُ الۡمِیۡعَادَ ٪ ","14:13":"وَقَالَ الَّذِیۡنَ کَفَرُوۡا لِرُسُلِہِمۡ لَنُخۡرِجَنَّکُمۡ مِّنۡ اَرۡضِنَاۤ اَوۡ لَتَعُوۡدُنَّ فِیۡ مِلَّتِنَا ؕ فَاَوۡحٰۤی اِلَیۡہِمۡ رَبُّہُمۡ لَنُہۡلِکَنَّ الظّٰلِمِیۡنَ ۙ ","14:15":"وَاسۡتَفۡتَحُوۡا وَخَابَ کُلُّ جَبَّارٍ عَنِیۡدٍ ۙ ","14:16":"مِّنۡ وَّرَآئِہٖ جَہَنَّمُ وَیُسۡقٰی مِنۡ مَّآءٍ صَدِیۡدٍ ۙ ","14:17":"یَّتَجَرَّعُہٗ وَلَا یَکَادُ یُسِیۡغُہٗ وَیَاۡتِیۡہِ الۡمَوۡتُ مِنۡ کُلِّ مَکَانٍ وَّمَا ہُوَ بِمَیِّتٍ ؕ وَمِنۡ وَّرَآئِہٖ عَذَابٌ غَلِیۡظٌ ","14:22":"وَقَالَ الشَّیۡطٰنُ لَمَّا قُضِیَ الۡاَمۡرُ اِنَّ اللّٰہَ وَعَدَکُمۡ وَعۡدَ الۡحَقِّ وَوَعَدۡتُّکُمۡ فَاَخۡلَفۡتُکُمۡ ؕ وَمَا کَانَ لِیَ عَلَیۡکُمۡ مِّنۡ سُلۡطٰنٍ اِلَّاۤ اَنۡ دَعَوۡتُکُمۡ فَاسۡتَجَبۡتُمۡ لِیۡ ۚ فَلَا تَلُوۡمُوۡنِیۡ وَلُوۡمُوۡۤا اَنۡفُسَکُمۡ ؕ مَاۤ اَنَا بِمُصۡرِخِکُمۡ وَمَاۤ اَنۡتُمۡ بِمُصۡرِخِیَّ ؕ اِنِّیۡ کَفَرۡتُ بِمَاۤ اَشۡرَکۡتُمُوۡنِ مِنۡ قَبۡلُ ؕ اِنَّ الظّٰلِمِیۡنَ لَہُمۡ عَذَابٌ اَلِیۡمٌ ","14:30":"وَجَعَلُوۡا لِلّٰہِ اَنۡدَادًا لِّیُضِلُّوۡا عَنۡ سَبِیۡلِہٖ ؕ قُلۡ تَمَتَّعُوۡا فَاِنَّ مَصِیۡرَکُمۡ اِلَی النَّارِ ","14:49":"وَتَـرَی الۡمُجۡرِمِیۡنَ یَوۡمَئِذٍ مُّقَرَّنِیۡنَ فِی الۡاَصۡفَادِ ۚ ","14:50":"سَرَابِیۡلُہُمۡ مِّنۡ قَطِرَانٍ وَّتَغۡشٰی وُجُوۡہَہُمُ النَّارُ ۙ","15:16":"وَلَقَدۡ جَعَلۡنَا فِی السَّمَآءِ بُرُوۡجًا وَّزَیَّنّٰہَا لِلنّٰظِرِیۡنَ ۙ ","15:18":"اِلَّا مَنِ اسۡتَرَقَ السَّمۡعَ فَاَتۡبَعَہٗ شِہَابٌ مُّبِیۡنٌ ","15:26":"وَلَقَدۡ خَلَقۡنَا الۡاِنۡسَانَ مِنۡ صَلۡصَالٍ مِّنۡ حَمَاٍ مَّسۡنُوۡنٍ ۚ ","15:27":"وَالۡجَآنَّ خَلَقۡنٰہُ مِنۡ قَبۡلُ مِنۡ نَّارِ السَّمُوۡمِ ","15:28":"وَاِذۡ قَالَ رَبُّکَ لِلۡمَلٰٓئِکَۃِ اِنِّیۡ خَالِقٌۢ بَشَرًا مِّنۡ صَلۡصَالٍ مِّنۡ حَمَاٍ مَّسۡنُوۡنٍ ","15:29":"فَاِذَا سَوَّیۡتُہٗ وَنَفَخۡتُ فِیۡہِ مِنۡ رُّوۡحِیۡ فَقَعُوۡا لَہٗ سٰجِدِیۡنَ ","15:30":"فَسَجَدَ الۡمَلٰٓئِکَۃُ کُلُّہُمۡ اَجۡمَعُوۡنَ ۙ ","15:31":"اِلَّاۤ اِبۡلِیۡسَ ؕ اَبٰۤی اَنۡ یَّکُوۡنَ مَعَ السّٰجِدِیۡنَ ","15:32":"قَالَ یٰۤـاِبۡلِیۡسُ مَا لَکَ اَلَّا تَکُوۡنَ مَعَ السّٰجِدِیۡنَ ","15:35":"وَّاِنَّ عَلَیۡکَ اللَّعۡنَۃَ اِلٰی یَوۡمِ الدِّیۡنِ ","15:37":"قَالَ فَاِنَّکَ مِنَ الۡمُنۡظَرِیۡنَ ۙ ","15:38":"اِلٰی یَوۡمِ الۡوَقۡتِ الۡمَعۡلُوۡمِ ","15:39":"قَالَ رَبِّ بِمَاۤ اَغۡوَیۡتَنِیۡ لَاُزَیِّنَنَّ لَہُمۡ فِی الۡاَرۡضِ وَلَاُغۡوِیَنَّہُمۡ اَجۡمَعِیۡنَ ۙ ","15:42":"اِنَّ عِبَادِیۡ لَیۡسَ لَکَ عَلَیۡہِمۡ سُلۡطٰنٌ اِلَّا مَنِ اتَّبَعَکَ مِنَ الۡغٰوِیۡنَ ","15:88":"لَا تَمُدَّنَّ عَیۡنَیۡکَ اِلٰی مَا مَتَّعۡنَا بِہٖۤ اَزۡوَاجًا مِّنۡہُمۡ وَلَا تَحۡزَنۡ عَلَیۡہِمۡ وَاخۡفِضۡ جَنَاحَکَ لِلۡمُؤۡمِنِیۡنَ ","16:63":"تَاللّٰہِ لَقَدۡ اَرۡسَلۡنَاۤ اِلٰۤی اُمَمٍ مِّنۡ قَبۡلِکَ فَزَیَّنَ لَہُمُ الشَّیۡطٰنُ اَعۡمَالَہُمۡ فَہُوَ وَلِیُّہُمُ الۡیَوۡمَ وَلَہُمۡ عَذَابٌ اَلِیۡمٌ ","16:69":"ثُمَّ کُلِیۡ مِنۡ کُلِّ الثَّمَرٰتِ فَاسۡلُکِیۡ سُبُلَ رَبِّکِ ذُلُلًا ؕ یَخۡرُجُ مِنۡۢ بُطُوۡنِہَا شَرَابٌ مُّخۡتَلِفٌ اَلۡوَانُہٗ فِیۡہِ شِفَآءٌ لِّلنَّاسِ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیَۃً لِّقَوۡمٍ یَّتَفَکَّرُوۡنَ ","16:78":"وَاللّٰہُ اَخۡرَجَکُمۡ مِّنۡۢ بُطُوۡنِ اُمَّہٰتِکُمۡ لَا تَعۡلَمُوۡنَ شَیۡئًا ۙ وَّجَعَلَ لَکُمُ السَّمۡعَ وَالۡاَبۡصَارَ وَالۡاَفۡـِٕدَۃَ ۙ لَعَلَّکُمۡ تَشۡکُرُوۡنَ ","16:90":"اِنَّ اللّٰہَ یَاۡمُرُ بِالۡعَدۡلِ وَالۡاِحۡسَانِ وَاِیۡتَآیِٔ ذِی الۡقُرۡبٰی وَیَنۡہٰی عَنِ الۡفَحۡشَآءِ وَالۡمُنۡکَرِ وَالۡبَغۡیِ ۚ یَعِظُکُمۡ لَعَلَّکُمۡ تَذَکَّرُوۡنَ ","16:99":"اِنَّہٗ لَیۡسَ لَہٗ سُلۡطٰنٌ عَلَی الَّذِیۡنَ اٰمَنُوۡا وَعَلٰی رَبِّہِمۡ یَتَوَکَّلُوۡنَ ","16:100":"اِنَّمَا سُلۡطٰنُہٗ عَلَی الَّذِیۡنَ یَتَوَلَّوۡنَہٗ وَالَّذِیۡنَ ہُمۡ بِہٖ مُشۡرِکُوۡنَ ٪ ","16:108":"اُولٰٓئِکَ الَّذِیۡنَ طَبَعَ اللّٰہُ عَلٰی قُلُوۡبِہِمۡ وَسَمۡعِہِمۡ وَاَبۡصَارِہِمۡ ۚ وَاُولٰٓئِکَ ہُمُ الۡغٰفِلُوۡنَ ","17:4":"وَقَضَیۡنَاۤ اِلٰی بَنِیۡۤ اِسۡرَآءِیۡلَ فِی الۡکِتٰبِ لَتُفۡسِدُنَّ فِی الۡاَرۡضِ مَرَّتَیۡنِ وَلَتَعۡلُنَّ عُلُوًّا کَبِیۡرًا ","17:5":"فَاِذَا جَآءَ وَعۡدُ اُوۡلٰىہُمَا بَعَثۡنَا عَلَیۡکُمۡ عِبَادًا لَّنَاۤ اُولِیۡ بَاۡسٍ شَدِیۡدٍ فَجَاسُوۡا خِلٰلَ الدِّیَارِ ؕ وَکَانَ وَعۡدًا مَّفۡعُوۡلًا ","17:16":"وَاِذَاۤ اَرَدۡنَاۤ اَنۡ نُّہۡلِکَ قَرۡیَۃً اَمَرۡنَا مُتۡرَفِیۡہَا فَفَسَقُوۡا فِیۡہَا فَحَقَّ عَلَیۡہَا الۡقَوۡلُ فَدَمَّرۡنٰہَا تَدۡمِیۡرًا ","17:26":"وَاٰتِ ذَا الۡقُرۡبٰی حَقَّہٗ وَالۡمِسۡکِیۡنَ وَابۡنَ السَّبِیۡلِ وَلَا تُبَذِّرۡ تَبۡذِیۡرًا ","17:27":"اِنَّ الۡمُبَذِّرِیۡنَ کَانُوۡۤا اِخۡوَانَ الشَّیٰطِیۡنِ ؕ وَکَانَ الشَّیۡطٰنُ لِرَبِّہٖ کَفُوۡرًا ","17:32":"وَلَا تَقۡرَبُوا الزِّنٰۤی اِنَّہٗ کَانَ فَاحِشَۃً ؕ وَسَآءَ سَبِیۡلًا ","17:33":"وَلَا تَقۡتُلُوا النَّفۡسَ الَّتِیۡ حَرَّمَ اللّٰہُ اِلَّا بِالۡحَقِّ ؕ وَمَنۡ قُتِلَ مَظۡلُوۡمًا فَقَدۡ جَعَلۡنَا لِوَلِیِّہٖ سُلۡطٰنًا فَلَا یُسۡرِفۡ فِّی الۡقَتۡلِ ؕ اِنَّہٗ کَانَ مَنۡصُوۡرًا ","17:45":"وَاِذَا قَرَاۡتَ الۡقُرۡاٰنَ جَعَلۡنَا بَیۡنَکَ وَبَیۡنَ الَّذِیۡنَ لَا یُؤۡمِنُوۡنَ بِالۡاٰخِرَۃِ حِجَابًا مَّسۡتُوۡرًا ۙ","17:53":"وَقُلۡ لِّعِبَادِیۡ یَقُوۡلُوا الَّتِیۡ ہِیَ اَحۡسَنُ ؕ اِنَّ الشَّیۡطٰنَ یَنۡزَغُ بَیۡنَہُمۡ ؕ اِنَّ الشَّیۡطٰنَ کَانَ لِلۡاِنۡسَانِ عَدُوًّا مُّبِیۡنًا ","17:61":"وَاِذۡ قُلۡنَا لِلۡمَلٰٓئِکَۃِ اسۡجُدُوۡا لِاٰدَمَ فَسَجَدُوۡۤا اِلَّاۤ اِبۡلِیۡسَ ؕ قَالَ ءَاَسۡجُدُ لِمَنۡ خَلَقۡتَ طِیۡنًا ۚ ","17:62":"قَالَ اَرَءَیۡتَکَ ہٰذَا الَّذِیۡ کَرَّمۡتَ عَلَیَّ ۫ لَئِنۡ اَخَّرۡتَنِ اِلٰی یَوۡمِ الۡقِیٰمَۃِ لَاَحۡتَنِکَنَّ ذُرِّیَّتَہٗۤ اِلَّا قَلِیۡلًا ","17:63":"قَالَ اذۡہَبۡ فَمَنۡ تَبِعَکَ مِنۡہُمۡ فَاِنَّ جَہَنَّمَ جَزَآؤُکُمۡ جَزَآءً مَّوۡفُوۡرًا ","17:64":"وَاسۡتَفۡزِزۡ مَنِ اسۡتَطَعۡتَ مِنۡہُمۡ بِصَوۡتِکَ وَاَجۡلِبۡ عَلَیۡہِمۡ بِخَیۡلِکَ وَرَجِلِکَ وَشَارِکۡہُمۡ فِی الۡاَمۡوَالِ وَالۡاَوۡلَادِ وَعِدۡہُمۡ ؕ وَمَا یَعِدُہُمُ الشَّیۡطٰنُ اِلَّا غُرُوۡرًا ","17:65":"اِنَّ عِبَادِیۡ لَیۡسَ لَکَ عَلَیۡہِمۡ سُلۡطٰنٌ ؕ وَکَفٰی بِرَبِّکَ وَکِیۡلًا ","17:74":"وَلَوۡلَاۤ اَنۡ ثَبَّتۡنٰکَ لَقَدۡ کِدۡتَّ تَرۡکَنُ اِلَیۡہِمۡ شَیۡئًا قَلِیۡلًا ٭ۙ ","17:75":"اِذًا لَّاَذَقۡنٰکَ ضِعۡفَ الۡحَیٰوۃِ وَضِعۡفَ الۡمَمَاتِ ثُمَّ لَا تَجِدُ لَکَ عَلَیۡنَا نَصِیۡرًا ","17:81":"وَقُلۡ جَآءَ الۡحَقُّ وَزَہَقَ الۡبَاطِلُ ؕ اِنَّ الۡبَاطِلَ کَانَ زَہُوۡقًا ","17:82":"وَنُنَزِّلُ مِنَ الۡقُرۡاٰنِ مَا ہُوَ شِفَآءٌ وَّرَحۡمَۃٌ لِّلۡمُؤۡمِنِیۡنَ ۙ وَلَا یَزِیۡدُ الظّٰلِمِیۡنَ اِلَّا خَسَارًا ","17:88":"قُلۡ لَّئِنِ اجۡتَمَعَتِ الۡاِنۡسُ وَالۡجِنُّ عَلٰۤی اَنۡ یَّاۡتُوۡا بِمِثۡلِ ہٰذَا الۡقُرۡاٰنِ لَا یَاۡتُوۡنَ بِمِثۡلِہٖ وَلَوۡ کَانَ بَعۡضُہُمۡ لِبَعۡضٍ ظَہِیۡرًا ","17:98":"ذٰلِکَ جَزَآؤُہُمۡ بِاَنَّہُمۡ کَفَرُوۡا بِاٰیٰتِنَا وَقَالُوۡۤا ءَاِذَا کُنَّا عِظَامًا وَّرُفَاتًا ءَاِنَّا لَمَبۡعُوۡثُوۡنَ خَلۡقًا جَدِیۡدًا ","18:29":"وَقُلِ الۡحَقُّ مِنۡ رَّبِّکُمۡ ۟ فَمَنۡ شَآءَ فَلۡیُؤۡمِنۡ وَّمَنۡ شَآءَ فَلۡیَکۡفُرۡ ۙ اِنَّاۤ اَعۡتَدۡنَا لِلظّٰلِمِیۡنَ نَارًا ۙ اَحَاطَ بِہِمۡ سُرَادِقُہَا ؕ وَاِنۡ یَّسۡتَغِیۡثُوۡا یُغَاثُوۡا بِمَآءٍ کَالۡمُہۡلِ یَشۡوِی الۡوُجُوۡہَ ؕ بِئۡسَ الشَّرَابُ ؕ وَسَآءَتۡ مُرۡتَفَقًا ","18:39":"وَلَوۡلَاۤ اِذۡ دَخَلۡتَ جَنَّتَکَ قُلۡتَ مَا شَآءَ اللّٰہُ ۙ لَا قُوَّۃَ اِلَّا بِاللّٰہِ ۚ اِنۡ تَرَنِ اَنَا اَقَلَّ مِنۡکَ مَالًا وَّوَلَدًا ۚ ","18:40":"فَعَسٰی رَبِّیۡۤ اَنۡ یُّؤۡتِیَنِ خَیۡرًا مِّنۡ جَنَّتِکَ وَیُرۡسِلَ عَلَیۡہَا حُسۡبَانًا مِّنَ السَّمَآءِ فَتُصۡبِحَ صَعِیۡدًا زَلَقًا ۙ ","18:50":"وَاِذۡ قُلۡنَا لِلۡمَلٰٓئِکَۃِ اسۡجُدُوۡا لِاٰدَمَ فَسَجَدُوۡۤا اِلَّاۤ اِبۡلِیۡسَ ؕ کَانَ مِنَ الۡجِنِّ فَفَسَقَ عَنۡ اَمۡرِ رَبِّہٖ ؕ اَفَتَتَّخِذُوۡنَہٗ وَذُرِّیَّتَہٗۤ اَوۡلِیَآءَ مِنۡ دُوۡنِیۡ وَہُمۡ لَکُمۡ عَدُوٌّ ؕ بِئۡسَ لِلظّٰلِمِیۡنَ بَدَلًا ","18:57":"وَمَنۡ اَظۡلَمُ مِمَّنۡ ذُکِّرَ بِاٰیٰتِ رَبِّہٖ فَاَعۡرَضَ عَنۡہَا وَنَسِیَ مَا قَدَّمَتۡ یَدٰہُ ؕ اِنَّا جَعَلۡنَا عَلٰی قُلُوۡبِہِمۡ اَکِنَّۃً اَنۡ یَّفۡقَہُوۡہُ وَفِیۡۤ اٰذَانِہِمۡ وَقۡرًا ؕ وَاِنۡ تَدۡعُہُمۡ اِلَی الۡہُدٰی فَلَنۡ یَّہۡتَدُوۡۤا اِذًا اَبَدًا ","18:95":"قَالَ مَا مَکَّنِّیۡ فِیۡہِ رَبِّیۡ خَیۡرٌ فَاَعِیۡنُوۡنِیۡ بِقُوَّۃٍ اَجۡعَلۡ بَیۡنَکُمۡ وَبَیۡنَہُمۡ رَدۡمًا ۙ ","19:4":"قَالَ رَبِّ اِنِّیۡ وَہَنَ الۡعَظۡمُ مِنِّیۡ وَاشۡتَعَلَ الرَّاۡسُ شَیۡبًا وَّلَمۡ اَکُنۡۢ بِدُعَآئِکَ رَبِّ شَقِیًّا ","19:17":"فَاتَّخَذَتۡ مِنۡ دُوۡنِہِمۡ حِجَابًا ۪۟ فَاَرۡسَلۡنَاۤ اِلَیۡہَا رُوۡحَنَا فَتَمَثَّلَ لَہَا بَشَرًا سَوِیًّا ","19:18":"قَالَتۡ اِنِّیۡۤ اَعُوۡذُ بِالرَّحۡمٰنِ مِنۡکَ اِنۡ کُنۡتَ تَقِیًّا ","19:20":"قَالَتۡ اَنّٰی یَکُوۡنُ لِیۡ غُلٰمٌ وَّلَمۡ یَمۡسَسۡنِیۡ بَشَرٌ وَّلَمۡ اَکُ بَغِیًّا ","19:28":"یٰۤاُخۡتَ ہٰرُوۡنَ مَا کَانَ اَبُوۡکِ امۡرَاَ سَوۡءٍ وَّمَا کَانَتۡ اُمُّکِ بَغِیًّا ۖۚ ","19:41":"وَاذۡکُرۡ فِی الۡکِتٰبِ اِبۡرٰہِیۡمَ ۬ؕ اِنَّہٗ کَانَ صِدِّیۡقًا نَّبِیًّا ","19:42":"اِذۡ قَالَ لِاَبِیۡہِ یٰۤاَبَتِ لِمَ تَعۡبُدُ مَا لَا یَسۡمَعُ وَلَا یُبۡصِرُ وَلَا یُغۡنِیۡ عَنۡکَ شَیۡئًا ","19:43":"یٰۤاَبَتِ اِنِّیۡ قَدۡ جَآءَنِیۡ مِنَ الۡعِلۡمِ مَا لَمۡ یَاۡتِکَ فَاتَّبِعۡنِیۡۤ اَہۡدِکَ صِرَاطًا سَوِیًّا ","19:45":"یٰۤاَبَتِ اِنِّیۡۤ اَخَافُ اَنۡ یَّمَسَّکَ عَذَابٌ مِّنَ الرَّحۡمٰنِ فَتَکُوۡنَ لِلشَّیۡطٰنِ وَلِیًّا ","19:68":"فَوَرَبِّکَ لَنَحۡشُرَنَّہُمۡ وَالشَّیٰطِیۡنَ ثُمَّ لَنُحۡضِرَنَّہُمۡ حَوۡلَ جَہَنَّمَ جِثِیًّا ۚ ","19:69":"ثُمَّ لَنَنۡزِعَنَّ مِنۡ کُلِّ شِیۡعَۃٍ اَیُّہُمۡ اَشَدُّ عَلَی الرَّحۡمٰنِ عِتِیًّا ۚ ","19:70":"ثُمَّ لَنَحۡنُ اَعۡلَمُ بِالَّذِیۡنَ ہُمۡ اَوۡلٰی بِہَا صِلِیًّا ","19:71":"وَاِنۡ مِّنۡکُمۡ اِلَّا وَارِدُہَا ۚ کَانَ عَلٰی رَبِّکَ حَتۡمًا مَّقۡضِیًّا ۚ ","19:72":"ثُمَّ نُنَجِّی الَّذِیۡنَ اتَّقَوۡا وَّنَذَرُ الظّٰلِمِیۡنَ فِیۡہَا جِثِیًّا ","19:83":"اَلَمۡ تَرَ اَنَّـاۤ اَرۡسَلۡنَا الشَّیٰطِیۡنَ عَلَی الۡکٰفِرِیۡنَ تَؤُزُّہُمۡ اَزًّا ۙ ","19:84":"فَلَا تَعۡجَلۡ عَلَیۡہِمۡ ؕ اِنَّمَا نَعُدُّ لَہُمۡ عَدًّا ۚ ","19:86":"وَّنَسُوۡقُ الۡمُجۡرِمِیۡنَ اِلٰی جَہَنَّمَ وِرۡدًا ۘ ","20:25":"قَالَ رَبِّ اشۡرَحۡ لِیۡ صَدۡرِیۡ ۙ ","20:26":"وَیَسِّرۡ لِیۡۤ اَمۡرِیۡ ۙ","20:27":"وَاحۡلُلۡ عُقۡدَۃً مِّنۡ لِّسَانِیۡ ۙ ","20:28":"یَفۡقَہُوۡا قَوۡلِیۡ ۪ ","20:55":"مِنۡہَا خَلَقۡنٰکُمۡ وَفِیۡہَا نُعِیۡدُکُمۡ وَمِنۡہَا نُخۡرِجُکُمۡ تَارَۃً اُخۡرٰی ","20:69":"وَاَلۡقِ مَا فِیۡ یَمِیۡنِکَ تَلۡقَفۡ مَا صَنَعُوۡا ؕ اِنَّمَا صَنَعُوۡا کَیۡدُ سٰحِرٍ ؕ وَلَا یُفۡلِحُ السَّاحِرُ حَیۡثُ اَتٰی ","20:97":"قَالَ فَاذۡہَبۡ فَاِنَّ لَکَ فِی الۡحَیٰوۃِ اَنۡ تَقُوۡلَ لَا مِسَاسَ ۪ وَاِنَّ لَکَ مَوۡعِدًا لَّنۡ تُخۡلَفَہٗ ۚ وَانۡظُرۡ اِلٰۤی اِلٰـہِکَ الَّذِیۡ ظَلۡتَ عَلَیۡہِ عَاکِفًا ؕ لَنُحَرِّقَنَّہٗ ثُمَّ لَنَنۡسِفَنَّہٗ فِی الۡیَمِّ نَسۡفًا ","20:112":"وَمَنۡ یَّعۡمَلۡ مِنَ الصّٰلِحٰتِ وَہُوَ مُؤۡمِنٌ فَلَا یَخٰفُ ظُلۡمًا وَّلَا ہَضۡمًا ","20:113":"وَکَذٰلِکَ اَنۡزَلۡنٰہُ قُرۡاٰنًا عَرَبِیًّا وَّصَرَّفۡنَا فِیۡہِ مِنَ الۡوَعِیۡدِ لَعَلَّہُمۡ یَتَّقُوۡنَ اَوۡ یُحۡدِثُ لَہُمۡ ذِکۡرًا ","20:114":"فَتَعٰلَی اللّٰہُ الۡمَلِکُ الۡحَقُّ ۚ وَلَا تَعۡجَلۡ بِالۡقُرۡاٰنِ مِنۡ قَبۡلِ اَنۡ یُّقۡضٰۤی اِلَیۡکَ وَحۡیُہٗ ۫ وَقُلۡ رَّبِّ زِدۡنِیۡ عِلۡمًا ","20:115":"وَلَقَدۡ عَہِدۡنَاۤ اِلٰۤی اٰدَمَ مِنۡ قَبۡلُ فَنَسِیَ وَلَمۡ نَجِدۡ لَہٗ عَزۡمًا ٪ ","20:116":"وَاِذۡ قُلۡنَا لِلۡمَلٰٓئِکَۃِ اسۡجُدُوۡا لِاٰدَمَ فَسَجَدُوۡۤا اِلَّاۤ اِبۡلِیۡسَ ؕ اَبٰی ","20:117":"فَقُلۡنَا یٰۤـاٰدَمُ اِنَّ ہٰذَا عَدُوٌّ لَّکَ وَلِزَوۡجِکَ فَلَا یُخۡرِجَنَّکُمَا مِنَ الۡجَنَّۃِ فَتَشۡقٰی ","20:118":"اِنَّ لَکَ اَلَّا تَجُوۡعَ فِیۡہَا وَلَا تَعۡرٰی ۙ ","20:119":"وَاَنَّکَ لَا تَظۡمَؤُا فِیۡہَا وَلَا تَضۡحٰی ","20:120":"فَوَسۡوَسَ اِلَیۡہِ الشَّیۡطٰنُ قَالَ یٰۤـاٰدَمُ ہَلۡ اَدُلُّکَ عَلٰی شَجَرَۃِ الۡخُلۡدِ وَمُلۡکٍ لَّا یَبۡلٰی ","20:121":"فَاَکَلَا مِنۡہَا فَبَدَتۡ لَہُمَا سَوۡاٰتُہُمَا وَطَفِقَا یَخۡصِفٰنِ عَلَیۡہِمَا مِنۡ وَّرَقِ الۡجَنَّۃِ ۫ وَعَصٰۤی اٰدَمُ رَبَّہٗ فَغَوٰی ۪ۖ","20:131":"وَلَا تَمُدَّنَّ عَیۡنَیۡکَ اِلٰی مَا مَتَّعۡنَا بِہٖۤ اَزۡوَاجًا مِّنۡہُمۡ زَہۡرَۃَ الۡحَیٰوۃِ الدُّنۡیَا ۬ۙ لِنَفۡتِنَہُمۡ فِیۡہِ ؕ وَرِزۡقُ رَبِّکَ خَیۡرٌ وَّاَبۡقٰی ","21:34":"وَمَا جَعَلۡنَا لِبَشَرٍ مِّنۡ قَبۡلِکَ الۡخُلۡدَ ؕ اَفَا۠ئِنۡ مِّتَّ فَہُمُ الۡخٰلِدُوۡنَ ","21:35":"کُلُّ نَفۡسٍ ذَآئِقَۃُ الۡمَوۡتِ ؕ وَنَبۡلُوۡکُمۡ بِالشَّرِّ وَالۡخَیۡرِ فِتۡنَۃً ؕ وَاِلَیۡنَا تُرۡجَعُوۡنَ ","21:39":"لَوۡ یَعۡلَمُ الَّذِیۡنَ کَفَرُوۡا حِیۡنَ لَا یَکُفُّوۡنَ عَنۡ وُّجُوۡہِہِمُ النَّارَ وَلَا عَنۡ ظُہُوۡرِہِمۡ وَلَا ہُمۡ یُنۡصَرُوۡنَ ","21:61":"قَالُوۡا فَاۡتُوۡا بِہٖ عَلٰۤی اَعۡیُنِ النَّاسِ لَعَلَّہُمۡ یَشۡہَدُوۡنَ ","21:74":"وَلُوۡطًا اٰتَیۡنٰہُ حُکۡمًا وَّعِلۡمًا وَّنَجَّیۡنٰہُ مِنَ الۡقَرۡیَۃِ الَّتِیۡ کَانَتۡ تَّعۡمَلُ الۡخَبٰٓئِثَ ؕ اِنَّہُمۡ کَانُوۡا قَوۡمَ سَوۡءٍ فٰسِقِیۡنَ ۙ ","21:81":"وَلِسُلَیۡمٰنَ الرِّیۡحَ عَاصِفَۃً تَجۡرِیۡ بِاَمۡرِہٖۤ اِلَی الۡاَرۡضِ الَّتِیۡ بٰرَکۡنَا فِیۡہَا ؕ وَکُنَّا بِکُلِّ شَیۡءٍ عٰلِمِیۡنَ ","21:82":"وَمِنَ الشَّیٰطِیۡنِ مَنۡ یَّغُوۡصُوۡنَ لَہٗ وَیَعۡمَلُوۡنَ عَمَلًا دُوۡنَ ذٰلِکَ ۚ وَکُنَّا لَہُمۡ حٰفِظِیۡنَ ۙ ","21:91":"وَالَّتِیۡۤ اَحۡصَنَتۡ فَرۡجَہَا فَنَفَخۡنَا فِیۡہَا مِنۡ رُّوۡحِنَا وَجَعَلۡنٰہَا وَابۡنَہَاۤ اٰیَۃً لِّلۡعٰلَمِیۡنَ ","21:98":"اِنَّکُمۡ وَمَا تَعۡبُدُوۡنَ مِنۡ دُوۡنِ اللّٰہِ حَصَبُ جَہَنَّمَ ؕ اَنۡتُمۡ لَہَا وٰرِدُوۡنَ ","22:3":"وَمِنَ النَّاسِ مَنۡ یُّجَادِلُ فِی اللّٰہِ بِغَیۡرِ عِلۡمٍ وَّیَتَّبِعُ کُلَّ شَیۡطٰنٍ مَّرِیۡدٍ ۙ ","22:4":"کُتِبَ عَلَیۡہِ اَنَّہٗ مَنۡ تَوَلَّاہُ فَاَنَّہٗ یُضِلُّہٗ وَیَہۡدِیۡہِ اِلٰی عَذَابِ السَّعِیۡرِ ","22:9":"ثَانِیَ عِطۡفِہٖ لِیُضِلَّ عَنۡ سَبِیۡلِ اللّٰہِ ؕ لَہٗ فِی الدُّنۡیَا خِزۡیٌ وَّنُذِیۡقُہٗ یَوۡمَ الۡقِیٰمَۃِ عَذَابَ الۡحَرِیۡقِ ","22:19":"ہٰذٰنِ خَصۡمٰنِ اخۡتَصَمُوۡا فِیۡ رَبِّہِمۡ ۫ فَالَّذِیۡنَ کَفَرُوۡا قُطِّعَتۡ لَہُمۡ ثِیَابٌ مِّنۡ نَّارٍ ؕ یُصَبُّ مِنۡ فَوۡقِ رُءُوۡسِہِمُ الۡحَمِیۡمُ ۚ ","22:21":"وَلَہُمۡ مَّقَامِعُ مِنۡ حَدِیۡدٍ ","22:22":"کُلَّمَاۤ اَرَادُوۡۤا اَنۡ یَّخۡرُجُوۡا مِنۡہَا مِنۡ غَمٍّ اُعِیۡدُوۡا فِیۡہَا ٭ وَذُوۡقُوۡا عَذَابَ الۡحَرِیۡقِ ٪ ","22:52":"وَمَاۤ اَرۡسَلۡنَا مِنۡ قَبۡلِکَ مِنۡ رَّسُوۡلٍ وَّلَا نَبِیٍّ اِلَّاۤ اِذَا تَمَنّٰۤی اَلۡقَی الشَّیۡطٰنُ فِیۡۤ اُمۡنِیَّتِہٖ ۚ فَیَنۡسَخُ اللّٰہُ مَا یُلۡقِی الشَّیۡطٰنُ ثُمَّ یُحۡکِمُ اللّٰہُ اٰیٰتِہٖ ؕ وَاللّٰہُ عَلِیۡمٌ حَکِیۡمٌ ۙ","22:53":"لِّیَجۡعَلَ مَا یُلۡقِی الشَّیۡطٰنُ فِتۡنَۃً لِّلَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ وَّالۡقَاسِیَۃِ قُلُوۡبُہُمۡ ؕ وَاِنَّ الظّٰلِمِیۡنَ لَفِیۡ شِقَاقٍۭ بَعِیۡدٍ ۙ ","23:14":"ثُمَّ خَلَقۡنَا النُّطۡفَۃَ عَلَقَۃً فَخَلَقۡنَا الۡعَلَقَۃَ مُضۡغَۃً فَخَلَقۡنَا الۡمُضۡغَۃَ عِظٰمًا فَکَسَوۡنَا الۡعِظٰمَ لَحۡمًا ٭ ثُمَّ اَنۡشَاۡنٰہُ خَلۡقًا اٰخَرَ ؕ فَتَبٰرَکَ اللّٰہُ اَحۡسَنُ الۡخٰلِقِیۡنَ ؕ ","23:15":"ثُمَّ اِنَّکُمۡ بَعۡدَ ذٰلِکَ لَمَیِّتُوۡنَ ؕ ","23:16":"ثُمَّ اِنَّکُمۡ یَوۡمَ الۡقِیٰمَۃِ تُبۡعَثُوۡنَ ","23:25":"اِنۡ ہُوَ اِلَّا رَجُلٌۢ بِہٖ جِنَّۃٌ فَتَرَبَّصُوۡا بِہٖ حَتّٰی حِیۡنٍ ","23:35":"اَیَعِدُکُمۡ اَنَّکُمۡ اِذَا مِتُّمۡ وَکُنۡتُمۡ تُرَابًا وَّعِظَامًا اَنَّکُمۡ مُّخۡرَجُوۡنَ ۪ۙ ","23:97":"وَقُلۡ رَّبِّ اَعُوۡذُ بِکَ مِنۡ ہَمَزٰتِ الشَّیٰطِیۡنِ ۙ ","23:98":"وَاَعُوۡذُ بِکَ رَبِّ اَنۡ یَّحۡضُرُوۡنِ ","23:99":"حَتّٰۤی اِذَا جَآءَ اَحَدَہُمُ الۡمَوۡتُ قَالَ رَبِّ ارۡجِعُوۡنِ ۙ ","23:100":"لَعَلِّیۡۤ اَعۡمَلُ صَالِحًا فِیۡمَا تَرَکۡتُ کَلَّا ؕ اِنَّہَا کَلِمَۃٌ ہُوَ قَآئِلُہَا ؕ وَمِنۡ وَّرَآئِہِمۡ بَرۡزَخٌ اِلٰی یَوۡمِ یُبۡعَثُوۡنَ ","23:104":"تَلۡفَحُ وُجُوۡہَہُمُ النَّارُ وَہُمۡ فِیۡہَا کٰلِحُوۡنَ ","23:106":"قَالُوۡا رَبَّنَا غَلَبَتۡ عَلَیۡنَا شِقۡوَتُنَا وَکُنَّا قَوۡمًا ضَآلِّیۡنَ ","23:107":"رَبَّنَاۤ اَخۡرِجۡنَا مِنۡہَا فَاِنۡ عُدۡنَا فَاِنَّا ظٰلِمُوۡنَ ","23:115":"اَفَحَسِبۡتُمۡ اَنَّمَا خَلَقۡنٰکُمۡ عَبَثًا وَّاَنَّکُمۡ اِلَیۡنَا لَا تُرۡجَعُوۡنَ ","23:117":"وَمَنۡ یَّدۡعُ مَعَ اللّٰہِ اِلٰـہًا اٰخَرَ ۙ لَا بُرۡہَانَ لَہٗ بِہٖ ۙ فَاِنَّمَا حِسَابُہٗ عِنۡدَ رَبِّہٖ ؕ اِنَّہٗ لَا یُفۡلِحُ الۡکٰفِرُوۡنَ ","23:118":"وَقُلۡ رَّبِّ اغۡفِرۡ وَارۡحَمۡ وَاَنۡتَ خَیۡرُ الرّٰحِمِیۡنَ ٪ ","24:2":"اَلزَّانِیَۃُ وَالزَّانِیۡ فَاجۡلِدُوۡا کُلَّ وَاحِدٍ مِّنۡہُمَا مِائَۃَ جَلۡدَۃٍ ۪ وَّلَا تَاۡخُذۡکُمۡ بِہِمَا رَاۡفَۃٌ فِیۡ دِیۡنِ اللّٰہِ اِنۡ کُنۡتُمۡ تُؤۡمِنُوۡنَ بِاللّٰہِ وَالۡیَوۡمِ الۡاٰخِرِ ۚ وَلۡیَشۡہَدۡ عَذَابَہُمَا طَآئِفَۃٌ مِّنَ الۡمُؤۡمِنِیۡنَ ","24:3":"اَلزَّانِیۡ لَا یَنۡکِحُ اِلَّا زَانِیَۃً اَوۡ مُشۡرِکَۃً ۫ وَّالزَّانِیَۃُ لَا یَنۡکِحُہَاۤ اِلَّا زَانٍ اَوۡ مُشۡرِکٌ ۚ وَحُرِّمَ ذٰلِکَ عَلَی الۡمُؤۡمِنِیۡنَ ","24:19":"اِنَّ الَّذِیۡنَ یُحِبُّوۡنَ اَنۡ تَشِیۡعَ الۡفَاحِشَۃُ فِی الَّذِیۡنَ اٰمَنُوۡا لَہُمۡ عَذَابٌ اَلِیۡمٌ ۙ فِی الدُّنۡیَا وَالۡاٰخِرَۃِ ؕ وَاللّٰہُ یَعۡلَمُ وَاَنۡتُمۡ لَا تَعۡلَمُوۡنَ ","24:21":"یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَتَّبِعُوۡا خُطُوٰتِ الشَّیۡطٰنِ ؕ وَمَنۡ یَّتَّبِعۡ خُطُوٰتِ الشَّیۡطٰنِ فَاِنَّہٗ یَاۡمُرُ بِالۡفَحۡشَآءِ وَالۡمُنۡکَرِ ؕ وَلَوۡلَا فَضۡلُ اللّٰہِ عَلَیۡکُمۡ وَرَحۡمَتُہٗ مَا زَکٰی مِنۡکُمۡ مِّنۡ اَحَدٍ اَبَدًا ۙ وَّلٰکِنَّ اللّٰہَ یُزَکِّیۡ مَنۡ یَّشَآءُ ؕ وَاللّٰہُ سَمِیۡعٌ عَلِیۡمٌ ","24:26":"اَلۡخَبِیۡثٰتُ لِلۡخَبِیۡثِیۡنَ وَالۡخَبِیۡثُوۡنَ لِلۡخَبِیۡثٰتِ ۚ وَالطَّیِّبٰتُ لِلطَّیِّبِیۡنَ وَالطَّیِّبُوۡنَ لِلطَّیِّبٰتِ ۚ اُولٰٓئِکَ مُبَرَّءُوۡنَ مِمَّا یَقُوۡلُوۡنَ ؕ لَہُمۡ مَّغۡفِرَۃٌ وَّرِزۡقٌ کَرِیۡمٌ ٪ ","24:28":"فَاِنۡ لَّمۡ تَجِدُوۡا فِیۡہَاۤ اَحَدًا فَلَا تَدۡخُلُوۡہَا حَتّٰی یُؤۡذَنَ لَکُمۡ ۚ وَاِنۡ قِیۡلَ لَکُمُ ارۡجِعُوۡا فَارۡجِعُوۡا ہُوَ اَزۡکٰی لَکُمۡ ؕ وَاللّٰہُ بِمَا تَعۡمَلُوۡنَ عَلِیۡمٌ ","24:30":"قُلۡ لِّلۡمُؤۡمِنِیۡنَ یَغُضُّوۡا مِنۡ اَبۡصَارِہِمۡ وَیَحۡفَظُوۡا فُرُوۡجَہُمۡ ؕ ذٰلِکَ اَزۡکٰی لَہُمۡ ؕ اِنَّ اللّٰہَ خَبِیۡرٌۢ بِمَا یَصۡنَعُوۡنَ ","24:31":"وَقُلۡ لِّلۡمُؤۡمِنٰتِ یَغۡضُضۡنَ مِنۡ اَبۡصَارِہِنَّ وَیَحۡفَظۡنَ فُرُوۡجَہُنَّ وَلَا یُبۡدِیۡنَ زِیۡنَتَہُنَّ اِلَّا مَا ظَہَرَ مِنۡہَا وَلۡیَضۡرِبۡنَ بِخُمُرِہِنَّ عَلٰی جُیُوۡبِہِنَّ ۪ وَلَا یُبۡدِیۡنَ زِیۡنَتَہُنَّ اِلَّا لِبُعُوۡلَتِہِنَّ اَوۡ اٰبَآئِہِنَّ اَوۡ اٰبَآءِ بُعُوۡلَتِہِنَّ اَوۡ اَبۡنَآئِہِنَّ اَوۡ اَبۡنَآءِ بُعُوۡلَتِہِنَّ اَوۡ اِخۡوَانِہِنَّ اَوۡ بَنِیۡۤ اِخۡوَانِہِنَّ اَوۡ بَنِیۡۤ اَخَوٰتِہِنَّ اَوۡ نِسَآئِہِنَّ اَوۡ مَا مَلَکَتۡ اَیۡمَانُہُنَّ اَوِ التّٰبِعِیۡنَ غَیۡرِ اُولِی الۡاِرۡبَۃِ مِنَ الرِّجَالِ اَوِ الطِّفۡلِ الَّذِیۡنَ لَمۡ یَظۡہَرُوۡا عَلٰی عَوۡرٰتِ النِّسَآءِ ۪ وَلَا یَضۡرِبۡنَ بِاَرۡجُلِہِنَّ لِیُعۡلَمَ مَا یُخۡفِیۡنَ مِنۡ زِیۡنَتِہِنَّ ؕ وَتُوۡبُوۡۤا اِلَی اللّٰہِ جَمِیۡعًا اَیُّہَ الۡمُؤۡمِنُوۡنَ لَعَلَّکُمۡ تُفۡلِحُوۡنَ ","24:33":"وَلۡیَسۡتَعۡفِفِ الَّذِیۡنَ لَا یَجِدُوۡنَ نِکَاحًا حَتّٰی یُغۡنِیَہُمُ اللّٰہُ مِنۡ فَضۡلِہٖ ؕ وَالَّذِیۡنَ یَبۡتَغُوۡنَ الۡکِتٰبَ مِمَّا مَلَکَتۡ اَیۡمَانُکُمۡ فَکَاتِبُوۡہُمۡ اِنۡ عَلِمۡتُمۡ فِیۡہِمۡ خَیۡرًا ٭ۖ وَّاٰتُوۡہُمۡ مِّنۡ مَّالِ اللّٰہِ الَّذِیۡۤ اٰتٰىکُمۡ ؕ وَلَا تُکۡرِہُوۡا فَتَیٰتِکُمۡ عَلَی الۡبِغَآءِ اِنۡ اَرَدۡنَ تَحَصُّنًا لِّتَبۡتَغُوۡا عَرَضَ الۡحَیٰوۃِ الدُّنۡیَا ؕ وَمَنۡ یُّکۡرِہۡہُّنَّ فَاِنَّ اللّٰہَ مِنۡۢ بَعۡدِ اِکۡرَاہِہِنَّ غَفُوۡرٌ رَّحِیۡمٌ ","24:35":"اَللّٰہُ نُوۡرُ السَّمٰوٰتِ وَالۡاَرۡضِ ؕ مَثَلُ نُوۡرِہٖ کَمِشۡکٰوۃٍ فِیۡہَا مِصۡبَاحٌ ؕ اَلۡمِصۡبَاحُ فِیۡ زُجَاجَۃٍ ؕ اَلزُّجَاجَۃُ کَاَنَّہَا کَوۡکَبٌ دُرِّیٌّ یُّوۡقَدُ مِنۡ شَجَرَۃٍ مُّبٰرَکَۃٍ زَیۡتُوۡنَۃٍ لَّا شَرۡقِیَّۃٍ وَّلَا غَرۡبِیَّۃٍ ۙ یَّکَادُ زَیۡتُہَا یُضِیۡٓءُ وَلَوۡ لَمۡ تَمۡسَسۡہُ نَارٌ ؕ نُوۡرٌ عَلٰی نُوۡرٍ ؕ یَہۡدِی اللّٰہُ لِنُوۡرِہٖ مَنۡ یَّشَآءُ ؕ وَیَضۡرِبُ اللّٰہُ الۡاَمۡثَالَ لِلنَّاسِ ؕ وَاللّٰہُ بِکُلِّ شَیۡءٍ عَلِیۡمٌ ۙ ","24:53":"وَاَقۡسَمُوۡا بِاللّٰہِ جَہۡدَ اَیۡمَانِہِمۡ لَئِنۡ اَمَرۡتَہُمۡ لَیَخۡرُجُنَّ ؕ قُلۡ لَّا تُقۡسِمُوۡا ۚ طَاعَۃٌ مَّعۡرُوۡفَۃٌ ؕ اِنَّ اللّٰہَ خَبِیۡرٌۢ بِمَا تَعۡمَلُوۡنَ ","25:27":"وَیَوۡمَ یَعَضُّ الظَّالِمُ عَلٰی یَدَیۡہِ یَقُوۡلُ یٰلَیۡتَنِی اتَّخَذۡتُ مَعَ الرَّسُوۡلِ سَبِیۡلًا ","25:28":"یٰوَیۡلَتٰی لَیۡتَنِیۡ لَمۡ اَتَّخِذۡ فُلَانًا خَلِیۡلًا ","25:29":"لَقَدۡ اَضَلَّنِیۡ عَنِ الذِّکۡرِ بَعۡدَ اِذۡ جَآءَنِیۡ ؕ وَکَانَ الشَّیۡطٰنُ لِلۡاِنۡسَانِ خَذُوۡلًا ","25:53":"وَہُوَ الَّذِیۡ مَرَجَ الۡبَحۡرَیۡنِ ہٰذَا عَذۡبٌ فُرَاتٌ وَّہٰذَا مِلۡحٌ اُجَاجٌ ۚ وَجَعَلَ بَیۡنَہُمَا بَرۡزَخًا وَّحِجۡرًا مَّحۡجُوۡرًا ","25:68":"وَالَّذِیۡنَ لَا یَدۡعُوۡنَ مَعَ اللّٰہِ اِلٰـہًا اٰخَرَ وَلَا یَقۡتُلُوۡنَ النَّفۡسَ الَّتِیۡ حَرَّمَ اللّٰہُ اِلَّا بِالۡحَقِّ وَلَا یَزۡنُوۡنَ ۚ وَمَنۡ یَّفۡعَلۡ ذٰلِکَ یَلۡقَ اَثَامًا ۙ ","26:12":"قَالَ رَبِّ اِنِّیۡۤ اَخَافُ اَنۡ یُّکَذِّبُوۡنِ ؕ ","26:13":"وَیَضِیۡقُ صَدۡرِیۡ وَلَا یَنۡطَلِقُ لِسَانِیۡ فَاَرۡسِلۡ اِلٰی ہٰرُوۡنَ ","26:14":"وَلَہُمۡ عَلَیَّ ذَنۡۢبٌ فَاَخَافُ اَنۡ یَّقۡتُلُوۡنِ ۚ","26:80":"وَاِذَا مَرِضۡتُ فَہُوَ یَشۡفِیۡنِ ۪ۙ ","26:166":"وَتَذَرُوۡنَ مَا خَلَقَ لَکُمۡ رَبُّکُمۡ مِّنۡ اَزۡوَاجِکُمۡ ؕ بَلۡ اَنۡتُمۡ قَوۡمٌ عٰدُوۡنَ ","26:167":"قَالُوۡا لَئِنۡ لَّمۡ تَنۡتَہِ یٰلُوۡطُ لَتَکُوۡنَنَّ مِنَ الۡمُخۡرَجِیۡنَ ","26:206":"ثُمَّ جَآءَہُمۡ مَّا کَانُوۡا یُوۡعَدُوۡنَ ۙ ","26:207":"مَاۤ اَغۡنٰی عَنۡہُمۡ مَّا کَانُوۡا یُمَتَّعُوۡنَ ؕ ","26:213":"فَلَا تَدۡعُ مَعَ اللّٰہِ اِلٰـہًا اٰخَرَ فَتَکُوۡنَ مِنَ الۡمُعَذَّبِیۡنَ ۚ ","26:221":"ہَلۡ اُنَبِّئُکُمۡ عَلٰی مَنۡ تَنَزَّلُ الشَّیٰطِیۡنُ ؕ ","26:222":"تَنَزَّلُ عَلٰی کُلِّ اَفَّاکٍ اَثِیۡمٍ ۙ ","27:7":"اِذۡ قَالَ مُوۡسٰی لِاَہۡلِہٖۤ اِنِّیۡۤ اٰنَسۡتُ نَارًا ؕ سَاٰتِیۡکُمۡ مِّنۡہَا بِخَبَرٍ اَوۡ اٰتِیۡکُمۡ بِشِہَابٍ قَبَسٍ لَّعَلَّکُمۡ تَصۡطَلُوۡنَ ","27:15":"وَلَقَدۡ اٰتَیۡنَا دَاوٗدَ وَسُلَیۡمٰنَ عِلۡمًا ۚ وَقَالَا الۡحَمۡدُ لِلّٰہِ الَّذِیۡ فَضَّلَنَا عَلٰی کَثِیۡرٍ مِّنۡ عِبَادِہِ الۡمُؤۡمِنِیۡنَ ","27:16":"وَوَرِثَ سُلَیۡمٰنُ دَاوٗدَ وَقَالَ یٰۤاَیُّہَا النَّاسُ عُلِّمۡنَا مَنۡطِقَ الطَّیۡرِ وَاُوۡتِیۡنَا مِنۡ کُلِّ شَیۡءٍ ؕ اِنَّ ہٰذَا لَہُوَ الۡفَضۡلُ الۡمُبِیۡنُ ","27:17":"وَحُشِرَ لِسُلَیۡمٰنَ جُنُوۡدُہٗ مِنَ الۡجِنِّ وَالۡاِنۡسِ وَالطَّیۡرِ فَہُمۡ یُوۡزَعُوۡنَ ","27:37":"اِرۡجِعۡ اِلَیۡہِمۡ فَلَنَاۡتِیَنَّہُمۡ بِجُنُوۡدٍ لَّا قِبَلَ لَہُمۡ بِہَا وَلَنُخۡرِجَنَّہُمۡ مِّنۡہَاۤ اَذِلَّۃً وَّہُمۡ صٰغِرُوۡنَ ","27:38":"قَالَ یٰۤاَیُّہَا الۡمَلَؤُا اَیُّکُمۡ یَاۡتِیۡنِیۡ بِعَرۡشِہَا قَبۡلَ اَنۡ یَّاۡتُوۡنِیۡ مُسۡلِمِیۡنَ ","27:39":"قَالَ عِفۡرِیۡتٌ مِّنَ الۡجِنِّ اَنَا اٰتِیۡکَ بِہٖ قَبۡلَ اَنۡ تَقُوۡمَ مِنۡ مَّقَامِکَ ۚ وَاِنِّیۡ عَلَیۡہِ لَقَوِیٌّ اَمِیۡنٌ ","27:48":"وَکَانَ فِی الۡمَدِیۡنَۃِ تِسۡعَۃُ رَہۡطٍ یُّفۡسِدُوۡنَ فِی الۡاَرۡضِ وَلَا یُصۡلِحُوۡنَ ","27:54":"وَلُوۡطًا اِذۡ قَالَ لِقَوۡمِہٖۤ اَتَاۡتُوۡنَ الۡفَاحِشَۃَ وَاَنۡتُمۡ تُبۡصِرُوۡنَ ","27:67":"وَقَالَ الَّذِیۡنَ کَفَرُوۡۤا ءَاِذَا کُنَّا تُرٰبًا وَّاٰبَآؤُنَاۤ اَئِنَّا لَمُخۡرَجُوۡنَ ","27:90":"وَمَنۡ جَآءَ بِالسَّیِّئَۃِ فَکُبَّتۡ وُجُوۡہُہُمۡ فِی النَّارِ ؕ ہَلۡ تُجۡزَوۡنَ اِلَّا مَا کُنۡتُمۡ تَعۡمَلُوۡنَ ","28:15":"وَدَخَلَ الۡمَدِیۡنَۃَ عَلٰی حِیۡنِ غَفۡلَۃٍ مِّنۡ اَہۡلِہَا فَوَجَدَ فِیۡہَا رَجُلَیۡنِ یَقۡتَتِلٰنِ ٭۫ ہٰذَا مِنۡ شِیۡعَتِہٖ وَہٰذَا مِنۡ عَدُوِّہٖ ۚ فَاسۡتَغَاثَہُ الَّذِیۡ مِنۡ شِیۡعَتِہٖ عَلَی الَّذِیۡ مِنۡ عَدُوِّہٖ ۙ فَوَکَزَہٗ مُوۡسٰی فَقَضٰی عَلَیۡہِ ٭۫ قَالَ ہٰذَا مِنۡ عَمَلِ الشَّیۡطٰنِ ؕ اِنَّہٗ عَدُوٌّ مُّضِلٌّ مُّبِیۡنٌ ","28:19":"فَلَمَّاۤ اَنۡ اَرَادَ اَنۡ یَّبۡطِشَ بِالَّذِیۡ ہُوَ عَدُوٌّ لَّہُمَا ۙ قَالَ یٰمُوۡسٰۤی اَتُرِیۡدُ اَنۡ تَقۡتُلَنِیۡ کَمَا قَتَلۡتَ نَفۡسًۢا بِالۡاَمۡسِ ٭ۖ اِنۡ تُرِیۡدُ اِلَّاۤ اَنۡ تَکُوۡنَ جَبَّارًا فِی الۡاَرۡضِ وَمَا تُرِیۡدُ اَنۡ تَکُوۡنَ مِنَ الۡمُصۡلِحِیۡنَ ","28:20":"وَجَآءَ رَجُلٌ مِّنۡ اَقۡصَا الۡمَدِیۡنَۃِ یَسۡعٰی ۫ قَالَ یٰمُوۡسٰۤی اِنَّ الۡمَلَاَ یَاۡتَمِرُوۡنَ بِکَ لِیَقۡتُلُوۡکَ فَاخۡرُجۡ اِنِّیۡ لَکَ مِنَ النّٰصِحِیۡنَ ","28:21":"فَخَرَجَ مِنۡہَا خَآئِفًا یَّتَرَقَّبُ ۫ قَالَ رَبِّ نَجِّنِیۡ مِنَ الۡقَوۡمِ الظّٰلِمِیۡنَ ٪ ","28:31":"وَاَنۡ اَلۡقِ عَصَاکَ ؕ فَلَمَّا رَاٰہَا تَہۡتَزُّ کَاَنَّہَا جَآنٌّ وَّلّٰی مُدۡبِرًا وَّلَمۡ یُعَقِّبۡ ؕ یٰمُوۡسٰۤی اَقۡبِلۡ وَلَا تَخَفۡ ۟ اِنَّکَ مِنَ الۡاٰمِنِیۡنَ ","28:33":"قَالَ رَبِّ اِنِّیۡ قَتَلۡتُ مِنۡہُمۡ نَفۡسًا فَاَخَافُ اَنۡ یَّقۡتُلُوۡنِ ","29:24":"فَمَا کَانَ جَوَابَ قَوۡمِہٖۤ اِلَّاۤ اَنۡ قَالُوا اقۡتُلُوۡہُ اَوۡ حَرِّقُوۡہُ فَاَنۡجٰىہُ اللّٰہُ مِنَ النَّارِ ؕ اِنَّ فِیۡ ذٰلِکَ لَاٰیٰتٍ لِّقَوۡمٍ یُّؤۡمِنُوۡنَ ","29:28":"وَلُوۡطًا اِذۡ قَالَ لِقَوۡمِہٖۤ اِنَّکُمۡ لَتَاۡتُوۡنَ الۡفَاحِشَۃَ ۫ مَا سَبَقَکُمۡ بِہَا مِنۡ اَحَدٍ مِّنَ الۡعٰلَمِیۡنَ ","29:38":"وَعَادًا وَّثَمُوۡدَا۠ وَقَدۡ تَّبَیَّنَ لَکُمۡ مِّنۡ مَّسٰکِنِہِمۡ ۟ وَزَیَّنَ لَہُمُ الشَّیۡطٰنُ اَعۡمَالَہُمۡ فَصَدَّہُمۡ عَنِ السَّبِیۡلِ وَکَانُوۡا مُسۡتَبۡصِرِیۡنَ ۙ ","29:45":"اُتۡلُ مَاۤ اُوۡحِیَ اِلَیۡکَ مِنَ الۡکِتٰبِ وَاَقِمِ الصَّلٰوۃَ ؕ اِنَّ الصَّلٰوۃَ تَنۡہٰی عَنِ الۡفَحۡشَآءِ وَالۡمُنۡکَرِ ؕ وَلَذِکۡرُ اللّٰہِ اَکۡبَرُ ؕ وَاللّٰہُ یَعۡلَمُ مَا تَصۡنَعُوۡنَ ","29:57":"کُلُّ نَفۡسٍ ذَآئِقَۃُ الۡمَوۡتِ ۟ ثُمَّ اِلَیۡنَا تُرۡجَعُوۡنَ ","30:19":"یُخۡرِجُ الۡحَیَّ مِنَ الۡمَیِّتِ وَیُخۡرِجُ الۡمَیِّتَ مِنَ الۡحَیِّ وَیُحۡیِ الۡاَرۡضَ بَعۡدَ مَوۡتِہَا ؕ وَکَذٰلِکَ تُخۡرَجُوۡنَ ٪ ","30:25":"وَمِنۡ اٰیٰتِہٖۤ اَنۡ تَقُوۡمَ السَّمَآءُ وَالۡاَرۡضُ بِاَمۡرِہٖ ؕ ثُمَّ اِذَا دَعَاکُمۡ دَعۡوَۃً ٭ۖ مِّنَ الۡاَرۡضِ ٭ۖ اِذَاۤ اَنۡتُمۡ تَخۡرُجُوۡنَ ","31:21":"وَاِذَا قِیۡلَ لَہُمُ اتَّبِعُوۡا مَاۤ اَنۡزَلَ اللّٰہُ قَالُوۡا بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَیۡہِ اٰبَآءَنَا ؕ اَوَلَوۡ کَانَ الشَّیۡطٰنُ یَدۡعُوۡہُمۡ اِلٰی عَذَابِ السَّعِیۡرِ ","31:24":"نُمَتِّعُہُمۡ قَلِیۡلًا ثُمَّ نَضۡطَرُّہُمۡ اِلٰی عَذَابٍ غَلِیۡظٍ ","31:34":"اِنَّ اللّٰہَ عِنۡدَہٗ عِلۡمُ السَّاعَۃِ ۚ وَیُنَزِّلُ الۡغَیۡثَ ۚ وَیَعۡلَمُ مَا فِی الۡاَرۡحَامِ ؕ وَمَا تَدۡرِیۡ نَفۡسٌ مَّاذَا تَکۡسِبُ غَدًا ؕ وَمَا تَدۡرِیۡ نَفۡسٌۢ بِاَیِّ اَرۡضٍ تَمُوۡتُ ؕ اِنَّ اللّٰہَ عَلِیۡمٌ خَبِیۡرٌ ٪ ","32:11":"قُلۡ یَتَوَفّٰىکُمۡ مَّلَکُ الۡمَوۡتِ الَّذِیۡ وُکِّلَ بِکُمۡ ثُمَّ اِلٰی رَبِّکُمۡ تُرۡجَعُوۡنَ ٪ ","32:13":"وَلَوۡ شِئۡنَا لَاٰتَیۡنَا کُلَّ نَفۡسٍ ہُدٰىہَا وَلٰکِنۡ حَقَّ الۡقَوۡلُ مِنِّیۡ لَاَمۡلَـَٔنَّ جَہَنَّمَ مِنَ الۡجِنَّۃِ وَالنَّاسِ اَجۡمَعِیۡنَ ","32:20":"وَاَمَّا الَّذِیۡنَ فَسَقُوۡا فَمَاۡوٰىہُمُ النَّارُ ؕ کُلَّمَاۤ اَرَادُوۡۤا اَنۡ یَّخۡرُجُوۡا مِنۡہَاۤ اُعِیۡدُوۡا فِیۡہَا وَقِیۡلَ لَہُمۡ ذُوۡقُوۡا عَذَابَ النَّارِ الَّذِیۡ کُنۡتُمۡ بِہٖ تُکَذِّبُوۡنَ ","33:11":"ہُنَالِکَ ابۡتُلِیَ الۡمُؤۡمِنُوۡنَ وَزُلۡزِلُوۡا زِلۡزَالًا شَدِیۡدًا ","33:12":"وَاِذۡ یَقُوۡلُ الۡمُنٰفِقُوۡنَ وَالَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ مَّا وَعَدَنَا اللّٰہُ وَرَسُوۡلُہٗۤ اِلَّا غُرُوۡرًا ","33:25":"وَرَدَّ اللّٰہُ الَّذِیۡنَ کَفَرُوۡا بِغَیۡظِہِمۡ لَمۡ یَنَالُوۡا خَیۡرًا ؕ وَکَفَی اللّٰہُ الۡمُؤۡمِنِیۡنَ الۡقِتَالَ ؕ وَکَانَ اللّٰہُ قَوِیًّا عَزِیۡزًا ۚ ","33:26":"وَاَنۡزَلَ الَّذِیۡنَ ظَاہَرُوۡہُمۡ مِّنۡ اَہۡلِ الۡکِتٰبِ مِنۡ صَیَاصِیۡہِمۡ وَقَذَفَ فِیۡ قُلُوۡبِہِمُ الرُّعۡبَ فَرِیۡقًا تَقۡتُلُوۡنَ وَتَاۡسِرُوۡنَ فَرِیۡقًا ۚ","33:27":"وَاَوۡرَثَکُمۡ اَرۡضَہُمۡ وَدِیَارَہُمۡ وَاَمۡوَالَہُمۡ وَاَرۡضًا لَّمۡ تَطَـُٔوۡہَا ؕ وَکَانَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرًا ٪ ","33:30":"یٰنِسَآءَ النَّبِیِّ مَنۡ یَّاۡتِ مِنۡکُنَّ بِفَاحِشَۃٍ مُّبَیِّنَۃٍ یُّضٰعَفۡ لَہَا الۡعَذَابُ ضِعۡفَیۡنِ ؕ وَکَانَ ذٰلِکَ عَلَی اللّٰہِ یَسِیۡرًا ","33:35":"اِنَّ الۡمُسۡلِمِیۡنَ وَالۡمُسۡلِمٰتِ وَالۡمُؤۡمِنِیۡنَ وَالۡمُؤۡمِنٰتِ وَالۡقٰنِتِیۡنَ وَالۡقٰنِتٰتِ وَالصّٰدِقِیۡنَ وَالصّٰدِقٰتِ وَالصّٰبِرِیۡنَ وَالصّٰبِرٰتِ وَالۡخٰشِعِیۡنَ وَالۡخٰشِعٰتِ وَالۡمُتَصَدِّقِیۡنَ وَالۡمُتَصَدِّقٰتِ وَالصَّآئِمِیۡنَ وَالصّٰٓئِمٰتِ وَالۡحٰفِظِیۡنَ فُرُوۡجَہُمۡ وَالۡحٰفِظٰتِ وَالذّٰکِرِیۡنَ اللّٰہَ کَثِیۡرًا وَّالذّٰکِرٰتِ ۙ اَعَدَّ اللّٰہُ لَہُمۡ مَّغۡفِرَۃً وَّاَجۡرًا عَظِیۡمًا ","33:52":"لَا یَحِلُّ لَکَ النِّسَآءُ مِنۡۢ بَعۡدُ وَلَاۤ اَنۡ تَبَدَّلَ بِہِنَّ مِنۡ اَزۡوَاجٍ وَّلَوۡ اَعۡجَبَکَ حُسۡنُہُنَّ اِلَّا مَا مَلَکَتۡ یَمِیۡنُکَ ؕ وَکَانَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ رَّقِیۡبًا ٪ ","33:53":"یٰۤاَیُّہَا الَّذِیۡنَ اٰمَنُوۡا لَا تَدۡخُلُوۡا بُیُوۡتَ النَّبِیِّ اِلَّاۤ اَنۡ یُّؤۡذَنَ لَکُمۡ اِلٰی طَعَامٍ غَیۡرَ نٰظِرِیۡنَ اِنٰىہُ ۙ وَلٰکِنۡ اِذَا دُعِیۡتُمۡ فَادۡخُلُوۡا فَاِذَا طَعِمۡتُمۡ فَانۡتَشِرُوۡا وَلَا مُسۡتَاۡنِسِیۡنَ لِحَدِیۡثٍ ؕ اِنَّ ذٰلِکُمۡ کَانَ یُؤۡذِی النَّبِیَّ فَیَسۡتَحۡیٖ مِنۡکُمۡ ۫ وَاللّٰہُ لَا یَسۡتَحۡیٖ مِنَ الۡحَقِّ ؕ وَاِذَا سَاَلۡتُمُوۡہُنَّ مَتَاعًا فَسۡـَٔلُوۡہُنَّ مِنۡ وَّرَآءِ حِجَابٍ ؕ ذٰلِکُمۡ اَطۡہَرُ لِقُلُوۡبِکُمۡ وَقُلُوۡبِہِنَّ ؕ وَمَا کَانَ لَکُمۡ اَنۡ تُؤۡذُوۡا رَسُوۡلَ اللّٰہِ وَلَاۤ اَنۡ تَنۡکِحُوۡۤا اَزۡوَاجَہٗ مِنۡۢ بَعۡدِہٖۤ اَبَدًا ؕ اِنَّ ذٰلِکُمۡ کَانَ عِنۡدَ اللّٰہِ عَظِیۡمًا ","33:59":"یٰۤاَیُّہَا النَّبِیُّ قُلۡ لِّاَزۡوَاجِکَ وَبَنٰتِکَ وَنِسَآءِ الۡمُؤۡمِنِیۡنَ یُدۡنِیۡنَ عَلَیۡہِنَّ مِنۡ جَلَابِیۡبِہِنَّ ؕ ذٰلِکَ اَدۡنٰۤی اَنۡ یُّعۡرَفۡنَ فَلَا یُؤۡذَیۡنَ ؕ وَکَانَ اللّٰہُ غَفُوۡرًا رَّحِیۡمًا ","33:60":"لَئِنۡ لَّمۡ یَنۡتَہِ الۡمُنٰفِقُوۡنَ وَالَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ وَّالۡمُرۡجِفُوۡنَ فِی الۡمَدِیۡنَۃِ لَنُغۡرِیَنَّکَ بِہِمۡ ثُمَّ لَا یُجَاوِرُوۡنَکَ فِیۡہَاۤ اِلَّا قَلِیۡلًا ۖۛۚ ","33:61":"مَّلۡعُوۡنِیۡنَ ۚۛ اَیۡنَمَا ثُقِفُوۡۤا اُخِذُوۡا وَقُتِّلُوۡا تَقۡتِیۡلًا ","33:66":"یَوۡمَ تُقَلَّبُ وُجُوۡہُہُمۡ فِی النَّارِ یَقُوۡلُوۡنَ یٰلَیۡتَنَاۤ اَطَعۡنَا اللّٰہَ وَاَطَعۡنَا الرَّسُوۡلَا ","34:2":"یَعۡلَمُ مَا یَلِجُ فِی الۡاَرۡضِ وَمَا یَخۡرُجُ مِنۡہَا وَمَا یَنۡزِلُ مِنَ السَّمَآءِ وَمَا یَعۡرُجُ فِیۡہَا ؕ وَہُوَ الرَّحِیۡمُ الۡغَفُوۡرُ ","34:12":"وَلِسُلَیۡمٰنَ الرِّیۡحَ غُدُوُّہَا شَہۡرٌ وَّرَوَاحُہَا شَہۡرٌ ۚ وَاَسَلۡنَا لَہٗ عَیۡنَ الۡقِطۡرِ ؕ وَمِنَ الۡجِنِّ مَنۡ یَّعۡمَلُ بَیۡنَ یَدَیۡہِ بِاِذۡنِ رَبِّہٖ ؕ وَمَنۡ یَّزِغۡ مِنۡہُمۡ عَنۡ اَمۡرِنَا نُذِقۡہُ مِنۡ عَذَابِ السَّعِیۡرِ ","34:13":"یَعۡمَلُوۡنَ لَہٗ مَا یَشَآءُ مِنۡ مَّحَارِیۡبَ وَتَمَاثِیۡلَ وَجِفَانٍ کَالۡجَوَابِ وَقُدُوۡرٍ رّٰسِیٰتٍ ؕ اِعۡمَلُوۡۤا اٰلَ دَاوٗدَ شُکۡرًا ؕ وَقَلِیۡلٌ مِّنۡ عِبَادِیَ الشَّکُوۡرُ ","34:14":"فَلَمَّا قَضَیۡنَا عَلَیۡہِ الۡمَوۡتَ مَا دَلَّہُمۡ عَلٰی مَوۡتِہٖۤ اِلَّا دَآبَّۃُ الۡاَرۡضِ تَاۡکُلُ مِنۡسَاَتَہٗ ۚ فَلَمَّا خَرَّ تَبَیَّنَتِ الۡجِنُّ اَنۡ لَّوۡ کَانُوۡا یَعۡلَمُوۡنَ الۡغَیۡبَ مَا لَبِثُوۡا فِی الۡعَذَابِ الۡمُہِیۡنِ ؕ ","34:20":"وَلَقَدۡ صَدَّقَ عَلَیۡہِمۡ اِبۡلِیۡسُ ظَنَّہٗ فَاتَّبَعُوۡہُ اِلَّا فَرِیۡقًا مِّنَ الۡمُؤۡمِنِیۡنَ ","34:21":"وَمَا کَانَ لَہٗ عَلَیۡہِمۡ مِّنۡ سُلۡطٰنٍ اِلَّا لِنَعۡلَمَ مَنۡ یُّؤۡمِنُ بِالۡاٰخِرَۃِ مِمَّنۡ ہُوَ مِنۡہَا فِیۡ شَکٍّ ؕ وَرَبُّکَ عَلٰی کُلِّ شَیۡءٍ حَفِیۡظٌ ٪ ","34:40":"وَیَوۡمَ یَحۡشُرُہُمۡ جَمِیۡعًا ثُمَّ یَقُوۡلُ لِلۡمَلٰٓئِکَۃِ اَہٰۤؤُلَآءِ اِیَّاکُمۡ کَانُوۡا یَعۡبُدُوۡنَ ","34:41":"قَالُوۡا سُبۡحٰنَکَ اَنۡتَ وَلِیُّنَا مِنۡ دُوۡنِہِمۡ ۚ بَلۡ کَانُوۡا یَعۡبُدُوۡنَ الۡجِنَّ ۚ اَکۡثَرُہُمۡ بِہِمۡ مُّؤۡمِنُوۡنَ ","34:42":"فَالۡیَوۡمَ لَا یَمۡلِکُ بَعۡضُکُمۡ لِبَعۡضٍ نَّفۡعًا وَّلَا ضَرًّا ؕ وَنَقُوۡلُ لِلَّذِیۡنَ ظَلَمُوۡا ذُوۡقُوۡا عَذَابَ النَّارِ الَّتِیۡ کُنۡتُمۡ بِہَا تُکَذِّبُوۡنَ ","34:54":"وَحِیۡلَ بَیۡنَہُمۡ وَبَیۡنَ مَا یَشۡتَہُوۡنَ کَمَا فُعِلَ بِاَشۡیَاعِہِمۡ مِّنۡ قَبۡلُ ؕ اِنَّہُمۡ کَانُوۡا فِیۡ شَکٍّ مُّرِیۡبٍ ٪","35:6":"اِنَّ الشَّیۡطٰنَ لَکُمۡ عَدُوٌّ فَاتَّخِذُوۡہُ عَدُوًّا ؕ اِنَّمَا یَدۡعُوۡا حِزۡبَہٗ لِیَکُوۡنُوۡا مِنۡ اَصۡحٰبِ السَّعِیۡرِ ؕ ","35:8":"اَفَمَنۡ زُیِّنَ لَہٗ سُوۡٓءُ عَمَلِہٖ فَرَاٰہُ حَسَنًا ؕ فَاِنَّ اللّٰہَ یُضِلُّ مَنۡ یَّشَآءُ وَیَہۡدِیۡ مَنۡ یَّشَآءُ ۫ۖ فَلَا تَذۡہَبۡ نَفۡسُکَ عَلَیۡہِمۡ حَسَرٰتٍ ؕ اِنَّ اللّٰہَ عَلِیۡمٌۢ بِمَا یَصۡنَعُوۡنَ ","35:36":"وَالَّذِیۡنَ کَفَرُوۡا لَہُمۡ نَارُ جَہَنَّمَ ۚ لَا یُقۡضٰی عَلَیۡہِمۡ فَیَمُوۡتُوۡا وَلَا یُخَفَّفُ عَنۡہُمۡ مِّنۡ عَذَابِہَا ؕ کَذٰلِکَ نَجۡزِیۡ کُلَّ کَفُوۡرٍ ۚ ","35:37":"وَہُمۡ یَصۡطَرِخُوۡنَ فِیۡہَا ۚ رَبَّنَاۤ اَخۡرِجۡنَا نَعۡمَلۡ صَالِحًا غَیۡرَ الَّذِیۡ کُنَّا نَعۡمَلُ ؕ اَوَلَمۡ نُعَمِّرۡکُمۡ مَّا یَتَذَکَّرُ فِیۡہِ مَنۡ تَذَکَّرَ وَجَآءَکُمُ النَّذِیۡرُ ؕ فَذُوۡقُوۡا فَمَا لِلظّٰلِمِیۡنَ مِنۡ نَّصِیۡرٍ ٪ ","36:1":"یٰسٓ ۚ ","36:2":"وَالۡقُرۡاٰنِ الۡحَکِیۡمِ ۙ","36:3":"اِنَّکَ لَمِنَ الۡمُرۡسَلِیۡنَ ۙ ","36:4":"عَلٰی صِرَاطٍ مُّسۡتَقِیۡمٍ ؕ ","36:5":"تَنۡزِیۡلَ الۡعَزِیۡزِ الرَّحِیۡمِ ۙ ","36:6":"لِتُنۡذِرَ قَوۡمًا مَّاۤ اُنۡذِرَ اٰبَآؤُہُمۡ فَہُمۡ غٰفِلُوۡنَ ","36:7":"لَقَدۡ حَقَّ الۡقَوۡلُ عَلٰۤی اَکۡثَرِہِمۡ فَہُمۡ لَا یُؤۡمِنُوۡنَ ","36:8":"اِنَّا جَعَلۡنَا فِیۡۤ اَعۡنَاقِہِمۡ اَغۡلٰلًا فَہِیَ اِلَی الۡاَذۡقَانِ فَہُمۡ مُّقۡمَحُوۡنَ ","36:9":"وَجَعَلۡنَا مِنۡۢ بَیۡنِ اَیۡدِیۡہِمۡ سَدًّا وَّمِنۡ خَلۡفِہِمۡ سَدًّا فَاَغۡشَیۡنٰہُمۡ فَہُمۡ لَا یُبۡصِرُوۡنَ ","36:33":"وَاٰیَۃٌ لَّہُمُ الۡاَرۡضُ الۡمَیۡتَۃُ ۚۖ اَحۡیَیۡنٰہَا وَاَخۡرَجۡنَا مِنۡہَا حَبًّا فَمِنۡہُ یَاۡکُلُوۡنَ ","36:58":"سَلٰمٌ ۟ قَوۡلًا مِّنۡ رَّبٍّ رَّحِیۡمٍ ","36:59":"وَامۡتَازُوا الۡیَوۡمَ اَیُّہَا الۡمُجۡرِمُوۡنَ ","36:60":"اَلَمۡ اَعۡہَدۡ اِلَیۡکُمۡ یٰبَنِیۡۤ اٰدَمَ اَنۡ لَّا تَعۡبُدُوا الشَّیۡطٰنَ ۚ اِنَّہٗ لَکُمۡ عَدُوٌّ مُّبِیۡنٌ ۙ ","36:62":"وَلَقَدۡ اَضَلَّ مِنۡکُمۡ جِبِلًّا کَثِیۡرًا ؕ اَفَلَمۡ تَکُوۡنُوۡا تَعۡقِلُوۡنَ ","36:64":"اِصۡلَوۡہَا الۡیَوۡمَ بِمَا کُنۡتُمۡ تَکۡفُرُوۡنَ ","36:78":"وَضَرَبَ لَنَا مَثَلًا وَّنَسِیَ خَلۡقَہٗ ؕ قَالَ مَنۡ یُّحۡیِ الۡعِظَامَ وَہِیَ رَمِیۡمٌ ","36:79":"قُلۡ یُحۡیِیۡہَا الَّذِیۡۤ اَنۡشَاَہَاۤ اَوَّلَ مَرَّۃٍ ؕ وَہُوَ بِکُلِّ خَلۡقٍ عَلِیۡمُࣘ ۙ ","37:2":"فَالزّٰجِرٰتِ زَجۡرًا ۙ ","37:5":"رَبُّ السَّمٰوٰتِ وَالۡاَرۡضِ وَمَا بَیۡنَہُمَا وَرَبُّ الۡمَشَارِقِ ؕ ","37:6":"اِنَّا زَیَّنَّا السَّمَآءَ الدُّنۡیَا بِزِیۡنَۃِࣙ الۡکَوَاکِبِ ۙ","37:7":"وَحِفۡظًا مِّنۡ کُلِّ شَیۡطٰنٍ مَّارِدٍ ۚ ","37:8":"لَا یَسَّمَّعُوۡنَ اِلَی الۡمَلَاِ الۡاَعۡلٰی وَیُقۡذَفُوۡنَ مِنۡ کُلِّ جَانِبٍ ٭ۖ ","37:9":"دُحُوۡرًا وَّلَہُمۡ عَذَابٌ وَّاصِبٌ ۙ ","37:10":"اِلَّا مَنۡ خَطِفَ الۡخَطۡفَۃَ فَاَتۡبَعَہٗ شِہَابٌ ثَاقِبٌ ","37:51":"قَالَ قَآئِلٌ مِّنۡہُمۡ اِنِّیۡ کَانَ لِیۡ قَرِیۡنٌ ۙ ","37:52":"یَّقُوۡلُ اَئِنَّکَ لَمِنَ الۡمُصَدِّقِیۡنَ ","37:53":"ءَاِذَا مِتۡنَا وَکُنَّا تُرَابًا وَّعِظَامًا ءَاِنَّا لَمَدِیۡنُوۡنَ ","37:62":"اَذٰلِکَ خَیۡرٌ نُّزُلًا اَمۡ شَجَرَۃُ الزَّقُّوۡمِ ","37:66":"فَاِنَّہُمۡ لَاٰکِلُوۡنَ مِنۡہَا فَمَالِـُٔوۡنَ مِنۡہَا الۡبُطُوۡنَ ؕ ","37:67":"ثُمَّ اِنَّ لَہُمۡ عَلَیۡہَا لَشَوۡبًا مِّنۡ حَمِیۡمٍ ۚ ","37:68":"ثُمَّ اِنَّ مَرۡجِعَہُمۡ لَا۠اِلَی الۡجَحِیۡمِ ","37:88":"فَنَظَرَ نَظۡرَۃً فِی النُّجُوۡمِ ۙ ","37:98":"فَاَرَادُوۡا بِہٖ کَیۡدًا فَجَعَلۡنٰہُمُ الۡاَسۡفَلِیۡنَ ","37:158":"وَجَعَلُوۡا بَیۡنَہٗ وَبَیۡنَ الۡجِنَّۃِ نَسَبًا ؕ وَلَقَدۡ عَلِمَتِ الۡجِنَّۃُ اِنَّہُمۡ لَمُحۡضَرُوۡنَ ۙ ","38:28":"اَمۡ نَجۡعَلُ الَّذِیۡنَ اٰمَنُوۡا وَعَمِلُوا الصّٰلِحٰتِ کَالۡمُفۡسِدِیۡنَ فِی الۡاَرۡضِ ۫ اَمۡ نَجۡعَلُ الۡمُتَّقِیۡنَ کَالۡفُجَّارِ ","38:34":"وَلَقَدۡ فَتَنَّا سُلَیۡمٰنَ وَاَلۡقَیۡنَا عَلٰی کُرۡسِیِّہٖ جَسَدًا ثُمَّ اَنَابَ ","38:35":"قَالَ رَبِّ اغۡفِرۡ لِیۡ وَہَبۡ لِیۡ مُلۡکًا لَّا یَنۡۢبَغِیۡ لِاَحَدٍ مِّنۡۢ بَعۡدِیۡ ۚ اِنَّکَ اَنۡتَ الۡوَہَّابُ ","38:36":"فَسَخَّرۡنَا لَہُ الرِّیۡحَ تَجۡرِیۡ بِاَمۡرِہٖ رُخَآءً حَیۡثُ اَصَابَ ۙ","38:37":"وَالشَّیٰطِیۡنَ کُلَّ بَنَّآءٍ وَّغَوَّاصٍ ۙ ","38:39":"ہٰذَا عَطَآؤُنَا فَامۡنُنۡ اَوۡ اَمۡسِکۡ بِغَیۡرِ حِسَابٍ ","38:40":"وَاِنَّ لَہٗ عِنۡدَنَا لَزُلۡفٰی وَحُسۡنَ مَاٰبٍ ٪ ","38:41":"وَاذۡکُرۡ عَبۡدَنَاۤ اَیُّوۡبَ ۘ اِذۡ نَادٰی رَبَّہٗۤ اَنِّیۡ مَسَّنِیَ الشَّیۡطٰنُ بِنُصۡبٍ وَّعَذَابٍ ؕ ","38:42":"اُرۡکُضۡ بِرِجۡلِکَ ۚ ہٰذَا مُغۡتَسَلٌۢ بَارِدٌ وَّشَرَابٌ ","39:8":"وَاِذَا مَسَّ الۡاِنۡسَانَ ضُرٌّ دَعَا رَبَّہٗ مُنِیۡبًا اِلَیۡہِ ثُمَّ اِذَا خَوَّلَہٗ نِعۡمَۃً مِّنۡہُ نَسِیَ مَا کَانَ یَدۡعُوۡۤا اِلَیۡہِ مِنۡ قَبۡلُ وَجَعَلَ لِلّٰہِ اَنۡدَادًا لِّیُضِلَّ عَنۡ سَبِیۡلِہٖ ؕ قُلۡ تَمَتَّعۡ بِکُفۡرِکَ قَلِیۡلًا ٭ۖ اِنَّکَ مِنۡ اَصۡحٰبِ النَّارِ ","39:16":"لَہُمۡ مِّنۡ فَوۡقِہِمۡ ظُلَلٌ مِّنَ النَّارِ وَمِنۡ تَحۡتِہِمۡ ظُلَلٌ ؕ ذٰلِکَ یُخَوِّفُ اللّٰہُ بِہٖ عِبَادَہٗ ؕ یٰعِبَادِ فَاتَّقُوۡنِ ","39:30":"اِنَّکَ مَیِّتٌ وَّاِنَّہُمۡ مَّیِّتُوۡنَ ۫ ","39:31":"ثُمَّ اِنَّکُمۡ یَوۡمَ الۡقِیٰمَۃِ عِنۡدَ رَبِّکُمۡ تَخۡتَصِمُوۡنَ ٪ ","39:49":"فَاِذَا مَسَّ الۡاِنۡسَانَ ضُرٌّ دَعَانَا ۫ ثُمَّ اِذَا خَوَّلۡنٰہُ نِعۡمَۃً مِّنَّا ۙ قَالَ اِنَّمَاۤ اُوۡتِیۡتُہٗ عَلٰی عِلۡمٍ ؕ بَلۡ ہِیَ فِتۡنَۃٌ وَّلٰکِنَّ اَکۡثَرَہُمۡ لَا یَعۡلَمُوۡنَ ","40:11":"قَالُوۡا رَبَّنَاۤ اَمَتَّنَا اثۡنَتَیۡنِ وَاَحۡیَیۡتَنَا اثۡنَتَیۡنِ فَاعۡتَرَفۡنَا بِذُنُوۡبِنَا فَہَلۡ اِلٰی خُرُوۡجٍ مِّنۡ سَبِیۡلٍ ","40:19":"یَعۡلَمُ خَآئِنَۃَ الۡاَعۡیُنِ وَمَا تُخۡفِی الصُّدُوۡرُ ","40:26":"وَقَالَ فِرۡعَوۡنُ ذَرُوۡنِیۡۤ اَقۡتُلۡ مُوۡسٰی وَلۡیَدۡعُ رَبَّہٗ ۚ اِنِّیۡۤ اَخَافُ اَنۡ یُّبَدِّلَ دِیۡنَکُمۡ اَوۡ اَنۡ یُّظۡہِرَ فِی الۡاَرۡضِ الۡفَسَادَ ","40:27":"وَقَالَ مُوۡسٰۤی اِنِّیۡ عُذۡتُ بِرَبِّیۡ وَرَبِّکُمۡ مِّنۡ کُلِّ مُتَکَبِّرٍ لَّا یُؤۡمِنُ بِیَوۡمِ الۡحِسَابِ ٪ ","40:28":"وَقَالَ رَجُلٌ مُّؤۡمِنٌ ٭ۖ مِّنۡ اٰلِ فِرۡعَوۡنَ یَکۡتُمُ اِیۡمَانَہٗۤ اَتَقۡتُلُوۡنَ رَجُلًا اَنۡ یَّقُوۡلَ رَبِّیَ اللّٰہُ وَقَدۡ جَآءَکُمۡ بِالۡبَیِّنٰتِ مِنۡ رَّبِّکُمۡ ؕ وَاِنۡ یَّکُ کَاذِبًا فَعَلَیۡہِ کَذِبُہٗ ۚ وَاِنۡ یَّکُ صَادِقًا یُّصِبۡکُمۡ بَعۡضُ الَّذِیۡ یَعِدُکُمۡ ؕ اِنَّ اللّٰہَ لَا یَہۡدِیۡ مَنۡ ہُوَ مُسۡرِفٌ کَذَّابٌ ","40:29":"یٰقَوۡمِ لَکُمُ الۡمُلۡکُ الۡیَوۡمَ ظٰہِرِیۡنَ فِی الۡاَرۡضِ ۫ فَمَنۡ یَّنۡصُرُنَا مِنۡۢ بَاۡسِ اللّٰہِ اِنۡ جَآءَنَا ؕ قَالَ فِرۡعَوۡنُ مَاۤ اُرِیۡکُمۡ اِلَّا مَاۤ اَرٰی وَمَاۤ اَہۡدِیۡکُمۡ اِلَّا سَبِیۡلَ الرَّشَادِ ","41:5":"وَقَالُوۡا قُلُوۡبُنَا فِیۡۤ اَکِنَّۃٍ مِّمَّا تَدۡعُوۡنَاۤ اِلَیۡہِ وَفِیۡۤ اٰذَانِنَا وَقۡرٌ وَّمِنۡۢ بَیۡنِنَا وَبَیۡنِکَ حِجَابٌ فَاعۡمَلۡ اِنَّنَا عٰمِلُوۡنَ ؓ ","41:25":"وَقَیَّضۡنَا لَہُمۡ قُرَنَآءَ فَزَیَّنُوۡا لَہُمۡ مَّا بَیۡنَ اَیۡدِیۡہِمۡ وَمَا خَلۡفَہُمۡ وَحَقَّ عَلَیۡہِمُ الۡقَوۡلُ فِیۡۤ اُمَمٍ قَدۡ خَلَتۡ مِنۡ قَبۡلِہِمۡ مِّنَ الۡجِنِّ وَالۡاِنۡسِ ۚ اِنَّہُمۡ کَانُوۡا خٰسِرِیۡنَ ٪ ","41:29":"وَقَالَ الَّذِیۡنَ کَفَرُوۡا رَبَّنَاۤ اَرِنَا الَّذَیۡنِ اَضَلّٰنَا مِنَ الۡجِنِّ وَالۡاِنۡسِ نَجۡعَلۡہُمَا تَحۡتَ اَقۡدَامِنَا لِیَکُوۡنَا مِنَ الۡاَسۡفَلِیۡنَ ","41:36":"وَاِمَّا یَنۡزَغَنَّکَ مِنَ الشَّیۡطٰنِ نَزۡغٌ فَاسۡتَعِذۡ بِاللّٰہِ ؕ اِنَّہٗ ہُوَ السَّمِیۡعُ الۡعَلِیۡمُ ","41:44":"وَلَوۡ جَعَلۡنٰہُ قُرۡاٰنًا اَعۡجَمِیًّا لَّقَالُوۡا لَوۡلَا فُصِّلَتۡ اٰیٰتُہٗ ؕ ءَؔاَعۡجَمِیٌّ وَّعَرَبِیٌّ ؕ قُلۡ ہُوَ لِلَّذِیۡنَ اٰمَنُوۡا ہُدًی وَّشِفَآءٌ ؕ وَالَّذِیۡنَ لَا یُؤۡمِنُوۡنَ فِیۡۤ اٰذَانِہِمۡ وَقۡرٌ وَّہُوَ عَلَیۡہِمۡ عَمًی ؕ اُولٰٓئِکَ یُنَادَوۡنَ مِنۡ مَّکَانٍۭ بَعِیۡدٍ ٪ ","42:37":"وَالَّذِیۡنَ یَجۡتَنِبُوۡنَ کَبٰٓئِرَ الۡاِثۡمِ وَالۡفَوَاحِشَ وَاِذَا مَا غَضِبُوۡا ہُمۡ یَغۡفِرُوۡنَ ۚ ","43:11":"وَالَّذِیۡ نَزَّلَ مِنَ السَّمَآءِ مَآءًۢ بِقَدَرٍ ۚ فَاَنۡشَرۡنَا بِہٖ بَلۡدَۃً مَّیۡتًا ۚ کَذٰلِکَ تُخۡرَجُوۡنَ ","43:36":"وَمَنۡ یَّعۡشُ عَنۡ ذِکۡرِ الرَّحۡمٰنِ نُقَیِّضۡ لَہٗ شَیۡطٰنًا فَہُوَ لَہٗ قَرِیۡنٌ ","43:37":"وَاِنَّہُمۡ لَیَصُدُّوۡنَہُمۡ عَنِ السَّبِیۡلِ وَیَحۡسَبُوۡنَ اَنَّہُمۡ مُّہۡتَدُوۡنَ ","43:38":"حَتّٰۤی اِذَا جَآءَنَا قَالَ یٰلَیۡتَ بَیۡنِیۡ وَبَیۡنَکَ بُعۡدَ الۡمَشۡرِقَیۡنِ فَبِئۡسَ الۡقَرِیۡنُ ","44:44":"طَعَامُ الۡاَثِیۡمِ ۖۛۚ","44:48":"ثُمَّ صُبُّوۡا فَوۡقَ رَاۡسِہٖ مِنۡ عَذَابِ الۡحَمِیۡمِ ؕ ","45:23":"اَفَرَءَیۡتَ مَنِ اتَّخَذَ اِلٰـہَہٗ ہَوٰىہُ وَاَضَلَّہُ اللّٰہُ عَلٰی عِلۡمٍ وَّخَتَمَ عَلٰی سَمۡعِہٖ وَقَلۡبِہٖ وَجَعَلَ عَلٰی بَصَرِہٖ غِشٰوَۃً ؕ فَمَنۡ یَّہۡدِیۡہِ مِنۡۢ بَعۡدِ اللّٰہِ ؕ اَفَلَا تَذَکَّرُوۡنَ ","46:20":"وَیَوۡمَ یُعۡرَضُ الَّذِیۡنَ کَفَرُوۡا عَلَی النَّارِ ؕ اَذۡہَبۡتُمۡ طَیِّبٰتِکُمۡ فِیۡ حَیَاتِکُمُ الدُّنۡیَا وَاسۡتَمۡتَعۡتُمۡ بِہَا ۚ فَالۡیَوۡمَ تُجۡزَوۡنَ عَذَابَ الۡہُوۡنِ بِمَا کُنۡتُمۡ تَسۡتَکۡبِرُوۡنَ فِی الۡاَرۡضِ بِغَیۡرِ الۡحَقِّ وَبِمَا کُنۡتُمۡ تَفۡسُقُوۡنَ ٪ ","46:29":"وَاِذۡ صَرَفۡنَاۤ اِلَیۡکَ نَفَرًا مِّنَ الۡجِنِّ یَسۡتَمِعُوۡنَ الۡقُرۡاٰنَ ۚ فَلَمَّا حَضَرُوۡہُ قَالُوۡۤا اَنۡصِتُوۡا ۚ فَلَمَّا قُضِیَ وَلَّوۡا اِلٰی قَوۡمِہِمۡ مُّنۡذِرِیۡنَ ","46:30":"قَالُوۡا یٰقَوۡمَنَاۤ اِنَّا سَمِعۡنَا کِتٰبًا اُنۡزِلَ مِنۡۢ بَعۡدِ مُوۡسٰی مُصَدِّقًا لِّمَا بَیۡنَ یَدَیۡہِ یَہۡدِیۡۤ اِلَی الۡحَقِّ وَاِلٰی طَرِیۡقٍ مُّسۡتَقِیۡمٍ ","46:31":"یٰقَوۡمَنَاۤ اَجِیۡبُوۡا دَاعِیَ اللّٰہِ وَاٰمِنُوۡا بِہٖ یَغۡفِرۡ لَکُمۡ مِّنۡ ذُنُوۡبِکُمۡ وَیُجِرۡکُمۡ مِّنۡ عَذَابٍ اَلِیۡمٍ ","46:32":"وَمَنۡ لَّا یُجِبۡ دَاعِیَ اللّٰہِ فَلَیۡسَ بِمُعۡجِزٍ فِی الۡاَرۡضِ وَلَیۡسَ لَہٗ مِنۡ دُوۡنِہٖۤ اَوۡلِیَآءُ ؕ اُولٰٓئِکَ فِیۡ ضَلٰلٍ مُّبِیۡنٍ ","47:4":"فَاِذَا لَقِیۡتُمُ الَّذِیۡنَ کَفَرُوۡا فَضَرۡبَ الرِّقَابِ ؕ حَتّٰۤی اِذَاۤ اَثۡخَنۡتُمُوۡہُمۡ فَشُدُّوا الۡوَثَاقَ ٭ۙ فَاِمَّا مَنًّۢا بَعۡدُ وَاِمَّا فِدَآءً حَتّٰی تَضَعَ الۡحَرۡبُ اَوۡزَارَہَا ۬ۚ۟ۛ ذٰؔلِکَ ؕۛ وَلَوۡ یَشَآءُ اللّٰہُ لَانۡتَصَرَ مِنۡہُمۡ وَلٰکِنۡ لِّیَبۡلُوَا۠ بَعۡضَکُمۡ بِبَعۡضٍ ؕ وَالَّذِیۡنَ قُتِلُوۡا فِیۡ سَبِیۡلِ اللّٰہِ فَلَنۡ یُّضِلَّ اَعۡمَالَہُمۡ ","47:12":"اِنَّ اللّٰہَ یُدۡخِلُ الَّذِیۡنَ اٰمَنُوۡا وَعَمِلُوا الصّٰلِحٰتِ جَنّٰتٍ تَجۡرِیۡ مِنۡ تَحۡتِہَا الۡاَنۡہٰرُ ؕ وَالَّذِیۡنَ کَفَرُوۡا یَتَمَتَّعُوۡنَ وَیَاۡکُلُوۡنَ کَمَا تَاۡکُلُ الۡاَنۡعَامُ وَالنَّارُ مَثۡوًی لَّہُمۡ ","47:13":"وَکَاَیِّنۡ مِّنۡ قَرۡیَۃٍ ہِیَ اَشَدُّ قُوَّۃً مِّنۡ قَرۡیَتِکَ الَّتِیۡۤ اَخۡرَجَتۡکَ ۚ اَہۡلَکۡنٰہُمۡ فَلَا نَاصِرَ لَہُمۡ ","47:15":"مَثَلُ الۡجَنَّۃِ الَّتِیۡ وُعِدَ الۡمُتَّقُوۡنَ ؕ فِیۡہَاۤ اَنۡہٰرٌ مِّنۡ مَّآءٍ غَیۡرِ اٰسِنٍ ۚ وَاَنۡہٰرٌ مِّنۡ لَّبَنٍ لَّمۡ یَتَغَیَّرۡ طَعۡمُہٗ ۚ وَاَنۡہٰرٌ مِّنۡ خَمۡرٍ لَّذَّۃٍ لِّلشّٰرِبِیۡنَ ۬ۚ وَاَنۡہٰرٌ مِّنۡ عَسَلٍ مُّصَفًّی ؕ وَلَہُمۡ فِیۡہَا مِنۡ کُلِّ الثَّمَرٰتِ وَمَغۡفِرَۃٌ مِّنۡ رَّبِّہِمۡ ؕ کَمَنۡ ہُوَ خَالِدٌ فِی النَّارِ وَسُقُوۡا مَآءً حَمِیۡمًا فَقَطَّعَ اَمۡعَآءَہُمۡ ","47:20":"وَیَقُوۡلُ الَّذِیۡنَ اٰمَنُوۡا لَوۡلَا نُزِّلَتۡ سُوۡرَۃٌ ۚ فَاِذَاۤ اُنۡزِلَتۡ سُوۡرَۃٌ مُّحۡکَمَۃٌ وَّذُکِرَ فِیۡہَا الۡقِتَالُ ۙ رَاَیۡتَ الَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ یَّنۡظُرُوۡنَ اِلَیۡکَ نَظَرَ الۡمَغۡشِیِّ عَلَیۡہِ مِنَ الۡمَوۡتِ ؕ فَاَوۡلٰی لَہُمۡ ۚ ","47:25":"اِنَّ الَّذِیۡنَ ارۡتَدُّوۡا عَلٰۤی اَدۡبَارِہِمۡ مِّنۡۢ بَعۡدِ مَا تَبَیَّنَ لَہُمُ الۡہُدَی ۙ الشَّیۡطٰنُ سَوَّلَ لَہُمۡ ؕ وَاَمۡلٰی لَہُمۡ ","47:29":"اَمۡ حَسِبَ الَّذِیۡنَ فِیۡ قُلُوۡبِہِمۡ مَّرَضٌ اَنۡ لَّنۡ یُّخۡرِجَ اللّٰہُ اَضۡغَانَہُمۡ ","48:4":"ہُوَ الَّذِیۡۤ اَنۡزَلَ السَّکِیۡنَۃَ فِیۡ قُلُوۡبِ الۡمُؤۡمِنِیۡنَ لِیَزۡدَادُوۡۤا اِیۡمَانًا مَّعَ اِیۡمَانِہِمۡ ؕ وَلِلّٰہِ جُنُوۡدُ السَّمٰوٰتِ وَالۡاَرۡضِ ؕ وَکَانَ اللّٰہُ عَلِیۡمًا حَکِیۡمًا ۙ ","48:18":"لَقَدۡ رَضِیَ اللّٰہُ عَنِ الۡمُؤۡمِنِیۡنَ اِذۡ یُبَایِعُوۡنَکَ تَحۡتَ الشَّجَرَۃِ فَعَلِمَ مَا فِیۡ قُلُوۡبِہِمۡ فَاَنۡزَلَ السَّکِیۡنَۃَ عَلَیۡہِمۡ وَاَثَابَہُمۡ فَتۡحًا قَرِیۡبًا ۙ ","48:21":"وَّاُخۡرٰی لَمۡ تَقۡدِرُوۡا عَلَیۡہَا قَدۡ اَحَاطَ اللّٰہُ بِہَا ؕ وَکَانَ اللّٰہُ عَلٰی کُلِّ شَیۡءٍ قَدِیۡرًا ","48:22":"وَلَوۡ قٰتَلَکُمُ الَّذِیۡنَ کَفَرُوۡا لَوَلَّوُا الۡاَدۡبَارَ ثُمَّ لَا یَجِدُوۡنَ وَلِیًّا وَّلَا نَصِیۡرًا ","48:26":"اِذۡ جَعَلَ الَّذِیۡنَ کَفَرُوۡا فِیۡ قُلُوۡبِہِمُ الۡحَمِیَّۃَ حَمِیَّۃَ الۡجَاہِلِیَّۃِ فَاَنۡزَلَ اللّٰہُ سَکِیۡنَتَہٗ عَلٰی رَسُوۡلِہٖ وَعَلَی الۡمُؤۡمِنِیۡنَ وَاَلۡزَمَہُمۡ کَلِمَۃَ التَّقۡوٰی وَکَانُوۡۤا اَحَقَّ بِہَا وَاَہۡلَہَا ؕ وَکَانَ اللّٰہُ بِکُلِّ شَیۡءٍ عَلِیۡمًا ٪ ","50:6":"اَفَلَمۡ یَنۡظُرُوۡۤا اِلَی السَّمَآءِ فَوۡقَہُمۡ کَیۡفَ بَنَیۡنٰہَا وَزَیَّنّٰہَا وَمَا لَہَا مِنۡ فُرُوۡجٍ ","50:42":"یَّوۡمَ یَسۡمَعُوۡنَ الصَّیۡحَۃَ بِالۡحَقِّ ؕ ذٰلِکَ یَوۡمُ الۡخُرُوۡجِ ","51:35":"فَاَخۡرَجۡنَا مَنۡ کَانَ فِیۡہَا مِنَ الۡمُؤۡمِنِیۡنَ ۚ ","51:44":"فَعَتَوۡا عَنۡ اَمۡرِ رَبِّہِمۡ فَاَخَذَتۡہُمُ الصّٰعِقَۃُ وَہُمۡ یَنۡظُرُوۡنَ ","51:56":"وَمَا خَلَقۡتُ الۡجِنَّ وَالۡاِنۡسَ اِلَّا لِیَعۡبُدُوۡنِ ","51:57":"مَاۤ اُرِیۡدُ مِنۡہُمۡ مِّنۡ رِّزۡقٍ وَّمَاۤ اُرِیۡدُ اَنۡ یُّطۡعِمُوۡنِ ","51:58":"اِنَّ اللّٰہَ ہُوَ الرَّزَّاقُ ذُو الۡقُوَّۃِ الۡمَتِیۡنُ ","53:32":"اَلَّذِیۡنَ یَجۡتَنِبُوۡنَ کَبٰٓئِرَ الۡاِثۡمِ وَالۡفَوَاحِشَ اِلَّا اللَّمَمَ ؕ اِنَّ رَبَّکَ وَاسِعُ الۡمَغۡفِرَۃِ ؕ ہُوَ اَعۡلَمُ بِکُمۡ اِذۡ اَنۡشَاَکُمۡ مِّنَ الۡاَرۡضِ وَاِذۡ اَنۡتُمۡ اَجِنَّۃٌ فِیۡ بُطُوۡنِ اُمَّہٰتِکُمۡ ۚ فَلَا تُزَکُّوۡۤا اَنۡفُسَکُمۡ ؕ ہُوَ اَعۡلَمُ بِمَنِ اتَّقٰی ٪","54:7":"خُشَّعًا اَبۡصَارُہُمۡ یَخۡرُجُوۡنَ مِنَ الۡاَجۡدَاثِ کَاَنَّہُمۡ جَرَادٌ مُّنۡتَشِرٌ ۙ ","54:12":"وَّفَجَّرۡنَا الۡاَرۡضَ عُیُوۡنًا فَالۡتَقَی الۡمَآءُ عَلٰۤی اَمۡرٍ قَدۡ قُدِرَ ۚ ","54:37":"وَلَقَدۡ رَاوَدُوۡہُ عَنۡ ضَیۡفِہٖ فَطَمَسۡنَاۤ اَعۡیُنَہُمۡ فَذُوۡقُوۡا عَذَابِیۡ وَنُذُرِ ","54:54":"اِنَّ الۡمُتَّقِیۡنَ فِیۡ جَنّٰتٍ وَّنَہَرٍ ۙ ","55:1":"اَلرَّحۡمٰنُ ۙ ","55:2":"عَلَّمَ الۡقُرۡاٰنَ ؕ ","55:3":"خَلَقَ الۡاِنۡسَانَ ۙ ","55:4":"عَلَّمَہُ الۡبَیَانَ ","55:14":"خَلَقَ الۡاِنۡسَانَ مِنۡ صَلۡصَالٍ کَالۡفَخَّارِ ۙ ","55:15":"وَخَلَقَ الۡجَآنَّ مِنۡ مَّارِجٍ مِّنۡ نَّارٍ ۚ ","55:20":"بَیۡنَہُمَا بَرۡزَخٌ لَّا یَبۡغِیٰنِ ۚ ","55:22":"یَخۡرُجُ مِنۡہُمَا اللُّؤۡلُؤُ وَالۡمَرۡجَانُ ۚ ","55:33":"یٰمَعۡشَرَ الۡجِنِّ وَالۡاِنۡسِ اِنِ اسۡتَطَعۡتُمۡ اَنۡ تَنۡفُذُوۡا مِنۡ اَقۡطَارِ السَّمٰوٰتِ وَالۡاَرۡضِ فَانۡفُذُوۡا ؕ لَا تَنۡفُذُوۡنَ اِلَّا بِسُلۡطٰنٍ ۚ ","55:66":"فِیۡہِمَا عَیۡنٰنِ نَضَّاخَتٰنِ ۚ ","55:72":"حُوۡرٌ مَّقۡصُوۡرٰتٌ فِی الۡخِیَامِ ۚ ","56:47":"وَکَانُوۡا یَقُوۡلُوۡنَ ۬ۙ اَئِذَا مِتۡنَا وَکُنَّا تُرَابًا وَّعِظَامًا ءَاِنَّا لَمَبۡعُوۡثُوۡنَ ۙ ","56:51":"ثُمَّ اِنَّکُمۡ اَیُّہَا الضَّآلُّوۡنَ الۡمُکَذِّبُوۡنَ ۙ ","56:53":"فَمَالِـُٔوۡنَ مِنۡہَا الۡبُطُوۡنَ ۚ ","56:83":"فَلَوۡلَاۤ اِذَا بَلَغَتِ الۡحُلۡقُوۡمَ ۙ ","56:84":"وَاَنۡتُمۡ حِیۡنَئِذٍ تَنۡظُرُوۡنَ ۙ ","57:13":"یَوۡمَ یَقُوۡلُ الۡمُنٰفِقُوۡنَ وَالۡمُنٰفِقٰتُ لِلَّذِیۡنَ اٰمَنُوا انۡظُرُوۡنَا نَقۡتَبِسۡ مِنۡ نُّوۡرِکُمۡ ۚ قِیۡلَ ارۡجِعُوۡا وَرَآءَکُمۡ فَالۡتَمِسُوۡا نُوۡرًا ؕ فَضُرِبَ بَیۡنَہُمۡ بِسُوۡرٍ لَّہٗ بَابٌ ؕ بَاطِنُہٗ فِیۡہِ الرَّحۡمَۃُ وَظَاہِرُہٗ مِنۡ قِبَلِہِ الۡعَذَابُ ؕ","58:19":"اِسۡتَحۡوَذَ عَلَیۡہِمُ الشَّیۡطٰنُ فَاَنۡسٰہُمۡ ذِکۡرَ اللّٰہِ ؕ اُولٰٓئِکَ حِزۡبُ الشَّیۡطٰنِ ؕ اَلَاۤ اِنَّ حِزۡبَ الشَّیۡطٰنِ ہُمُ الۡخٰسِرُوۡنَ ","59:2":"ہُوَ الَّذِیۡۤ اَخۡرَجَ الَّذِیۡنَ کَفَرُوۡا مِنۡ اَہۡلِ الۡکِتٰبِ مِنۡ دِیَارِہِمۡ لِاَوَّلِ الۡحَشۡرِ ؕؔ مَا ظَنَنۡتُمۡ اَنۡ یَّخۡرُجُوۡا وَظَنُّوۡۤا اَنَّہُمۡ مَّانِعَتُہُمۡ حُصُوۡنُہُمۡ مِّنَ اللّٰہِ فَاَتٰىہُمُ اللّٰہُ مِنۡ حَیۡثُ لَمۡ یَحۡتَسِبُوۡا ٭ وَقَذَفَ فِیۡ قُلُوۡبِہِمُ الرُّعۡبَ یُخۡرِبُوۡنَ بُیُوۡتَہُمۡ بِاَیۡدِیۡہِمۡ وَاَیۡدِی الۡمُؤۡمِنِیۡنَ ٭ فَاعۡتَبِرُوۡا یٰۤاُولِی الۡاَبۡصَارِ ","59:16":"کَمَثَلِ الشَّیۡطٰنِ اِذۡ قَالَ لِلۡاِنۡسَانِ اکۡفُرۡ ۚ فَلَمَّا کَفَرَ قَالَ اِنِّیۡ بَرِیۡٓءٌ مِّنۡکَ اِنِّیۡۤ اَخَافُ اللّٰہَ رَبَّ الۡعٰلَمِیۡنَ ","59:17":"فَکَانَ عَاقِبَتَہُمَاۤ اَنَّہُمَا فِی النَّارِ خَالِدَیۡنِ فِیۡہَا ؕ وَذٰلِکَ جَزٰٓؤُا الظّٰلِمِیۡنَ ٪ ","59:21":"لَوۡ اَنۡزَلۡنَا ہٰذَا الۡقُرۡاٰنَ عَلٰی جَبَلٍ لَّرَاَیۡتَہٗ خَاشِعًا مُّتَصَدِّعًا مِّنۡ خَشۡیَۃِ اللّٰہِ ؕ وَتِلۡکَ الۡاَمۡثَالُ نَضۡرِبُہَا لِلنَّاسِ لَعَلَّہُمۡ یَتَفَکَّرُوۡنَ ","59:23":"ہُوَ اللّٰہُ الَّذِیۡ لَاۤ اِلٰہَ اِلَّا ہُوَ ۚ اَلۡمَلِکُ الۡقُدُّوۡسُ السَّلٰمُ الۡمُؤۡمِنُ الۡمُہَیۡمِنُ الۡعَزِیۡزُ الۡجَبَّارُ الۡمُتَکَبِّرُ ؕ سُبۡحٰنَ اللّٰہِ عَمَّا یُشۡرِکُوۡنَ ","59:24":"ہُوَ اللّٰہُ الۡخَالِقُ الۡبَارِئُ الۡمُصَوِّرُ لَہُ الۡاَسۡمَآءُ الۡحُسۡنٰی ؕ یُسَبِّحُ لَہٗ مَا فِی السَّمٰوٰتِ وَالۡاَرۡضِ ۚ وَہُوَ الۡعَزِیۡزُ الۡحَکِیۡمُ ٪","63:8":"یَقُوۡلُوۡنَ لَئِنۡ رَّجَعۡنَاۤ اِلَی الۡمَدِیۡنَۃِ لَیُخۡرِجَنَّ الۡاَعَزُّ مِنۡہَا الۡاَذَلَّ ؕ وَلِلّٰہِ الۡعِزَّۃُ وَلِرَسُوۡلِہٖ وَلِلۡمُؤۡمِنِیۡنَ وَلٰکِنَّ الۡمُنٰفِقِیۡنَ لَا یَعۡلَمُوۡنَ ٪ ","65:1":"یٰۤاَیُّہَا النَّبِیُّ اِذَا طَلَّقۡتُمُ النِّسَآءَ فَطَلِّقُوۡہُنَّ لِعِدَّتِہِنَّ وَاَحۡصُوا الۡعِدَّۃَ ۚ وَاتَّقُوا اللّٰہَ رَبَّکُمۡ ۚ لَا تُخۡرِجُوۡہُنَّ مِنۡۢ بُیُوۡتِہِنَّ وَلَا یَخۡرُجۡنَ اِلَّاۤ اَنۡ یَّاۡتِیۡنَ بِفَاحِشَۃٍ مُّبَیِّنَۃٍ ؕ وَتِلۡکَ حُدُوۡدُ اللّٰہِ ؕ وَمَنۡ یَّتَعَدَّ حُدُوۡدَ اللّٰہِ فَقَدۡ ظَلَمَ نَفۡسَہٗ ؕ لَا تَدۡرِیۡ لَعَلَّ اللّٰہَ یُحۡدِثُ بَعۡدَ ذٰلِکَ اَمۡرًا ","65:2":"فَاِذَا بَلَغۡنَ اَجَلَہُنَّ فَاَمۡسِکُوۡہُنَّ بِمَعۡرُوۡفٍ اَوۡ فَارِقُوۡہُنَّ بِمَعۡرُوۡفٍ وَّاَشۡہِدُوۡا ذَوَیۡ عَدۡلٍ مِّنۡکُمۡ وَاَقِیۡمُوا الشَّہَادَۃَ لِلّٰہِ ؕ ذٰلِکُمۡ یُوۡعَظُ بِہٖ مَنۡ کَانَ یُؤۡمِنُ بِاللّٰہِ وَالۡیَوۡمِ الۡاٰخِرِ ۬ؕ وَمَنۡ یَّتَّقِ اللّٰہَ یَجۡعَلۡ لَّہٗ مَخۡرَجًا ۙ ","66:12":"وَمَرۡیَمَ ابۡنَتَ عِمۡرٰنَ الَّتِیۡۤ اَحۡصَنَتۡ فَرۡجَہَا فَنَفَخۡنَا فِیۡہِ مِنۡ رُّوۡحِنَا وَصَدَّقَتۡ بِکَلِمٰتِ رَبِّہَا وَکُتُبِہٖ وَکَانَتۡ مِنَ الۡقٰنِتِیۡنَ ٪ ","67:3":"الَّذِیۡ خَلَقَ سَبۡعَ سَمٰوٰتٍ طِبَاقًا ؕ مَا تَرٰی فِیۡ خَلۡقِ الرَّحۡمٰنِ مِنۡ تَفٰوُتٍ ؕ فَارۡجِعِ الۡبَصَرَ ۙ ہَلۡ تَرٰی مِنۡ فُطُوۡرٍ ","67:5":"وَلَقَدۡ زَیَّنَّا السَّمَآءَ الدُّنۡیَا بِمَصَابِیۡحَ وَجَعَلۡنٰہَا رُجُوۡمًا لِّلشَّیٰطِیۡنِ وَاَعۡتَدۡنَا لَہُمۡ عَذَابَ السَّعِیۡرِ ","68:50":"فَاجۡتَبٰہُ رَبُّہٗ فَجَعَلَہٗ مِنَ الصّٰلِحِیۡنَ ","68:51":"وَاِنۡ یَّکَادُ الَّذِیۡنَ کَفَرُوۡا لَیُزۡلِقُوۡنَکَ بِاَبۡصَارِہِمۡ لَمَّا سَمِعُوا الذِّکۡرَ وَیَقُوۡلُوۡنَ اِنَّہٗ لَمَجۡنُوۡنٌ ۘ","70:43":"یَوۡمَ یَخۡرُجُوۡنَ مِنَ الۡاَجۡدَاثِ سِرَاعًا کَاَنَّہُمۡ اِلٰی نُصُبٍ یُّوۡفِضُوۡنَ ۙ ","71:18":"ثُمَّ یُعِیۡدُکُمۡ فِیۡہَا وَیُخۡرِجُکُمۡ اِخۡرَاجًا ","72:1":"قُلۡ اُوۡحِیَ اِلَیَّ اَنَّہُ اسۡتَمَعَ نَفَرٌ مِّنَ الۡجِنِّ فَقَالُوۡۤا اِنَّا سَمِعۡنَا قُرۡاٰنًا عَجَبًا ۙ ","72:2":"یَّہۡدِیۡۤ اِلَی الرُّشۡدِ فَاٰمَنَّا بِہٖ ؕ وَلَنۡ نُّشۡرِکَ بِرَبِّنَاۤ اَحَدًا ۙ ","72:3":"وَّاَنَّہٗ تَعٰلٰی جَدُّ رَبِّنَا مَا اتَّخَذَ صَاحِبَۃً وَّلَا وَلَدًا ۙ ","72:4":"وَّاَنَّہٗ کَانَ یَقُوۡلُ سَفِیۡہُنَا عَلَی اللّٰہِ شَطَطًا ۙ ","72:5":"وَّاَنَّا ظَنَنَّاۤ اَنۡ لَّنۡ تَقُوۡلَ الۡاِنۡسُ وَالۡجِنُّ عَلَی اللّٰہِ کَذِبًا ۙ ","72:6":"وَّاَنَّہٗ کَانَ رِجَالٌ مِّنَ الۡاِنۡسِ یَعُوۡذُوۡنَ بِرِجَالٍ مِّنَ الۡجِنِّ فَزَادُوۡہُمۡ رَہَقًا ۙ ","72:7":"وَّاَنَّہُمۡ ظَنُّوۡا کَمَا ظَنَنۡتُمۡ اَنۡ لَّنۡ یَّبۡعَثَ اللّٰہُ اَحَدًا ۙ ","72:8":"وَّاَنَّا لَمَسۡنَا السَّمَآءَ فَوَجَدۡنٰہَا مُلِئَتۡ حَرَسًا شَدِیۡدًا وَّشُہُبًا ۙ ","72:9":"وَّاَنَّا کُنَّا نَقۡعُدُ مِنۡہَا مَقَاعِدَ لِلسَّمۡعِ ؕ فَمَنۡ یَّسۡتَمِعِ الۡاٰنَ یَجِدۡ لَہٗ شِہَابًا رَّصَدًا ۙ ","72:10":"وَّاَنَّا لَا نَدۡرِیۡۤ اَشَرٌّ اُرِیۡدَ بِمَنۡ فِی الۡاَرۡضِ اَمۡ اَرَادَ بِہِمۡ رَبُّہُمۡ رَشَدًا ۙ ","72:11":"وَّاَنَّا مِنَّا الصّٰلِحُوۡنَ وَمِنَّا دُوۡنَ ذٰلِکَ ؕ کُنَّا طَرَآئِقَ قِدَدًا ۙ ","72:12":"وَّاَنَّا ظَنَنَّاۤ اَنۡ لَّنۡ نُّعۡجِزَ اللّٰہَ فِی الۡاَرۡضِ وَلَنۡ نُّعۡجِزَہٗ ہَرَبًا ۙ ","72:13":"وَّاَنَّا لَمَّا سَمِعۡنَا الۡہُدٰۤی اٰمَنَّا بِہٖ ؕ فَمَنۡ یُّؤۡمِنۡۢ بِرَبِّہٖ فَلَا یَخَافُ بَخۡسًا وَّلَا رَہَقًا ۙ ","72:14":"وَّاَنَّا مِنَّا الۡمُسۡلِمُوۡنَ وَمِنَّا الۡقٰسِطُوۡنَ ؕ فَمَنۡ اَسۡلَمَ فَاُولٰٓئِکَ تَحَرَّوۡا رَشَدًا ","72:15":"وَاَمَّا الۡقٰسِطُوۡنَ فَکَانُوۡا لِجَہَنَّمَ حَطَبًا ۙ ","72:17":"لِّنَفۡتِنَہُمۡ فِیۡہِ ؕ وَمَنۡ یُّعۡرِضۡ عَنۡ ذِکۡرِ رَبِّہٖ یَسۡلُکۡہُ عَذَابًا صَعَدًا ۙ ","72:18":"وَّاَنَّ الۡمَسٰجِدَ لِلّٰہِ فَلَا تَدۡعُوۡا مَعَ اللّٰہِ اَحَدًا ۙ ","72:19":"وَّاَنَّہٗ لَمَّا قَامَ عَبۡدُ اللّٰہِ یَدۡعُوۡہُ کَادُوۡا یَکُوۡنُوۡنَ عَلَیۡہِ لِبَدًا ؕ٪ ","72:20":"قُلۡ اِنَّمَاۤ اَدۡعُوۡا رَبِّیۡ وَلَاۤ اُشۡرِکُ بِہٖۤ اَحَدًا ","72:21":"قُلۡ اِنِّیۡ لَاۤ اَمۡلِکُ لَکُمۡ ضَرًّا وَّلَا رَشَدًا ","72:22":"قُلۡ اِنِّیۡ لَنۡ یُّجِیۡرَنِیۡ مِنَ اللّٰہِ اَحَدٌ ۬ۙ وَّلَنۡ اَجِدَ مِنۡ دُوۡنِہٖ مُلۡتَحَدًا ۙ ","72:23":"اِلَّا بَلٰغًا مِّنَ اللّٰہِ وَرِسٰلٰتِہٖ ؕ وَمَنۡ یَّعۡصِ اللّٰہَ وَرَسُوۡلَہٗ فَاِنَّ لَہٗ نَارَ جَہَنَّمَ خٰلِدِیۡنَ فِیۡہَاۤ اَبَدًا ؕ ","72:24":"حَتّٰۤی اِذَا رَاَوۡا مَا یُوۡعَدُوۡنَ فَسَیَعۡلَمُوۡنَ مَنۡ اَضۡعَفُ نَاصِرًا وَّاَقَلُّ عَدَدًا ","72:25":"قُلۡ اِنۡ اَدۡرِیۡۤ اَقَرِیۡبٌ مَّا تُوۡعَدُوۡنَ اَمۡ یَجۡعَلُ لَہٗ رَبِّیۡۤ اَمَدًا ","72:26":"عٰلِمُ الۡغَیۡبِ فَلَا یُظۡہِرُ عَلٰی غَیۡبِہٖۤ اَحَدًا ۙ ","72:27":"اِلَّا مَنِ ارۡتَضٰی مِنۡ رَّسُوۡلٍ فَاِنَّہٗ یَسۡلُکُ مِنۡۢ بَیۡنِ یَدَیۡہِ وَمِنۡ خَلۡفِہٖ رَصَدًا ۙ ","72:28":"لِّیَعۡلَمَ اَنۡ قَدۡ اَبۡلَغُوۡا رِسٰلٰتِ رَبِّہِمۡ وَاَحَاطَ بِمَا لَدَیۡہِمۡ وَاَحۡصٰی کُلَّ شَیۡءٍ عَدَدًا ٪ ","75:3":"اَیَحۡسَبُ الۡاِنۡسَانُ اَلَّنۡ نَّجۡمَعَ عِظَامَہٗ ؕ ","75:8":"وَخَسَفَ الۡقَمَرُ ۙ ","75:10":"یَقُوۡلُ الۡاِنۡسَانُ یَوۡمَئِذٍ اَیۡنَ الۡمَفَرُّ ۚ ","76:6":"عَیۡنًا یَّشۡرَبُ بِہَا عِبَادُ اللّٰہِ یُفَجِّرُوۡنَہَا تَفۡجِیۡرًا ","76:18":"عَیۡنًا فِیۡہَا تُسَمّٰی سَلۡسَبِیۡلًا ","77:46":"کُلُوۡا وَتَمَتَّعُوۡا قَلِیۡلًا اِنَّکُمۡ مُّجۡرِمُوۡنَ ","79:6":"یَوۡمَ تَرۡجُفُ الرَّاجِفَۃُ ۙ ","79:11":"ءَاِذَا کُنَّا عِظَامًا نَّخِرَۃً ؕ","85:10":"اِنَّ الَّذِیۡنَ فَتَنُوا الۡمُؤۡمِنِیۡنَ وَالۡمُؤۡمِنٰتِ ثُمَّ لَمۡ یَتُوۡبُوۡا فَلَہُمۡ عَذَابُ جَہَنَّمَ وَلَہُمۡ عَذَابُ الۡحَرِیۡقِ ؕ ","86:7":"یَّخۡرُجُ مِنۡۢ بَیۡنِ الصُّلۡبِ وَالتَّرَآئِبِ ؕ ","90:5":"اَیَحۡسَبُ اَنۡ لَّنۡ یَّقۡدِرَ عَلَیۡہِ اَحَدٌ ۘ","90:7":"اَیَحۡسَبُ اَنۡ لَّمۡ یَرَہٗۤ اَحَدٌ ؕ ","90:8":"اَلَمۡ نَجۡعَلۡ لَّہٗ عَیۡنَیۡنِ ۙ ","92:15":"لَا یَصۡلٰىہَاۤ اِلَّا الۡاَشۡقَی ۙ ","99:2":"وَاَخۡرَجَتِ الۡاَرۡضُ اَثۡقَالَہَا ۙ ","104:9":"فِیۡ عَمَدٍ مُّمَدَّدَۃٍ ٪ ","112:1":"قُلۡ ہُوَ اللّٰہُ اَحَدٌ ۚ","112:2":"اَللّٰہُ الصَّمَدُ ۚ ","112:3":"لَمۡ یَلِدۡ ۬ۙ وَلَمۡ یُوۡلَدۡ ۙ ","112:4":"وَلَمۡ یَکُنۡ لَّہٗ کُفُوًا اَحَدٌ ٪ ","113:1":"قُلۡ اَعُوۡذُ بِرَبِّ الۡفَلَقِ ۙ ","113:2":"مِنۡ شَرِّ مَا خَلَقَ ۙ ","113:3":"وَمِنۡ شَرِّ غَاسِقٍ اِذَا وَقَبَ ۙ ","113:4":"وَمِنۡ شَرِّ النَّفّٰثٰتِ فِی الۡعُقَدِ ۙ ","113:5":"وَمِنۡ شَرِّ حَاسِدٍ اِذَا حَسَدَ ٪ ","114:1":"قُلۡ اَعُوۡذُ بِرَبِّ النَّاسِ ۙ ","114:2":"مَلِکِ النَّاسِ ۙ ","114:3":"اِلٰہِ النَّاسِ ۙ ","114:4":"مِنۡ شَرِّ الۡوَسۡوَاسِ ۬ۙ الۡخَنَّاسِ ۪ۙ ","114:5":"الَّذِیۡ یُوَسۡوِسُ فِیۡ صُدُوۡرِ النَّاسِ ۙ ","114:6":"مِنَ الۡجِنَّۃِ وَالنَّاسِ ٪ "};
